  private val prefs: SecurePrefs,
  savedStateHandle: SavedStateHandle,
  private val resolveShareMimeType: (Uri) -> String?,
  shareLaunchCapacity: Int,
) : AndroidViewModel(app) {
  constructor(
    app: Application,
    savedStateHandle: SavedStateHandle,
  ) : this(
    app = app,
