private const val GROUP_MEMBER_FETCH_LIMIT = 10_000
private const val FULL_MESSAGE_TEXT_MAX_CHARS = 1_000_000

internal fun isCurrentHistoryLoad(
  requestedSessionKey: String,
  currentSessionKey: String,
