/**
 * CameraX-backed capture service used by gateway camera commands.
 */
internal class CameraClipSession(
  private val unbind: () -> Unit,
  private val deleteTemporaryFile: (File) -> Unit,
) : AutoCloseable {
  private var recording: AutoCloseable? = null
  private var temporaryFile: File? = null
  private var closed = false

  fun ownRecording(recording: AutoCloseable) {
    check(!closed) { "camera clip session is closed" }
    this.recording = recording
  }

  fun ownFile(file: File): File {
    check(!closed) { "camera clip session is closed" }
    check(temporaryFile == null) { "camera clip session already owns a file" }
    temporaryFile = file
    return file
  }

  fun transferFile(onTransfer: (File) -> Unit): File {
    check(!closed) { "camera clip session is closed" }
    return checkNotNull(temporaryFile) { "camera clip session has no file" }
      .also { file ->
        // Claim ownership before release because cancellation can discard a dispatched FilePayload.
        onTransfer(file)
        temporaryFile = null
      }
  }

  override fun close() {
    if (closed) return
    closed = true

    var failure: Throwable? = null

    fun cleanup(action: () -> Unit) {
      try {
        action()
      } catch (err: Throwable) {
        failure?.addSuppressed(err) ?: run { failure = err }
      }
    }

    // Keep teardown symmetric across bind, warmup, recording, finalize, and success exits.
    cleanup { recording?.close() }
    cleanup(unbind)
    temporaryFile?.let { file -> cleanup { deleteTemporaryFile(file) } }
    failure?.let { throw it }
  }
}

class CameraCaptureManager(
  private val context: Context,
  private val defaultFacing: () -> String = { "front" },
) {
  /** Base64 JSON response for camera.snap after resize and JPEG budget enforcement. */
  data class Payload(
    val payloadJson: String,
  )

  /** Temporary MP4 response for camera.clip before CameraHandler validates invoke size. */
  data class FilePayload(
    val file: File,
    val durationMs: Long,
    val hasAudio: Boolean,
  )

  /** Camera device metadata exposed through camera.list. */
  data class CameraDeviceInfo(
    val id: String,
    val name: String,
    val position: String,
    val deviceType: String,
  )

  @Volatile private var lifecycleOwner: LifecycleOwner? = null

  /** Supplies the foreground Activity lifecycle required by CameraX use-case binding. */
  fun attachLifecycleOwner(owner: LifecycleOwner) {
    // CameraX binds use cases to an Activity lifecycle; background services cannot capture alone.
    lifecycleOwner = owner
  }

  /** Lists CameraX devices with stable Camera2 ids where available. */
  suspend fun listDevices(): List<CameraDeviceInfo> =
    withContext(Dispatchers.Main) {
      val provider = context.cameraProvider()
      provider.availableCameraInfos
        .mapNotNull { info -> cameraDeviceInfoOrNull(info) }
        .sortedBy { it.id }
    }

  private fun ensureCameraPermission() {
    val granted = checkSelfPermission(context, Manifest.permission.CAMERA) == PackageManager.PERMISSION_GRANTED
    if (granted) return
    throw IllegalStateException("CAMERA_PERMISSION_REQUIRED: grant Camera permission")
  }

  private fun ensureMicPermission() {
    val granted = checkSelfPermission(context, Manifest.permission.RECORD_AUDIO) == PackageManager.PERMISSION_GRANTED
    if (granted) return
    throw IllegalStateException("MIC_PERMISSION_REQUIRED: grant Microphone permission")
  }

  /** Captures one still image and returns a gateway-sized JPEG payload. */
  suspend fun snap(paramsJson: String?): Payload =
    withContext(Dispatchers.Main) {
      ensureCameraPermission()
      val owner = lifecycleOwner ?: throw IllegalStateException("UNAVAILABLE: camera not ready")
      val params = parseJsonParamsObject(paramsJson)
      val facing = resolveCameraFacing(parseFacing(params), defaultFacing())
      val quality = (parseQuality(params) ?: 0.95).coerceIn(0.1, 1.0)
      val maxWidth = parseMaxWidth(params) ?: 1600
      val deviceId = parseDeviceId(params)

      val provider = context.cameraProvider()
      val capture = ImageCapture.Builder().build()
      val selector = resolveCameraSelector(provider, facing, deviceId)

      provider.unbindAll()
      // Bind only the still capture use case; CameraX owns camera open/close through the lifecycle owner.
      provider.bindToLifecycle(owner, selector, capture)

      val (bytes, orientation) =
        try {
          capture.takeJpegWithExif(context.mainExecutor(), context.cacheDir)
        } finally {
          // The JPEG bytes are self-contained; release CameraX before decoding and recompressing them.
          provider.unbind(capture)
        }
      val decoded =
        BitmapFactory.decodeByteArray(bytes, 0, bytes.size)
          ?: throw IllegalStateException("UNAVAILABLE: failed to decode captured image")
      val rotated = JpegSizeLimiter.normalizeOrientation(decoded, orientation)
      val scaled =
        if (maxWidth > 0 && rotated.width > maxWidth) {
          val h =
            (rotated.height.toDouble() * (maxWidth.toDouble() / rotated.width.toDouble()))
              .toInt()
              .coerceAtLeast(1)
          val s = rotated.scale(maxWidth, h)
          if (s !== rotated) rotated.recycle()
          s
        } else {
          rotated
        }

      try {
        val maxPayloadBytes = 5 * 1024 * 1024
        // Base64 inflates payloads by ~4/3; cap encoded bytes so the payload stays under 5MB (API limit).
        val maxEncodedBytes = (maxPayloadBytes / 4) * 3
        val result =
          JpegSizeLimiter.compressToLimit(
            initialWidth = scaled.width,
            initialHeight = scaled.height,
            startQuality = (quality * 100.0).roundToInt().coerceIn(10, 100),
            minQuality = (quality * 100.0).roundToInt().coerceIn(10, 20),
            maxBytes = maxEncodedBytes,
            encode = { width, height, q ->
              val bitmap =
                if (width == scaled.width && height == scaled.height) {
                  scaled
                } else {
                  scaled.scale(width, height)
                }
              val out = ByteArrayOutputStream()
              if (!bitmap.compress(Bitmap.CompressFormat.JPEG, q, out)) {
                if (bitmap !== scaled) bitmap.recycle()
                throw IllegalStateException("UNAVAILABLE: failed to encode JPEG")
              }
              if (bitmap !== scaled) {
                bitmap.recycle()
              }
              out.toByteArray()
            },
          )
        val base64 = Base64.encodeToString(result.bytes, Base64.NO_WRAP)
        Payload(
          """{"format":"jpg","base64":"$base64","width":${result.width},"height":${result.height}}""",
        )
      } finally {
        scaled.recycle()
      }
    }

  /** Records a short MP4 clip into a temporary cache file for the caller to encode/delete. */
  @SuppressLint("MissingPermission")
  suspend fun clip(
    paramsJson: String?,
    onFileReady: (File) -> Unit,
  ): FilePayload =
    withContext(Dispatchers.Main) {
      ensureCameraPermission()
      val params = parseJsonParamsObject(paramsJson)
      val facing = resolveCameraFacing(parseFacing(params), defaultFacing())
      val durationMs = (parseDurationMs(params) ?: 3_000).coerceIn(200, 60_000)
      val includeAudio = parseIncludeAudio(params) ?: true
      val deviceId = parseDeviceId(params)
      if (includeAudio) ensureMicPermission()
      val owner = lifecycleOwner ?: throw IllegalStateException("UNAVAILABLE: camera not ready")

      val provider = context.cameraProvider()

      // Use LOWEST quality for smallest files over WebSocket
      val recorder =
        Recorder
          .Builder()
          .setQualitySelector(
            QualitySelector.from(Quality.LOWEST, FallbackStrategy.lowerQualityOrHigherThan(Quality.LOWEST)),
          ).build()
      val videoCapture = VideoCapture.withOutput(recorder)
      val selector = resolveCameraSelector(provider, facing, deviceId)

      // CameraX requires a Preview use case for the camera to start producing frames;
      // without it, the encoder may get no data (ERROR_NO_VALID_DATA).
      val preview =
        androidx.camera.core.Preview
          .Builder()
          .build()
      // Allocate the dummy preview surface only after CameraX requests it; its result owns release.
      preview.setSurfaceProvider { request ->
        val surfaceTexture = android.graphics.SurfaceTexture(0)
        surfaceTexture.setDefaultBufferSize(640, 480)
        val surface = android.view.Surface(surfaceTexture)
        request.provideSurface(surface, context.mainExecutor()) {
          surface.release()
          surfaceTexture.release()
        }
      }

      provider.unbindAll()
      CameraClipSession(
        unbind = { provider.unbind(preview, videoCapture) },
        deleteTemporaryFile = { file ->
          check(!file.exists() || file.delete()) { "failed to delete temporary camera clip" }
        },
      ).use { session ->
        provider.bindToLifecycle(owner, selector, preview, videoCapture)

        // Give camera pipeline time to initialize before recording
        kotlinx.coroutines.delay(1_500)

        val clipFile = session.ownFile(File.createTempFile("openclaw-clip-", ".mp4", context.cacheDir))
        val outputOptions = FileOutputOptions.Builder(clipFile).build()

        val finalized = kotlinx.coroutines.CompletableDeferred<VideoRecordEvent.Finalize>()
        val recording =
          videoCapture.output
            .prepareRecording(context, outputOptions)
            .apply {
              if (includeAudio) withAudioEnabled()
            }.start(context.mainExecutor()) { event ->
              if (event is VideoRecordEvent.Finalize) {
                finalized.complete(event)
              }
            }
        session.ownRecording(recording)

        kotlinx.coroutines.delay(durationMs.toLong())
        recording.close()

        val finalizeEvent =
          try {
            withTimeout(15_000) { finalized.await() }
          } catch (_: kotlinx.coroutines.TimeoutCancellationException) {
            throw IllegalStateException("UNAVAILABLE: camera clip finalize timed out")
          }
        if (finalizeEvent.hasError()) {
          throw IllegalStateException("UNAVAILABLE: camera clip failed (error=${finalizeEvent.error})")
        }

        FilePayload(
          file = session.transferFile(onFileReady),
          durationMs = durationMs.toLong(),
          hasAudio = includeAudio,
        )
      }
    }

  private fun parseFacing(params: JsonObject?): String? {
    val value = parseJsonString(params, "facing")?.trim()?.lowercase() ?: return null
    return when (value) {
      "front", "back" -> value
      else -> null
    }
  }

  private fun parseQuality(params: JsonObject?): Double? = parseJsonDouble(params, "quality")

  private fun parseMaxWidth(params: JsonObject?): Int? =
    parseJsonInt(params, "maxWidth")
      ?.takeIf { it > 0 }

  private fun parseDurationMs(params: JsonObject?): Int? = parseJsonInt(params, "durationMs")

  private fun parseDeviceId(params: JsonObject?): String? =
    parseJsonString(params, "deviceId")
      ?.trim()
      ?.takeIf { it.isNotEmpty() }

  private fun parseIncludeAudio(params: JsonObject?): Boolean? = parseJsonBooleanFlag(params, "includeAudio")

  private fun Context.mainExecutor(): Executor = ContextCompat.getMainExecutor(this)

  private fun resolveCameraSelector(
    provider: ProcessCameraProvider,
    facing: String,
    deviceId: String?,
  ): CameraSelector {
    if (deviceId.isNullOrEmpty()) {
      return if (facing == "front") CameraSelector.DEFAULT_FRONT_CAMERA else CameraSelector.DEFAULT_BACK_CAMERA
    }
    val availableIds = provider.availableCameraInfos.mapNotNull { cameraIdOrNull(it) }.toSet()
    if (!availableIds.contains(deviceId)) {
      throw IllegalStateException("INVALID_REQUEST: unknown camera deviceId '$deviceId'")
    }
    return CameraSelector
      .Builder()
      // CameraX selectors are filters over CameraInfo; pin by Camera2 id for stable device selection.
      .addCameraFilter { infos -> infos.filter { cameraIdOrNull(it) == deviceId } }
      .build()
  }

  @SuppressLint("UnsafeOptInUsageError")
  private fun cameraDeviceInfoOrNull(info: CameraInfo): CameraDeviceInfo? {
    val cameraId = cameraIdOrNull(info) ?: return null
    val lensFacing =
      runCatching {
        Camera2CameraInfo.from(info).getCameraCharacteristic(CameraCharacteristics.LENS_FACING)
      }.getOrNull()
    val position =
      when (lensFacing) {
        CameraCharacteristics.LENS_FACING_FRONT -> "front"
        CameraCharacteristics.LENS_FACING_BACK -> "back"
        CameraCharacteristics.LENS_FACING_EXTERNAL -> "external"
        else -> "unspecified"
      }
    val deviceType =
      if (lensFacing == CameraCharacteristics.LENS_FACING_EXTERNAL) "external" else "builtIn"
    val name =
      when (position) {
        "front" -> "Front Camera"
        "back" -> "Back Camera"
        "external" -> "External Camera"
        else -> "Camera $cameraId"
      }
    return CameraDeviceInfo(
      id = cameraId,
      name = name,
      position = position,
      deviceType = deviceType,
    )
  }

  @SuppressLint("UnsafeOptInUsageError")
  private fun cameraIdOrNull(info: CameraInfo): String? = runCatching { Camera2CameraInfo.from(info).cameraId }.getOrNull()
}

internal fun resolveCameraFacing(
  explicitFacing: String?,
  preferredFacing: String,
): String = explicitFacing ?: preferredFacing.takeIf { it == "back" } ?: "front"

private suspend fun Context.cameraProvider(): ProcessCameraProvider =
  suspendCancellableCoroutine { cont ->
    val future = ProcessCameraProvider.getInstance(this)
    future.addListener(
      {
        try {
          cont.resume(future.get())
        } catch (e: Exception) {
          cont.resumeWithException(e)
        }
      },
      ContextCompat.getMainExecutor(this),
    )
  }

/**
 * Returns JPEG bytes plus EXIF orientation so callers can normalize the decoded bitmap.
 */
private suspend fun ImageCapture.takeJpegWithExif(
  executor: Executor,
  tempDir: File,
): Pair<ByteArray, Int> =
  suspendCancellableCoroutine { cont ->
    val file = File.createTempFile("openclaw-snap-", ".jpg", tempDir)
    val options = ImageCapture.OutputFileOptions.Builder(file).build()
    takePicture(
      options,
      executor,
      object : ImageCapture.OnImageSavedCallback {
        override fun onError(exception: ImageCaptureException) {
          file.delete()
          cont.resumeWithException(exception)
        }

        override fun onImageSaved(outputFileResults: ImageCapture.OutputFileResults) {
          try {
            val exif = ExifInterface(file.absolutePath)
            val orientation =
              exif.getAttributeInt(
                ExifInterface.TAG_ORIENTATION,
                ExifInterface.ORIENTATION_NORMAL,
              )
            val bytes = file.readBytes()
            cont.resume(Pair(bytes, orientation))
          } catch (e: Exception) {
            cont.resumeWithException(e)
          } finally {
            file.delete()
          }
        }
      },
    )
  }

package ai.openclaw.app.node

import ai.openclaw.app.BuildConfig
import ai.openclaw.app.CameraHudKind
import ai.openclaw.app.gateway.GatewaySession
import ai.openclaw.app.takeUtf16Safe
import android.content.Context
import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.NonCancellable
import kotlinx.coroutines.withContext
import kotlinx.serialization.json.JsonPrimitive
import kotlinx.serialization.json.buildJsonArray
import kotlinx.serialization.json.buildJsonObject
import kotlinx.serialization.json.put
import java.util.concurrent.atomic.AtomicReference

internal const val CAMERA_CLIP_MAX_RAW_BYTES: Long = 18L * 1024L * 1024L
private const val CAMERA_DEBUG_STACK_TRACE_MAX_CHARS = 2_000

/**
 * Raw MP4 size guard before base64 encoding the clip into a node.invoke response.
 */
internal fun isCameraClipWithinPayloadLimit(rawBytes: Long): Boolean = rawBytes in 0L..CAMERA_CLIP_MAX_RAW_BYTES

/**
 * Gateway camera command adapter that adds HUD feedback and payload-size enforcement.
 */
class CameraHandler(
  private val appContext: Context,
  private val camera: CameraCaptureManager,
  private val setCameraAudioCaptureActive: (Boolean) -> Boolean,
  private val showCameraHud: (message: String, kind: CameraHudKind, autoHideMs: Long?) -> Unit,
  private val invokeErrorFromThrowable: (err: Throwable) -> Pair<String, String>,
) {
  /** Handles camera.list by exposing CameraX devices through gateway metadata. */
  suspend fun handleList(_paramsJson: String?): GatewaySession.InvokeResult =
    try {
      val devices = camera.listDevices()
      val payload =
        buildJsonObject {
          put(
            "devices",
            buildJsonArray {
              devices.forEach { device ->
                add(
                  buildJsonObject {
                    put("id", JsonPrimitive(device.id))
                    put("name", JsonPrimitive(device.name))
                    put("position", JsonPrimitive(device.position))
                    put("deviceType", JsonPrimitive(device.deviceType))
                  },
                )
              }
            },
          )
        }.toString()
      GatewaySession.InvokeResult.ok(payload)
    } catch (err: CancellationException) {
      throw err
    } catch (err: Throwable) {
      val (code, message) = invokeErrorFromThrowable(err)
      GatewaySession.InvokeResult.error(code = code, message = message)
    }

  /** Handles camera.snap with HUD progress, flash feedback, and normalized invoke errors. */
  suspend fun handleSnap(paramsJson: String?): GatewaySession.InvokeResult {
    val logFile = if (BuildConfig.DEBUG) java.io.File(appContext.cacheDir, "camera_debug.log") else null

    fun camLog(msg: String) {
      if (!BuildConfig.DEBUG) return
      val ts = java.text.SimpleDateFormat("HH:mm:ss.SSS", java.util.Locale.US).format(java.util.Date())
      logFile?.appendText("[$ts] $msg\n")
      android.util.Log.w("openclaw", "camera.snap: $msg")
    }
    try {
      logFile?.writeText("") // clear
      camLog("starting, params=$paramsJson")
      camLog("calling showCameraHud")
      showCameraHud("Taking photo…", CameraHudKind.Photo, null)
      val res =
        try {
          camLog("calling camera.snap()")
          val r = camera.snap(paramsJson)
          camLog("success, payload size=${r.payloadJson.length}")
          r
        } catch (err: CancellationException) {
          throw err
        } catch (err: Throwable) {
          camLog("inner error: ${err::class.java.simpleName}: ${err.message}")
          camLog("stack: ${err.stackTraceToString().takeUtf16Safe(CAMERA_DEBUG_STACK_TRACE_MAX_CHARS)}")
          val (code, message) = invokeErrorFromThrowable(err)
          showCameraHud(message, CameraHudKind.Error, 2200)
          return GatewaySession.InvokeResult.error(code = code, message = message)
        }
      camLog("returning result")
      showCameraHud("Photo captured", CameraHudKind.Success, 1600)
      return GatewaySession.InvokeResult.ok(res.payloadJson)
    } catch (err: CancellationException) {
      throw err
    } catch (err: Throwable) {
      camLog("outer error: ${err::class.java.simpleName}: ${err.message}")
      camLog("stack: ${err.stackTraceToString().takeUtf16Safe(CAMERA_DEBUG_STACK_TRACE_MAX_CHARS)}")
      return GatewaySession.InvokeResult.error(code = "UNAVAILABLE", message = err.message ?: "camera snap failed")
    }
  }

  /** Handles camera.clip and keeps external audio capture paused while camera audio is active. */
  suspend fun handleClip(paramsJson: String?): GatewaySession.InvokeResult {
    val clipLogFile = if (BuildConfig.DEBUG) java.io.File(appContext.cacheDir, "camera_debug.log") else null

    fun clipLog(msg: String) {
      if (!BuildConfig.DEBUG) return
      val ts = java.text.SimpleDateFormat("HH:mm:ss.SSS", java.util.Locale.US).format(java.util.Date())
      clipLogFile?.appendText("[CLIP $ts] $msg\n")
      android.util.Log.w("openclaw", "camera.clip: $msg")
    }
    val includeAudio = parseIncludeAudio(paramsJson) ?: true
    val ownsAudioCapture = includeAudio && setCameraAudioCaptureActive(true)
    if (includeAudio && !ownsAudioCapture) {
      return GatewaySession.InvokeResult.error(
        code = "MIC_BUSY",
        message = "MIC_BUSY: another audio capture is active",
      )
    }
    val ownedClipFile = AtomicReference<java.io.File?>()
    try {
      clipLogFile?.writeText("") // clear
      clipLog("starting, params=$paramsJson includeAudio=$includeAudio")
      clipLog("calling showCameraHud")
      showCameraHud("Recording…", CameraHudKind.Recording, null)
      val filePayload =
        try {
          clipLog("calling camera.clip()")
          val r =
            camera.clip(paramsJson) { file ->
              check(ownedClipFile.compareAndSet(null, file)) { "camera clip already owns a file" }
            }
          clipLog("success, file size=${r.file.length()}")
          r
        } catch (err: CancellationException) {
          throw err
        } catch (err: Throwable) {
          clipLog("inner error: ${err::class.java.simpleName}: ${err.message}")
          clipLog("stack: ${err.stackTraceToString().takeUtf16Safe(CAMERA_DEBUG_STACK_TRACE_MAX_CHARS)}")
          val (code, message) = invokeErrorFromThrowable(err)
          showCameraHud(message, CameraHudKind.Error, 2400)
          return GatewaySession.InvokeResult.error(code = code, message = message)
        }
      val rawBytes = filePayload.file.length()
      if (!isCameraClipWithinPayloadLimit(rawBytes)) {
        clipLog("payload too large: bytes=$rawBytes max=$CAMERA_CLIP_MAX_RAW_BYTES")
        showCameraHud("Clip too large", CameraHudKind.Error, 2400)
        return GatewaySession.InvokeResult.error(
          code = "PAYLOAD_TOO_LARGE",
          message =
            "PAYLOAD_TOO_LARGE: camera clip is $rawBytes bytes; max is $CAMERA_CLIP_MAX_RAW_BYTES bytes. Reduce durationMs and retry.",
        )
      }

      val bytes = withContext(Dispatchers.IO) { filePayload.file.readBytes() }
      val base64 = android.util.Base64.encodeToString(bytes, android.util.Base64.NO_WRAP)
      clipLog("returning base64 payload")
      showCameraHud("Clip captured", CameraHudKind.Success, 1800)
      return GatewaySession.InvokeResult.ok(
        """{"format":"mp4","base64":"$base64","durationMs":${filePayload.durationMs},"hasAudio":${filePayload.hasAudio}}""",
      )
    } catch (err: CancellationException) {
      throw err
    } catch (err: Throwable) {
      clipLog("outer error: ${err::class.java.simpleName}: ${err.message}")
      clipLog("stack: ${err.stackTraceToString().takeUtf16Safe(CAMERA_DEBUG_STACK_TRACE_MAX_CHARS)}")
      return GatewaySession.InvokeResult.error(code = "UNAVAILABLE", message = err.message ?: "camera clip failed")
    } finally {
      try {
        ownedClipFile.getAndSet(null)?.let { file ->
          // Nest dispatcher changes so cancellation cannot replace the original failure.
          withContext(NonCancellable) {
            withContext(Dispatchers.IO) { file.delete() }
          }
        }
      } finally {
        // Prevent talk/transcription capture from competing with camera audio after every exit path.
        if (ownsAudioCapture) setCameraAudioCaptureActive(false)
      }
    }
  }

  private fun parseIncludeAudio(paramsJson: String?): Boolean? = parseJsonBooleanFlag(parseJsonParamsObject(paramsJson), "includeAudio")
}

package ai.openclaw.app.node

import ai.openclaw.app.BuildConfig
import ai.openclaw.app.LocationMode
import ai.openclaw.app.SecurePrefs
import ai.openclaw.app.gateway.GatewayClientInfo
import ai.openclaw.app.gateway.GatewayConnectOptions
import ai.openclaw.app.gateway.GatewayEndpoint
import ai.openclaw.app.gateway.GatewayTlsParams
import ai.openclaw.app.gateway.isLocalCleartextGatewayHost
import ai.openclaw.app.gateway.isLoopbackGatewayHost
import android.os.Build

/**
 * Builds gateway connect metadata from current Android permissions, settings, and device identity.
 */
class ConnectionManager internal constructor(
  private val prefs: SecurePrefs,
  private val cameraEnabled: () -> Boolean,
  private val locationMode: () -> LocationMode,
  private val motionActivityAvailable: () -> Boolean,
  private val motionPedometerAvailable: () -> Boolean,
  private val sendSmsAvailable: () -> Boolean,
  private val readSmsAvailable: () -> Boolean,
  private val smsSearchPossible: () -> Boolean,
  private val callLogAvailable: () -> Boolean,
  private val photosAvailable: () -> Boolean,
  private val installedAppsSharingEnabled: () -> Boolean,
  private val voiceWakeAvailable: () -> Boolean,
  private val mobileUiAvailable: () -> Boolean,
  private val inlineWidgetsAvailable: () -> Boolean,
  private val permissionSnapshot: () -> AndroidPermissionSnapshot,
  private val manualTls: (GatewayEndpoint) -> Boolean,
) {
  companion object {
    internal val legacyOperatorScopes: List<String> =
      listOf(
        "operator.approvals",
        "operator.read",
        "operator.write",
      )

    internal val nativeClientOperatorScopes: List<String> =
      listOf(
        // admin matches iOS fresh token/password connects and is required for
        // sessions.patch (model switching); stored tokens keep their granted scopes.
        "operator.admin",
        "operator.approvals",
        "operator.questions",
        "operator.read",
        "operator.talk.secrets",
        "operator.write",
      )

    internal const val AGENT_KIND_CLIENT_CAPABILITY = "agent-kind"
    internal const val INLINE_WIDGETS_CLIENT_CAPABILITY = "inline-widgets"
    internal const val USAGE_REFRESHING_CLIENT_CAPABILITY = "usage-refreshing"

    internal fun operatorScopesForStoredDeviceToken(storedScopes: List<String>): List<String> {
      val normalized =
        storedScopes
          .map { it.trim() }
          .filter { it.isNotEmpty() }
          .distinct()
      return normalized.ifEmpty { legacyOperatorScopes }
    }

    /**
     * Decide whether a discovered/manual endpoint must use pinned TLS or can stay local cleartext.
     */
    internal fun resolveTlsParamsForEndpoint(
      endpoint: GatewayEndpoint,
      storedFingerprint: String?,
      manualTlsEnabled: Boolean,
    ): GatewayTlsParams? {
      val stableId = endpoint.stableId
      val stored = storedFingerprint?.trim().takeIf { !it.isNullOrEmpty() }
      val isManual = stableId.startsWith("manual|")
      val cleartextAllowedHost =
        if (isManual) {
          isLocalCleartextGatewayHost(endpoint.host)
        } else {
          isLoopbackGatewayHost(endpoint.host)
        }

      if (isManual) {
        // Manual remote hosts default to TLS; only local manual hosts may honor the cleartext toggle.
        if (!manualTlsEnabled && cleartextAllowedHost) return null
        if (!stored.isNullOrBlank()) {
          return GatewayTlsParams(
            required = true,
            expectedFingerprint = stored,
            allowTOFU = false,
            stableId = stableId,
          )
        }
        return GatewayTlsParams(
          required = true,
          expectedFingerprint = null,
          allowTOFU = false,
          stableId = stableId,
        )
      }

      // Prefer stored pins. Never let discovery-provided TXT override a stored fingerprint.
      if (!stored.isNullOrBlank()) {
        return GatewayTlsParams(
          required = true,
          expectedFingerprint = stored,
          allowTOFU = false,
          stableId = stableId,
        )
      }

      val hinted = endpoint.tlsEnabled || !endpoint.tlsFingerprintSha256.isNullOrBlank()
      if (hinted) {
        // TXT is unauthenticated. Do not treat the advertised fingerprint as authoritative.
        return GatewayTlsParams(
          required = true,
          expectedFingerprint = null,
          allowTOFU = false,
          stableId = stableId,
        )
      }

      if (!cleartextAllowedHost) {
        // Non-loopback discovered hosts require TLS even without TXT hints.
        return GatewayTlsParams(
          required = true,
          expectedFingerprint = null,
          allowTOFU = false,
          stableId = stableId,
        )
      }

      return null
    }
  }

  private fun runtimeFlags(): NodeRuntimeFlags =
    NodeRuntimeFlags(
      cameraEnabled = cameraEnabled(),
      locationEnabled = locationMode() != LocationMode.Off,
      sendSmsAvailable = sendSmsAvailable(),
      readSmsAvailable = readSmsAvailable(),
      smsSearchPossible = smsSearchPossible(),
      callLogAvailable = callLogAvailable(),
      photosAvailable = photosAvailable(),
      motionActivityAvailable = motionActivityAvailable(),
      motionPedometerAvailable = motionPedometerAvailable(),
      installedAppsSharingEnabled = installedAppsSharingEnabled(),
      debugBuild = BuildConfig.DEBUG,
      voiceWakeEnabled = prefs.voiceWakeEnabled.value && voiceWakeAvailable(),
      mobileUiAvailable = mobileUiAvailable(),
    )

  /** Builds the gateway-advertised node.invoke command list from current permission and feature state. */
  fun buildInvokeCommands(): List<String> = InvokeCommandRegistry.advertisedCommands(runtimeFlags())

  /** Builds the gateway-advertised capability list from current permission and feature state. */
  fun buildCapabilities(): List<String> = InvokeCommandRegistry.advertisedCapabilities(runtimeFlags())

  /** Builds the current independently grantable Android permission surface. */
  fun buildPermissions(): Map<String, Boolean> = permissionSnapshot().gatewayPermissions()

  /**
   * Debug Android builds advertise a dev version so gateway logs do not look like release clients.
   */
  fun resolvedVersionName(): String {
    val versionName = BuildConfig.VERSION_NAME.trim().ifEmpty { "dev" }
    return if (BuildConfig.DEBUG && !versionName.contains("dev", ignoreCase = true)) {
      "$versionName-dev"
    } else {
      versionName
    }
  }

  /** Human-readable Android device model used in gateway client metadata. */
  fun resolveModelIdentifier(): String? =
    listOfNotNull(Build.MANUFACTURER, Build.MODEL)
      .joinToString(" ")
      .trim()
      .ifEmpty { null }

  /**
   * User-Agent used for gateway telemetry and troubleshooting.
   */
  fun buildUserAgent(): String {
    val version = resolvedVersionName()
    val release =
      Build.VERSION.RELEASE
        ?.trim()
        .orEmpty()
    val releaseLabel = if (release.isEmpty()) "unknown" else release
    return "OpenClawAndroid/$version (Android $releaseLabel; SDK ${Build.VERSION.SDK_INT})"
  }

  /** Client identity block shared by node and operator gateway sessions. */
  fun buildClientInfo(
    clientId: String,
    clientMode: String,
  ): GatewayClientInfo =
    GatewayClientInfo(
      id = clientId,
      displayName = prefs.displayName.value,
      version = resolvedVersionName(),
      platform = "android",
      mode = clientMode,
      instanceId = prefs.instanceId.value,
      deviceFamily = "Android",
      modelIdentifier = resolveModelIdentifier(),
    )

  /** Connect options for the Android node session that exposes phone capabilities. */
  fun buildNodeConnectOptions(): GatewayConnectOptions =
    GatewayConnectOptions(
      role = "node",
      scopes = emptyList(),
      caps = buildCapabilities(),
      commands = buildInvokeCommands(),
      permissions = buildPermissions(),
      client = buildClientInfo(clientId = "openclaw-android", clientMode = "node"),
      userAgent = buildUserAgent(),
    )

  /** Connect options for the Android operator session that drives approvals and UI actions. */
  fun buildOperatorConnectOptions(
    scopes: List<String> = nativeClientOperatorScopes,
  ): GatewayConnectOptions =
    GatewayConnectOptions(
      role = "operator",
      scopes = scopes,
      caps =
        buildList {
          add(AGENT_KIND_CLIENT_CAPABILITY)
          if (inlineWidgetsAvailable()) add(INLINE_WIDGETS_CLIENT_CAPABILITY)
          add(USAGE_REFRESHING_CLIENT_CAPABILITY)
        },
      commands = emptyList(),
      permissions = emptyMap(),
      client = buildClientInfo(clientId = "openclaw-android", clientMode = "ui"),
      userAgent = buildUserAgent(),
    )

  /** Resolves persisted TLS pin policy for a concrete gateway endpoint. */
  fun resolveTlsParams(endpoint: GatewayEndpoint): GatewayTlsParams? {
    val stored = prefs.loadGatewayTlsFingerprint(endpoint.stableId)
    return resolveTlsParamsForEndpoint(endpoint, storedFingerprint = stored, manualTlsEnabled = manualTls(endpoint))
  }
}

package ai.openclaw.app.node

import ai.openclaw.app.gateway.GatewaySession
import android.Manifest
import android.content.ContentProviderOperation
import android.content.ContentResolver
import android.content.Context
import android.provider.ContactsContract
import androidx.core.content.ContextCompat
import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonArray
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.JsonPrimitive
import kotlinx.serialization.json.buildJsonArray
import kotlinx.serialization.json.buildJsonObject
import kotlinx.serialization.json.put

private const val DEFAULT_CONTACTS_LIMIT = 25

/**
 * Normalized Android contact row returned through the contacts commands.
 */
internal data class ContactRecord(
  val identifier: String,
  val displayName: String,
  val givenName: String,
  val familyName: String,
  val organizationName: String,
  val phoneNumbers: List<String>,
  val emails: List<String>,
)

/**
 * Parsed contacts.search request with bounded result count.
 */
internal data class ContactsSearchRequest(
  val query: String?,
  val limit: Int,
)

/**
 * Parsed contacts.add request before ContentProviderOperation batching.
 */
internal data class ContactsAddRequest(
  val givenName: String?,
  val familyName: String?,
  val organizationName: String?,
  val displayName: String?,
  val phoneNumbers: List<String>,
  val emails: List<String>,
)

/**
 * Injectable ContactsProvider facade for command tests and Android runtime access.
 */
internal interface ContactsDataSource {
  fun hasReadPermission(context: Context): Boolean

  fun hasWritePermission(context: Context): Boolean

  fun search(
    context: Context,
    request: ContactsSearchRequest,
  ): List<ContactRecord>

  fun add(
    context: Context,
    request: ContactsAddRequest,
  ): ContactRecord
}

private object SystemContactsDataSource : ContactsDataSource {
  override fun hasReadPermission(context: Context): Boolean =
    ContextCompat.checkSelfPermission(context, Manifest.permission.READ_CONTACTS) ==
      android.content.pm.PackageManager.PERMISSION_GRANTED

  override fun hasWritePermission(context: Context): Boolean =
    ContextCompat.checkSelfPermission(context, Manifest.permission.WRITE_CONTACTS) ==
      android.content.pm.PackageManager.PERMISSION_GRANTED

  override fun search(
    context: Context,
    request: ContactsSearchRequest,
  ): List<ContactRecord> {
    val resolver = context.contentResolver
    val projection =
      arrayOf(
        ContactsContract.Contacts._ID,
        ContactsContract.Contacts.DISPLAY_NAME_PRIMARY,
      )
    val selection: String?
    val selectionArgs: Array<String>?
    if (request.query.isNullOrBlank()) {
      selection = null
      selectionArgs = null
    } else {
      // Escape wildcard characters so user text remains a substring search, not a LIKE pattern.
      selection = "${ContactsContract.Contacts.DISPLAY_NAME_PRIMARY} LIKE ? ESCAPE '\\'"
      selectionArgs = arrayOf("%${escapeLikePattern(request.query)}%")
    }
    val sortOrder = "${ContactsContract.Contacts.DISPLAY_NAME_PRIMARY} COLLATE NOCASE ASC LIMIT ${request.limit}"
    resolver
      .query(
        ContactsContract.Contacts.CONTENT_URI,
        projection,
        selection,
        selectionArgs,
        sortOrder,
      ).use { cursor ->
        if (cursor == null) return emptyList()
        val idIndex = cursor.getColumnIndexOrThrow(ContactsContract.Contacts._ID)
        val displayNameIndex = cursor.getColumnIndexOrThrow(ContactsContract.Contacts.DISPLAY_NAME_PRIMARY)
        val out = mutableListOf<ContactRecord>()
        while (cursor.moveToNext() && out.size < request.limit) {
          val contactId = cursor.getLong(idIndex)
          val displayName = cursor.getString(displayNameIndex).orEmpty()
          out += loadContactRecord(resolver, contactId, fallbackDisplayName = displayName)
        }
        return out
      }
  }

  override fun add(
    context: Context,
    request: ContactsAddRequest,
  ): ContactRecord {
    val resolver = context.contentResolver
    val operations = ArrayList<ContentProviderOperation>()
    operations +=
      ContentProviderOperation
        .newInsert(ContactsContract.RawContacts.CONTENT_URI)
        .withValue(ContactsContract.RawContacts.ACCOUNT_TYPE, null)
        .withValue(ContactsContract.RawContacts.ACCOUNT_NAME, null)
        .build()
    // Subsequent Data rows use back-reference 0 to attach to the RawContact inserted above.
    if (!request.givenName.isNullOrEmpty() || !request.familyName.isNullOrEmpty() || !request.displayName.isNullOrEmpty()) {
      operations +=
        ContentProviderOperation
          .newInsert(ContactsContract.Data.CONTENT_URI)
          .withValueBackReference(ContactsContract.Data.RAW_CONTACT_ID, 0)
          .withValue(ContactsContract.Data.MIMETYPE, ContactsContract.CommonDataKinds.StructuredName.CONTENT_ITEM_TYPE)
          .withValue(ContactsContract.CommonDataKinds.StructuredName.GIVEN_NAME, request.givenName)
          .withValue(ContactsContract.CommonDataKinds.StructuredName.FAMILY_NAME, request.familyName)
          .withValue(ContactsContract.CommonDataKinds.StructuredName.DISPLAY_NAME, request.displayName)
          .build()
    }
    if (!request.organizationName.isNullOrEmpty()) {
      operations +=
        ContentProviderOperation
          .newInsert(ContactsContract.Data.CONTENT_URI)
          .withValueBackReference(ContactsContract.Data.RAW_CONTACT_ID, 0)
          .withValue(ContactsContract.Data.MIMETYPE, ContactsContract.CommonDataKinds.Organization.CONTENT_ITEM_TYPE)
          .withValue(ContactsContract.CommonDataKinds.Organization.COMPANY, request.organizationName)
          .build()
    }
    request.phoneNumbers.forEach { number ->
      operations +=
        ContentProviderOperation
          .newInsert(ContactsContract.Data.CONTENT_URI)
          .withValueBackReference(ContactsContract.Data.RAW_CONTACT_ID, 0)
          .withValue(ContactsContract.Data.MIMETYPE, ContactsContract.CommonDataKinds.Phone.CONTENT_ITEM_TYPE)
          .withValue(ContactsContract.CommonDataKinds.Phone.NUMBER, number)
          .withValue(ContactsContract.CommonDataKinds.Phone.TYPE, ContactsContract.CommonDataKinds.Phone.TYPE_MOBILE)
          .build()
    }
    request.emails.forEach { email ->
      operations +=
        ContentProviderOperation
          .newInsert(ContactsContract.Data.CONTENT_URI)
          .withValueBackReference(ContactsContract.Data.RAW_CONTACT_ID, 0)
          .withValue(ContactsContract.Data.MIMETYPE, ContactsContract.CommonDataKinds.Email.CONTENT_ITEM_TYPE)
          .withValue(ContactsContract.CommonDataKinds.Email.ADDRESS, email)
          .withValue(ContactsContract.CommonDataKinds.Email.TYPE, ContactsContract.CommonDataKinds.Email.TYPE_HOME)
          .build()
    }

    val results = resolver.applyBatch(ContactsContract.AUTHORITY, operations)
    val rawContactUri =
      results.firstOrNull()?.uri
        ?: throw IllegalStateException("contact insert failed")
    val rawContactId =
      rawContactUri.lastPathSegment?.toLongOrNull()
        ?: throw IllegalStateException("contact insert failed")
    val contactId =
      // Android returns the RawContact id; resolve the aggregate Contact id used by search APIs.
      resolveContactIdForRawContact(resolver, rawContactId)
        ?: throw IllegalStateException("contact insert failed")
    return loadContactRecord(
      resolver = resolver,
      contactId = contactId,
      fallbackDisplayName = request.displayName.orEmpty(),
    )
  }

  private fun resolveContactIdForRawContact(
    resolver: ContentResolver,
    rawContactId: Long,
  ): Long? {
    val projection = arrayOf(ContactsContract.RawContacts.CONTACT_ID)
    resolver
      .query(
        ContactsContract.RawContacts.CONTENT_URI,
        projection,
        "${ContactsContract.RawContacts._ID}=?",
        arrayOf(rawContactId.toString()),
        null,
      ).use { cursor ->
        if (cursor == null || !cursor.moveToFirst()) return null
        val index = cursor.getColumnIndexOrThrow(ContactsContract.RawContacts.CONTACT_ID)
        return cursor.getLong(index)
      }
  }

  private fun loadContactRecord(
    resolver: ContentResolver,
    contactId: Long,
    fallbackDisplayName: String,
  ): ContactRecord {
    val nameRow = loadNameRow(resolver, contactId)
    val organization = loadOrganization(resolver, contactId)
    val phones = loadPhones(resolver, contactId)
    val emails = loadEmails(resolver, contactId)
    val displayName =
      (nameRow.displayName ?: fallbackDisplayName).ifEmpty {
        listOfNotNull(nameRow.givenName, nameRow.familyName).joinToString(" ").ifEmpty {
          organization ?: phones.firstOrNull() ?: emails.firstOrNull() ?: "(unnamed)"
        }
      }
    return ContactRecord(
      identifier = contactId.toString(),
      displayName = displayName,
      givenName = nameRow.givenName.orEmpty(),
      familyName = nameRow.familyName.orEmpty(),
      organizationName = organization.orEmpty(),
      phoneNumbers = phones,
      emails = emails,
    )
  }

  private data class NameRow(
    val givenName: String?,
    val familyName: String?,
    val displayName: String?,
  )

  private fun loadNameRow(
    resolver: ContentResolver,
    contactId: Long,
  ): NameRow {
    val projection =
      arrayOf(
        ContactsContract.CommonDataKinds.StructuredName.GIVEN_NAME,
        ContactsContract.CommonDataKinds.StructuredName.FAMILY_NAME,
        ContactsContract.CommonDataKinds.StructuredName.DISPLAY_NAME,
      )
    resolver
      .query(
        ContactsContract.Data.CONTENT_URI,
        projection,
        "${ContactsContract.Data.CONTACT_ID}=? AND ${ContactsContract.Data.MIMETYPE}=?",
        arrayOf(
          contactId.toString(),
          ContactsContract.CommonDataKinds.StructuredName.CONTENT_ITEM_TYPE,
        ),
        null,
      ).use { cursor ->
        if (cursor == null || !cursor.moveToFirst()) {
          return NameRow(givenName = null, familyName = null, displayName = null)
        }
        val given = cursor.getString(0)?.trim()?.ifEmpty { null }
        val family = cursor.getString(1)?.trim()?.ifEmpty { null }
        val display = cursor.getString(2)?.trim()?.ifEmpty { null }
        return NameRow(givenName = given, familyName = family, displayName = display)
      }
  }

  private fun loadOrganization(
    resolver: ContentResolver,
    contactId: Long,
  ): String? {
    val projection = arrayOf(ContactsContract.CommonDataKinds.Organization.COMPANY)
    resolver
      .query(
        ContactsContract.Data.CONTENT_URI,
        projection,
        "${ContactsContract.Data.CONTACT_ID}=? AND ${ContactsContract.Data.MIMETYPE}=?",
        arrayOf(contactId.toString(), ContactsContract.CommonDataKinds.Organization.CONTENT_ITEM_TYPE),
        null,
      ).use { cursor ->
        if (cursor == null || !cursor.moveToFirst()) return null
        return cursor.getString(0)?.trim()?.ifEmpty { null }
      }
  }

  private fun escapeLikePattern(pattern: String): String = pattern.replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_")

  private fun loadPhones(
    resolver: ContentResolver,
    contactId: Long,
  ): List<String> =
    queryContactValues(
      resolver = resolver,
      contentUri = ContactsContract.CommonDataKinds.Phone.CONTENT_URI,
      valueColumn = ContactsContract.CommonDataKinds.Phone.NUMBER,
      contactIdColumn = ContactsContract.CommonDataKinds.Phone.CONTACT_ID,
      contactId = contactId,
    )

  private fun loadEmails(
    resolver: ContentResolver,
    contactId: Long,
  ): List<String> =
    queryContactValues(
      resolver = resolver,
      contentUri = ContactsContract.CommonDataKinds.Email.CONTENT_URI,
      valueColumn = ContactsContract.CommonDataKinds.Email.ADDRESS,
      contactIdColumn = ContactsContract.CommonDataKinds.Email.CONTACT_ID,
      contactId = contactId,
    )

  private fun queryContactValues(
    resolver: ContentResolver,
    contentUri: android.net.Uri,
    valueColumn: String,
    contactIdColumn: String,
    contactId: Long,
  ): List<String> {
    val projection = arrayOf(valueColumn)
    resolver
      .query(
        contentUri,
        projection,
        "$contactIdColumn=?",
        arrayOf(contactId.toString()),
        null,
      ).use { cursor ->
        if (cursor == null) return emptyList()
        val out = LinkedHashSet<String>()
        while (cursor.moveToNext()) {
          val value = cursor.getString(0)?.trim().orEmpty()
          if (value.isNotEmpty()) out += value
        }
        return out.toList()
      }
  }
}

/**
 * Handles contacts.search and contacts.add gateway commands through Android ContactsProvider.
 */
class ContactsHandler private constructor(
  private val appContext: Context,
  private val dataSource: ContactsDataSource,
) {
  constructor(appContext: Context) : this(appContext = appContext, dataSource = SystemContactsDataSource)

  /** Searches contacts by optional display-name substring with bounded result count. */
  fun handleContactsSearch(paramsJson: String?): GatewaySession.InvokeResult {
    if (!dataSource.hasReadPermission(appContext)) {
      return GatewaySession.InvokeResult.error(
        code = "CONTACTS_PERMISSION_REQUIRED",
        message = "CONTACTS_PERMISSION_REQUIRED: grant Contacts permission",
      )
    }
    val request =
      parseSearchRequest(paramsJson)
        ?: return GatewaySession.InvokeResult.error(
          code = "INVALID_REQUEST",
          message = "INVALID_REQUEST: expected JSON object",
        )
    return try {
      val contacts = dataSource.search(appContext, request)
      GatewaySession.InvokeResult.ok(
        buildJsonObject {
          put(
            "contacts",
            buildJsonArray {
              contacts.forEach { add(contactJson(it)) }
            },
          )
        }.toString(),
      )
    } catch (err: Throwable) {
      GatewaySession.InvokeResult.error(
        code = "CONTACTS_UNAVAILABLE",
        message = "CONTACTS_UNAVAILABLE: ${err.message ?: "contacts query failed"}",
      )
    }
  }

  /** Adds a local contact after validating that at least one user-visible field is present. */
  fun handleContactsAdd(paramsJson: String?): GatewaySession.InvokeResult {
    if (!dataSource.hasWritePermission(appContext)) {
      return GatewaySession.InvokeResult.error(
        code = "CONTACTS_PERMISSION_REQUIRED",
        message = "CONTACTS_PERMISSION_REQUIRED: grant Contacts permission",
      )
    }
    val request =
      parseAddRequest(paramsJson)
        ?: return GatewaySession.InvokeResult.error(
          code = "INVALID_REQUEST",
          message = "INVALID_REQUEST: expected JSON object",
        )
    val hasName =
      !(request.givenName.isNullOrEmpty() && request.familyName.isNullOrEmpty() && request.displayName.isNullOrEmpty())
    val hasOrg = !request.organizationName.isNullOrEmpty()
    val hasDetails = request.phoneNumbers.isNotEmpty() || request.emails.isNotEmpty()
    if (!hasName && !hasOrg && !hasDetails) {
      return GatewaySession.InvokeResult.error(
        code = "CONTACTS_INVALID",
        message = "CONTACTS_INVALID: include a name, organization, phone, or email",
      )
    }
    return try {
      val contact = dataSource.add(appContext, request)
      GatewaySession.InvokeResult.ok(
        buildJsonObject {
          put("contact", contactJson(contact))
        }.toString(),
      )
    } catch (err: Throwable) {
      GatewaySession.InvokeResult.error(
        code = "CONTACTS_UNAVAILABLE",
        message = "CONTACTS_UNAVAILABLE: ${err.message ?: "contact add failed"}",
      )
    }
  }

  private fun parseSearchRequest(paramsJson: String?): ContactsSearchRequest? {
    if (paramsJson.isNullOrBlank()) {
      return ContactsSearchRequest(query = null, limit = DEFAULT_CONTACTS_LIMIT)
    }
    val params =
      try {
        Json.parseToJsonElement(paramsJson).asObjectOrNull()
      } catch (_: Throwable) {
        null
      } ?: return null
    val query = (params["query"] as? JsonPrimitive)?.content?.trim()?.ifEmpty { null }
    // Keep gateway-driven searches bounded even if the model asks for a large contact dump.
    val limit = ((params["limit"] as? JsonPrimitive)?.content?.toIntOrNull() ?: DEFAULT_CONTACTS_LIMIT).coerceIn(1, 200)
    return ContactsSearchRequest(query = query, limit = limit)
  }

  private fun parseAddRequest(paramsJson: String?): ContactsAddRequest? {
    val params =
      try {
        paramsJson?.let { Json.parseToJsonElement(it).asObjectOrNull() }
      } catch (_: Throwable) {
        null
      } ?: return null
    return ContactsAddRequest(
      givenName = parseJsonString(params, "givenName")?.trim()?.ifEmpty { null },
      familyName = parseJsonString(params, "familyName")?.trim()?.ifEmpty { null },
      organizationName = parseJsonString(params, "organizationName")?.trim()?.ifEmpty { null },
      displayName = parseJsonString(params, "displayName")?.trim()?.ifEmpty { null },
      phoneNumbers = stringArray(params["phoneNumbers"] as? JsonArray),
      // Store emails case-normalized so repeated model calls do not create casing-only duplicates.
      emails = stringArray(params["emails"] as? JsonArray).map { it.lowercase() },
    )
  }

  private fun stringArray(array: JsonArray?): List<String> {
    if (array == null) return emptyList()
    return array.mapNotNull { element ->
      element.asStringOrNull()?.trim()?.ifEmpty { null }
    }
  }

  private fun contactJson(contact: ContactRecord): JsonObject =
    buildJsonObject {
      put("identifier", JsonPrimitive(contact.identifier))
      put("displayName", JsonPrimitive(contact.displayName))
      put("givenName", JsonPrimitive(contact.givenName))
      put("familyName", JsonPrimitive(contact.familyName))
      put("organizationName", JsonPrimitive(contact.organizationName))
      put("phoneNumbers", buildJsonArray { contact.phoneNumbers.forEach { add(JsonPrimitive(it)) } })
      put("emails", buildJsonArray { contact.emails.forEach { add(JsonPrimitive(it)) } })
    }

  companion object {
    /** Creates a handler with an injected contacts source for parser and payload tests. */
    internal fun forTesting(
      appContext: Context,
      dataSource: ContactsDataSource,
    ): ContactsHandler = ContactsHandler(appContext = appContext, dataSource = dataSource)
  }
}

package ai.openclaw.app.node

import ai.openclaw.app.BuildConfig
import ai.openclaw.app.gateway.DeviceIdentityStore
import ai.openclaw.app.gateway.GatewaySession
import ai.openclaw.app.i18n.nativeString
import ai.openclaw.app.takeUtf16Safe
import android.content.Context
import kotlinx.serialization.json.JsonPrimitive

private const val LOGCAT_PATH = "/system/bin/logcat"

/**
 * Debug-only node.invoke commands for Android cryptography and log diagnostics.
 */
class DebugHandler(
  private val appContext: Context,
  private val identityStore: DeviceIdentityStore,
) {
  /**
   * Runs an Ed25519 self-test and returns redacted diagnostics for debug builds.
   */
  fun handleEd25519(): GatewaySession.InvokeResult {
    if (!BuildConfig.DEBUG) {
      return GatewaySession.InvokeResult.error(code = "UNAVAILABLE", message = "debug commands are disabled in release builds")
    }
    // Self-test Ed25519 signing without returning full private/public key material.
    try {
      val identity = identityStore.loadOrCreate()
      val testPayload = "test|${identity.deviceId}|${System.currentTimeMillis()}"
      val results = mutableListOf<String>()
      results.add("deviceId: ${identity.deviceId}")
      results.add("publicKeyRawBase64: ${identity.publicKeyRawBase64.take(20)}...")
      results.add("privateKeyPkcs8Base64: ${identity.privateKeyPkcs8Base64.take(20)}...")

      // Public-key URL encoding must match the gateway device-auth payload contract.
      val pubKeyUrl = identityStore.publicKeyBase64Url(identity)
      results.add("publicKeyBase64Url: ${pubKeyUrl ?: nativeString("NULL (FAILED)")}")

      // Sign/verify through DeviceIdentityStore to catch provider and key-format failures together.
      val signature = identityStore.signPayload(testPayload, identity)
      results.add("signPayload: ${if (signature != null) nativeString("\${signature.take(20)}... (OK)", signature.take(20)) else nativeString("NULL (FAILED)")}")

      if (signature != null) {
        val verifyOk = identityStore.verifySelfSignature(testPayload, signature, identity)
        results.add("verifySelfSignature: $verifyOk")
      }

      // Check available providers
      val providers = java.security.Security.getProviders()
      val ed25519Providers =
        providers.filter { p ->
          p.services.any { s -> s.algorithm.contains("Ed25519", ignoreCase = true) }
        }
      results.add("Ed25519 providers: ${ed25519Providers.map { "${it.name} v${it.version}" }}")
      results.add("Provider order: ${providers.take(5).map { it.name }}")

      // Test KeyFactory directly
      try {
        val kf = java.security.KeyFactory.getInstance("Ed25519")
        results.add("KeyFactory.Ed25519: ${kf.provider.name} (OK)")
      } catch (e: Throwable) {
        results.add("KeyFactory.Ed25519: FAILED - ${e.javaClass.simpleName}: ${e.message}")
      }

      // Test Signature directly
      try {
        val sig = java.security.Signature.getInstance("Ed25519")
        results.add("Signature.Ed25519: ${sig.provider.name} (OK)")
      } catch (e: Throwable) {
        results.add("Signature.Ed25519: FAILED - ${e.javaClass.simpleName}: ${e.message}")
      }

      val diagnostics = results.joinToString("\n")
      return GatewaySession.InvokeResult.ok("""{"diagnostics":${JsonPrimitive(diagnostics)}}""")
    } catch (e: Throwable) {
      return GatewaySession.InvokeResult.error(
        code = "ED25519_TEST_FAILED",
        message = "${e.javaClass.simpleName}: ${e.message}\n${e.stackTraceToString().takeUtf16Safe(500)}",
      )
    }
  }

  /**
   * Returns a filtered logcat snapshot plus CameraX debug log for debug builds.
   */
  fun handleLogs(): GatewaySession.InvokeResult {
    if (!BuildConfig.DEBUG) {
      return GatewaySession.InvokeResult.error(code = "UNAVAILABLE", message = "debug commands are disabled in release builds")
    }
    val pid = android.os.Process.myPid()
    val rt = Runtime.getRuntime()
    val info = "v6 pid=$pid thread=${Thread.currentThread().name} free=${rt.freeMemory() / 1024}K total=${rt.totalMemory() / 1024}K max=${rt.maxMemory() / 1024}K uptime=${android.os.SystemClock.elapsedRealtime() / 1000}s sdk=${android.os.Build.VERSION.SDK_INT} device=${android.os.Build.MODEL}\n"
    // Capture only this process and redirect through a temp file to avoid blocking on pipe backpressure.
    val logResult =
      try {
        val tmpFile = java.io.File(appContext.cacheDir, "debug_logs.txt")
        if (tmpFile.exists()) tmpFile.delete()
        val pb = ProcessBuilder(LOGCAT_PATH, "-d", "-t", "200", "--pid=$pid")
        pb.redirectOutput(tmpFile)
        pb.redirectErrorStream(true)
        val proc = pb.start()
        val finished = proc.waitFor(4, java.util.concurrent.TimeUnit.SECONDS)
        if (!finished) proc.destroyForcibly()
        val raw =
          if (tmpFile.exists() && tmpFile.length() > 0) {
            tmpFile.readText().takeUtf16Safe(128_000)
          } else {
            "(no output, finished=$finished, exists=${tmpFile.exists()})"
          }
        tmpFile.delete()
        val spamPatterns =
          listOf(
            "setRequestedFrameRate",
            "I View    :",
            "BLASTBufferQueue",
            "VRI[Pop-Up",
            "InsetsController:",
            "VRI[MainActivity",
            "InsetsSource:",
            "handleResized",
            "ProfileInstaller",
            "I VRI[",
            "onStateChanged: host=",
            "D StrictMode:",
            "E StrictMode:",
            "ImeFocusController",
            "InputTransport",
            "IncorrectContextUseViolation",
          )
        val sb = StringBuilder()
        for (line in raw.lineSequence()) {
          if (line.isBlank()) continue
          if (spamPatterns.any { line.contains(it) }) continue
          if (sb.length + line.length > 16000) {
            // Keep debug.invoke responses small enough for the gateway WebSocket frame budget.
            sb.append("\n(truncated)")
            break
          }
          if (sb.isNotEmpty()) sb.append('\n')
          sb.append(line)
        }
        sb.toString().ifEmpty { "(all ${raw.lines().size} lines filtered as spam)" }
      } catch (e: Throwable) {
        "(logcat error: ${e::class.java.simpleName}: ${e.message})"
      }
    // Camera capture writes a separate debug file because CameraX failures often happen off logcat's hot path.
    val camLogFile = java.io.File(appContext.cacheDir, "camera_debug.log")
    val camLog =
      if (camLogFile.exists() && camLogFile.length() > 0) {
        "\n--- camera_debug.log ---\n" + camLogFile.readText().takeUtf16Safe(4_000)
      } else {
        ""
      }
    return GatewaySession.InvokeResult.ok("""{"logs":${JsonPrimitive(info + logResult + camLog)}}""")
  }
}

package ai.openclaw.app.node

import ai.openclaw.app.BuildConfig
import ai.openclaw.app.SensitiveFeatureConfig
import ai.openclaw.app.gateway.GatewaySession
import android.annotation.SuppressLint
import android.app.ActivityManager
import android.content.Context
import android.content.Intent
import android.content.IntentFilter
import android.content.pm.ApplicationInfo
import android.content.pm.PackageManager
import android.net.ConnectivityManager
import android.net.NetworkCapabilities
import android.os.BatteryManager
import android.os.Build
import android.os.Environment
import android.os.PowerManager
import android.os.StatFs
import android.os.SystemClock
import kotlinx.serialization.json.JsonPrimitive
import kotlinx.serialization.json.buildJsonArray
import kotlinx.serialization.json.buildJsonObject
import kotlinx.serialization.json.put
import java.util.Locale

private const val DEFAULT_DEVICE_APPS_LIMIT = 100
private const val MAX_DEVICE_APPS_LIMIT = 200
private const val DEVICE_APPS_SYSTEM_FLAGS =
  ApplicationInfo.FLAG_SYSTEM or ApplicationInfo.FLAG_UPDATED_SYSTEM_APP

internal fun isSystemDeviceApp(appInfo: ApplicationInfo): Boolean = (appInfo.flags and DEVICE_APPS_SYSTEM_FLAGS) != 0

internal data class DeviceAppEntry(
  val label: String,
  val packageName: String,
  val system: Boolean,
  val enabled: Boolean,
  val launchable: Boolean,
)

internal interface DeviceAppSource {
  fun listApps(includeNonLaunchable: Boolean): List<DeviceAppEntry>
}

private class AndroidDeviceAppSource(
  private val appContext: Context,
) : DeviceAppSource {
  override fun listApps(includeNonLaunchable: Boolean): List<DeviceAppEntry> {
    val packageManager = appContext.packageManager
    val launcherIntent = Intent(Intent.ACTION_MAIN).apply { addCategory(Intent.CATEGORY_LAUNCHER) }
    val launchablePackages =
      packageManager
        .queryIntentActivities(launcherIntent, PackageManager.MATCH_ALL)
        .asSequence()
        .mapNotNull {
          it.activityInfo
            ?.packageName
            ?.trim()
            ?.takeIf(String::isNotEmpty)
        }.toSet()

    val appInfos =
      if (includeNonLaunchable) {
        visibleInstalledApplications(packageManager)
      } else {
        launchablePackages.mapNotNull { packageName ->
          runCatching { packageManager.getApplicationInfo(packageName, 0) }.getOrNull()
        }
      }

    return appInfos
      .asSequence()
      .mapNotNull { appInfo ->
        appInfo.packageName
          ?.trim()
          ?.takeIf(String::isNotEmpty)
          ?.let { packageName ->
            val label = packageManager.getApplicationLabel(appInfo).toString().trim()
            DeviceAppEntry(
              label = label.ifEmpty { packageName },
              packageName = packageName,
              system = isSystemDeviceApp(appInfo),
              enabled = appInfo.enabled,
              launchable = packageName in launchablePackages,
            )
          }
      }.distinctBy { it.packageName }
      .sortedWith(compareBy<DeviceAppEntry> { it.label.lowercase() }.thenBy { it.packageName })
      .toList()
  }

  @SuppressLint("QueryPermissionsNeeded")
  private fun visibleInstalledApplications(packageManager: PackageManager): List<ApplicationInfo> {
    // Android package visibility intentionally bounds this result to packages the app can see.
    // OpenClaw should not request QUERY_ALL_PACKAGES for this optional device-context surface.
    return packageManager.getInstalledApplications(PackageManager.MATCH_ALL)
  }
}

private data class DeviceAppsRequest(
  val includeSystem: Boolean,
  val includeDisabled: Boolean,
  val includeNonLaunchable: Boolean,
  val query: String?,
  val limit: Int,
)

/**
 * Gateway device command adapter for Android status, info, permission, and health snapshots.
 */
class DeviceHandler private constructor(
  private val appContext: Context,
  private val smsEnabled: Boolean = SensitiveFeatureConfig.smsEnabled,
  private val callLogEnabled: Boolean = SensitiveFeatureConfig.callLogEnabled,
  private val photosEnabled: Boolean = SensitiveFeatureConfig.photosEnabled,
  private val appSource: DeviceAppSource = AndroidDeviceAppSource(appContext),
  private val permissionSnapshot: () -> AndroidPermissionSnapshot,
) {
  constructor(
    appContext: Context,
    smsEnabled: Boolean = SensitiveFeatureConfig.smsEnabled,
    callLogEnabled: Boolean = SensitiveFeatureConfig.callLogEnabled,
    photosEnabled: Boolean = SensitiveFeatureConfig.photosEnabled,
    backgroundLocationEnabled: Boolean = SensitiveFeatureConfig.backgroundLocationEnabled,
  ) : this(
    appContext = appContext,
    smsEnabled = smsEnabled,
    callLogEnabled = callLogEnabled,
    photosEnabled = photosEnabled,
    appSource = AndroidDeviceAppSource(appContext),
    permissionSnapshot = {
      readAndroidPermissionSnapshot(
        context = appContext,
        smsEnabled = smsEnabled,
        callLogEnabled = callLogEnabled,
        photosEnabled = photosEnabled,
        backgroundLocationEnabled = backgroundLocationEnabled,
      )
    },
  )

  companion object {
    internal fun withPermissionSnapshot(
      appContext: Context,
      smsEnabled: Boolean,
      callLogEnabled: Boolean,
      photosEnabled: Boolean,
      permissionSnapshot: () -> AndroidPermissionSnapshot,
    ): DeviceHandler =
      DeviceHandler(
        appContext = appContext,
        smsEnabled = smsEnabled,
        callLogEnabled = callLogEnabled,
        photosEnabled = photosEnabled,
        appSource = AndroidDeviceAppSource(appContext),
        permissionSnapshot = permissionSnapshot,
      )

    internal fun forTesting(
      appContext: Context,
      appSource: DeviceAppSource,
      smsEnabled: Boolean = SensitiveFeatureConfig.smsEnabled,
      callLogEnabled: Boolean = SensitiveFeatureConfig.callLogEnabled,
      photosEnabled: Boolean = SensitiveFeatureConfig.photosEnabled,
      backgroundLocationEnabled: Boolean = SensitiveFeatureConfig.backgroundLocationEnabled,
      permissionSnapshot: (() -> AndroidPermissionSnapshot)? = null,
    ): DeviceHandler =
      DeviceHandler(
        appContext = appContext,
        smsEnabled = smsEnabled,
        callLogEnabled = callLogEnabled,
        photosEnabled = photosEnabled,
        appSource = appSource,
        permissionSnapshot =
          permissionSnapshot ?: {
            readAndroidPermissionSnapshot(
              context = appContext,
              smsEnabled = smsEnabled,
              callLogEnabled = callLogEnabled,
              photosEnabled = photosEnabled,
              backgroundLocationEnabled = backgroundLocationEnabled,
            )
          },
      )

    /**
     * SMS is available only when the feature flag, telephony hardware, and at least one SMS permission align.
     */
    internal fun hasAnySmsCapability(
      smsEnabled: Boolean,
      telephonyAvailable: Boolean,
      smsSendGranted: Boolean,
      smsReadGranted: Boolean,
    ): Boolean = smsEnabled && telephonyAvailable && (smsSendGranted || smsReadGranted)

    /**
     * Prompt only when Android can grant a missing SMS permission that this build can use.
     */
    internal fun isSmsPromptable(
      smsEnabled: Boolean,
      telephonyAvailable: Boolean,
      smsSendGranted: Boolean,
      smsReadGranted: Boolean,
    ): Boolean = smsEnabled && telephonyAvailable && (!smsSendGranted || !smsReadGranted)
  }

  private data class BatterySnapshot(
    val status: Int,
    val plugged: Int,
    val levelFraction: Double?,
    val temperatureC: Double?,
  )

  /** Returns battery, storage, network, and uptime state for device.status. */
  fun handleDeviceStatus(_paramsJson: String?): GatewaySession.InvokeResult = GatewaySession.InvokeResult.ok(statusPayloadJson())

  /** Returns stable Android hardware, OS, app, and locale metadata for device.info. */
  fun handleDeviceInfo(_paramsJson: String?): GatewaySession.InvokeResult = GatewaySession.InvokeResult.ok(infoPayloadJson())

  /** Returns permission and promptability state for Android capabilities exposed to the gateway. */
  fun handleDevicePermissions(_paramsJson: String?): GatewaySession.InvokeResult = GatewaySession.InvokeResult.ok(permissionsPayloadJson())

  /** Returns coarse device health for memory, power, thermal, battery, and security patch state. */
  fun handleDeviceHealth(_paramsJson: String?): GatewaySession.InvokeResult = GatewaySession.InvokeResult.ok(healthPayloadJson())

  fun handleDeviceApps(paramsJson: String?): GatewaySession.InvokeResult {
    val request = parseDeviceAppsRequest(paramsJson)
    val matchingApps =
      appSource
        .listApps(includeNonLaunchable = request.includeNonLaunchable)
        .asSequence()
        .filter { request.includeSystem || !it.system }
        .filter { request.includeDisabled || it.enabled }
        .filter { app ->
          val query = request.query ?: return@filter true
          app.label.contains(query, ignoreCase = true) || app.packageName.contains(query, ignoreCase = true)
        }.toList()
    val limitedApps = matchingApps.take(request.limit)

    return GatewaySession.InvokeResult.ok(
      buildJsonObject {
        put("count", JsonPrimitive(limitedApps.size))
        put("totalMatched", JsonPrimitive(matchingApps.size))
        put("truncated", JsonPrimitive(matchingApps.size > limitedApps.size))
        put("visibility", JsonPrimitive(if (request.includeNonLaunchable) "android-visible" else "launcher"))
        put("includeSystem", JsonPrimitive(request.includeSystem))
        put("includeDisabled", JsonPrimitive(request.includeDisabled))
        put(
          "apps",
          buildJsonArray {
            for (app in limitedApps) {
              add(
                buildJsonObject {
                  put("label", JsonPrimitive(app.label))
                  put("packageName", JsonPrimitive(app.packageName))
                  put("system", JsonPrimitive(app.system))
                  put("enabled", JsonPrimitive(app.enabled))
                  put("launchable", JsonPrimitive(app.launchable))
                },
              )
            }
          },
        )
      }.toString(),
    )
  }

  private fun statusPayloadJson(): String {
    val battery = readBatterySnapshot()
    val powerManager = appContext.getSystemService(PowerManager::class.java)
    val storage = StatFs(Environment.getDataDirectory().absolutePath)
    val totalBytes = storage.totalBytes
    val freeBytes = storage.availableBytes
    val usedBytes = (totalBytes - freeBytes).coerceAtLeast(0L)
    val connectivity = appContext.getSystemService(ConnectivityManager::class.java)
    val activeNetwork = connectivity?.activeNetwork
    val caps = activeNetwork?.let { connectivity.getNetworkCapabilities(it) }
    // elapsedRealtime is monotonic device uptime, not wall-clock time.
    val uptimeSeconds = SystemClock.elapsedRealtime() / 1_000.0

    return buildJsonObject {
      put(
        "battery",
        buildJsonObject {
          battery.levelFraction?.let { put("level", JsonPrimitive(it)) }
          put("state", JsonPrimitive(mapBatteryState(battery.status)))
          put("lowPowerModeEnabled", JsonPrimitive(powerManager?.isPowerSaveMode == true))
        },
      )
      put(
        "thermal",
        buildJsonObject {
          put("state", JsonPrimitive(mapThermalState(powerManager)))
        },
      )
      put(
        "storage",
        buildJsonObject {
          put("totalBytes", JsonPrimitive(totalBytes))
          put("freeBytes", JsonPrimitive(freeBytes))
          put("usedBytes", JsonPrimitive(usedBytes))
        },
      )
      put(
        "network",
        buildJsonObject {
          put("status", JsonPrimitive(mapNetworkStatus(caps)))
          put(
            "isExpensive",
            JsonPrimitive(
              caps?.hasCapability(NetworkCapabilities.NET_CAPABILITY_NOT_METERED)?.not() ?: false,
            ),
          )
          put(
            "isConstrained",
            JsonPrimitive(
              caps?.hasCapability(NetworkCapabilities.NET_CAPABILITY_NOT_RESTRICTED)?.not() ?: false,
            ),
          )
          put("interfaces", networkInterfacesJson(caps))
        },
      )
      put("uptimeSeconds", JsonPrimitive(uptimeSeconds))
    }.toString()
  }

  private fun infoPayloadJson(): String {
    val model = Build.MODEL?.trim().orEmpty()
    val manufacturer = Build.MANUFACTURER?.trim().orEmpty()
    val modelIdentifier = Build.DEVICE?.trim().orEmpty()
    val systemVersion =
      Build.VERSION.RELEASE
        ?.trim()
        .orEmpty()
    val locale = Locale.getDefault().toLanguageTag().trim()
    val appVersion = BuildConfig.VERSION_NAME.trim()
    val appBuild = BuildConfig.VERSION_CODE.toString()

    return buildJsonObject {
      put("deviceName", JsonPrimitive(model.ifEmpty { "Android" }))
      put(
        "modelIdentifier",
        JsonPrimitive(modelIdentifier.ifEmpty { listOf(manufacturer, model).filter { it.isNotEmpty() }.joinToString(" ") }),
      )
      put("systemName", JsonPrimitive("Android"))
      put("systemVersion", JsonPrimitive(systemVersion.ifEmpty { Build.VERSION.SDK_INT.toString() }))
      put("appVersion", JsonPrimitive(appVersion.ifEmpty { "dev" }))
      put("appBuild", JsonPrimitive(appBuild.ifEmpty { "0" }))
      put("locale", JsonPrimitive(locale.ifEmpty { Locale.getDefault().toString() }))
    }.toString()
  }

  private fun permissionsPayloadJson(): String {
    val snapshot = permissionSnapshot()
    val canSendSms = appContext.packageManager.hasSystemFeature(PackageManager.FEATURE_TELEPHONY)
    return buildJsonObject {
      put(
        "permissions",
        buildJsonObject {
          put(
            "camera",
            permissionStateJson(
              granted = snapshot.camera,
              promptableWhenDenied = true,
            ),
          )
          put(
            "microphone",
            permissionStateJson(
              granted = snapshot.microphone,
              promptableWhenDenied = true,
            ),
          )
          put(
            "location",
            permissionStateJson(
              granted = snapshot.location,
              promptableWhenDenied = true,
            ),
          )
          put(
            "sms",
            buildJsonObject {
              put(
                "status",
                JsonPrimitive(
                  if (hasAnySmsCapability(
                      smsEnabled,
                      canSendSms,
                      snapshot.smsSend,
                      snapshot.smsRead,
                    )
                  ) {
                    "granted"
                  } else {
                    "denied"
                  },
                ),
              )
              put(
                "promptable",
                JsonPrimitive(
                  isSmsPromptable(
                    smsEnabled,
                    canSendSms,
                    snapshot.smsSend,
                    snapshot.smsRead,
                  ),
                ),
              )
              put(
                "capabilities",
                buildJsonObject {
                  put(
                    "send",
                    permissionStateJson(
                      granted = snapshot.smsSend,
                      promptableWhenDenied = smsEnabled && canSendSms,
                    ),
                  )
                  put(
                    "read",
                    permissionStateJson(
                      granted = snapshot.smsRead,
                      promptableWhenDenied = smsEnabled && canSendSms,
                    ),
                  )
                },
              )
            },
          )
          put(
            "notificationListener",
            permissionStateJson(
              granted = snapshot.notificationListener,
              promptableWhenDenied = true,
            ),
          )
          put(
            "notifications",
            permissionStateJson(
              granted = snapshot.notifications,
              promptableWhenDenied = true,
            ),
          )
          put(
            "photos",
            permissionStateJson(
              granted = snapshot.photos,
              promptableWhenDenied = photosEnabled,
            ),
          )
          put(
            "contacts",
            permissionStateJson(
              granted = snapshot.contactsRead && snapshot.contactsWrite,
              promptableWhenDenied = true,
            ),
          )
          put(
            "calendar",
            permissionStateJson(
              granted = snapshot.calendarRead && snapshot.calendarWrite,
              promptableWhenDenied = true,
            ),
          )
          put(
            "callLog",
            permissionStateJson(
              granted = snapshot.callLog,
              promptableWhenDenied = callLogEnabled,
            ),
          )
          put(
            "motion",
            permissionStateJson(
              granted = snapshot.motion,
              promptableWhenDenied = true,
            ),
          )
        },
      )
    }.toString()
  }

  private fun healthPayloadJson(): String {
    val battery = readBatterySnapshot()
    val batteryManager = appContext.getSystemService(BatteryManager::class.java)
    val currentNowUa = batteryManager?.getLongProperty(BatteryManager.BATTERY_PROPERTY_CURRENT_NOW)
    val currentNowMa =
      if (currentNowUa == null || currentNowUa == Long.MIN_VALUE) {
        null
      } else {
        // BatteryManager reports microamps; expose milliamps in the gateway payload.
        currentNowUa.toDouble() / 1_000.0
      }

    val powerManager = appContext.getSystemService(PowerManager::class.java)
    val activityManager = appContext.getSystemService(ActivityManager::class.java)
    val memoryInfo = ActivityManager.MemoryInfo()
    activityManager?.getMemoryInfo(memoryInfo)
    val totalRamBytes = memoryInfo.totalMem.coerceAtLeast(0L)
    val availableRamBytes = memoryInfo.availMem.coerceAtLeast(0L)
    val usedRamBytes = (totalRamBytes - availableRamBytes).coerceAtLeast(0L)
    val lowMemory = memoryInfo.lowMemory
    val memoryPressure = mapMemoryPressure(totalRamBytes, availableRamBytes, lowMemory)

    return buildJsonObject {
      put(
        "memory",
        buildJsonObject {
          put("pressure", JsonPrimitive(memoryPressure))
          put("totalRamBytes", JsonPrimitive(totalRamBytes))
          put("availableRamBytes", JsonPrimitive(availableRamBytes))
          put("usedRamBytes", JsonPrimitive(usedRamBytes))
          put("thresholdBytes", JsonPrimitive(memoryInfo.threshold.coerceAtLeast(0L)))
          put("lowMemory", JsonPrimitive(lowMemory))
        },
      )
      put(
        "battery",
        buildJsonObject {
          put("state", JsonPrimitive(mapBatteryState(battery.status)))
          put("chargingType", JsonPrimitive(mapChargingType(battery.plugged)))
          battery.temperatureC?.let { put("temperatureC", JsonPrimitive(it)) }
          currentNowMa?.let { put("currentMa", JsonPrimitive(it)) }
        },
      )
      put(
        "power",
        buildJsonObject {
          put("dozeModeEnabled", JsonPrimitive(powerManager?.isDeviceIdleMode == true))
          put("lowPowerModeEnabled", JsonPrimitive(powerManager?.isPowerSaveMode == true))
        },
      )
      put(
        "system",
        buildJsonObject {
          Build.VERSION.SECURITY_PATCH
            ?.trim()
            ?.takeIf { it.isNotEmpty() }
            ?.let { put("securityPatchLevel", JsonPrimitive(it)) }
        },
      )
    }.toString()
  }

  private fun parseDeviceAppsRequest(paramsJson: String?): DeviceAppsRequest {
    val params = parseJsonParamsObject(paramsJson)
    val includeSystem = parseJsonBooleanFlag(params, "includeSystem") ?: false
    val includeDisabled = parseJsonBooleanFlag(params, "includeDisabled") ?: false
    val includeNonLaunchable = parseJsonBooleanFlag(params, "includeNonLaunchable") ?: false
    val query = parseJsonString(params, "query")?.trim()?.takeIf { it.isNotEmpty() }
    val limit =
      (parseJsonInt(params, "limit") ?: DEFAULT_DEVICE_APPS_LIMIT)
        .coerceIn(1, MAX_DEVICE_APPS_LIMIT)
    return DeviceAppsRequest(
      includeSystem = includeSystem,
      includeDisabled = includeDisabled,
      includeNonLaunchable = includeNonLaunchable,
      query = query,
      limit = limit,
    )
  }

  private fun readBatterySnapshot(): BatterySnapshot {
    // ACTION_BATTERY_CHANGED is sticky; registerReceiver(null, ...) reads the last system snapshot.
    val intent = appContext.registerReceiver(null, IntentFilter(Intent.ACTION_BATTERY_CHANGED))
    val status =
      intent?.getIntExtra(BatteryManager.EXTRA_STATUS, BatteryManager.BATTERY_STATUS_UNKNOWN)
        ?: BatteryManager.BATTERY_STATUS_UNKNOWN
    val plugged = intent?.getIntExtra(BatteryManager.EXTRA_PLUGGED, 0) ?: 0
    val temperatureC =
      intent
        ?.getIntExtra(BatteryManager.EXTRA_TEMPERATURE, Int.MIN_VALUE)
        ?.takeIf { it != Int.MIN_VALUE }
        ?.toDouble()
        ?.div(10.0)
    return BatterySnapshot(
      status = status,
      plugged = plugged,
      levelFraction = batteryLevelFraction(intent),
      temperatureC = temperatureC,
    )
  }

  private fun batteryLevelFraction(intent: Intent?): Double? {
    val rawLevel = intent?.getIntExtra(BatteryManager.EXTRA_LEVEL, -1) ?: -1
    val rawScale = intent?.getIntExtra(BatteryManager.EXTRA_SCALE, -1) ?: -1
    if (rawLevel < 0 || rawScale <= 0) return null
    return rawLevel.toDouble() / rawScale.toDouble()
  }

  private fun mapBatteryState(status: Int): String =
    when (status) {
      BatteryManager.BATTERY_STATUS_CHARGING -> "charging"
      BatteryManager.BATTERY_STATUS_FULL -> "full"
      BatteryManager.BATTERY_STATUS_DISCHARGING, BatteryManager.BATTERY_STATUS_NOT_CHARGING -> "unplugged"
      else -> "unknown"
    }

  private fun mapChargingType(plugged: Int): String =
    when (plugged) {
      BatteryManager.BATTERY_PLUGGED_AC -> "ac"
      BatteryManager.BATTERY_PLUGGED_USB -> "usb"
      BatteryManager.BATTERY_PLUGGED_WIRELESS -> "wireless"
      BatteryManager.BATTERY_PLUGGED_DOCK -> "dock"
      else -> "none"
    }

  private fun mapThermalState(powerManager: PowerManager?): String {
    val thermal = powerManager?.currentThermalStatus ?: return "nominal"
    return when (thermal) {
      PowerManager.THERMAL_STATUS_NONE, PowerManager.THERMAL_STATUS_LIGHT -> "nominal"
      PowerManager.THERMAL_STATUS_MODERATE -> "fair"
      PowerManager.THERMAL_STATUS_SEVERE -> "serious"
      PowerManager.THERMAL_STATUS_CRITICAL,
      PowerManager.THERMAL_STATUS_EMERGENCY,
      PowerManager.THERMAL_STATUS_SHUTDOWN,
      -> "critical"
      else -> "nominal"
    }
  }

  private fun mapNetworkStatus(caps: NetworkCapabilities?): String {
    if (caps == null) return "unsatisfied"
    return when {
      caps.hasCapability(NetworkCapabilities.NET_CAPABILITY_VALIDATED) -> "satisfied"
      // Internet without validation mirrors iOS "requiresConnection" for captive or unproven networks.
      caps.hasCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET) -> "requiresConnection"
      else -> "unsatisfied"
    }
  }

  private fun permissionStateJson(
    granted: Boolean,
    promptableWhenDenied: Boolean,
  ) = buildJsonObject {
    put("status", JsonPrimitive(if (granted) "granted" else "denied"))
    put("promptable", JsonPrimitive(!granted && promptableWhenDenied))
  }

  private fun mapMemoryPressure(
    totalBytes: Long,
    availableBytes: Long,
    lowMemory: Boolean,
  ): String {
    if (totalBytes <= 0L) return if (lowMemory) "critical" else "unknown"
    if (lowMemory) return "critical"
    val freeRatio = availableBytes.toDouble() / totalBytes.toDouble()
    // Thresholds intentionally mirror coarse OS health labels instead of exact memory pressure.
    return when {
      freeRatio <= 0.05 -> "critical"
      freeRatio <= 0.15 -> "high"
      freeRatio <= 0.30 -> "moderate"
      else -> "normal"
    }
  }

  private fun networkInterfacesJson(caps: NetworkCapabilities?) =
    buildJsonArray {
      if (caps == null) return@buildJsonArray
      var hasKnownTransport = false
      if (caps.hasTransport(NetworkCapabilities.TRANSPORT_WIFI)) {
        hasKnownTransport = true
        add(JsonPrimitive("wifi"))
      }
      if (caps.hasTransport(NetworkCapabilities.TRANSPORT_CELLULAR)) {
        hasKnownTransport = true
        add(JsonPrimitive("cellular"))
      }
      if (caps.hasTransport(NetworkCapabilities.TRANSPORT_ETHERNET)) {
        hasKnownTransport = true
        add(JsonPrimitive("wired"))
      }
      if (!hasKnownTransport) add(JsonPrimitive("other"))
    }
}

package ai.openclaw.app.node

import ai.openclaw.app.NotificationBurstLimiter
import ai.openclaw.app.SecurePrefs
import ai.openclaw.app.allowsPackage
import ai.openclaw.app.isWithinQuietHours
import ai.openclaw.app.takeUtf16Safe
import android.app.Notification
import android.app.NotificationManager
import android.app.RemoteInput
import android.content.ComponentName
import android.content.Context
import android.content.Intent
import android.service.notification.NotificationListenerService
import android.service.notification.StatusBarNotification
import androidx.core.content.edit
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.JsonPrimitive
import kotlinx.serialization.json.buildJsonObject
import kotlinx.serialization.json.put

private const val MAX_NOTIFICATION_TEXT_CHARS = 512
private const val NOTIFICATIONS_CHANGED_EVENT = "notifications.changed"

/**
 * Trims notification text and caps payload size before it enters gateway-visible state.
 */
internal fun sanitizeNotificationText(value: CharSequence?): String? {
  val normalized = value?.toString()?.trim().orEmpty()
  // Notification extras can include long previews; cap before sending over node events.
  return normalized.takeUtf16Safe(MAX_NOTIFICATION_TEXT_CHARS).ifEmpty { null }
}

/**
 * Keeps app-owned notifications outside the gateway list/action trust boundary.
 */
internal fun isGatewayVisibleNotification(
  appPackageName: String,
  notificationPackageName: String?,
): Boolean {
  val appPackage = appPackageName.trim()
  val notificationPackage = notificationPackageName?.trim().orEmpty()
  return appPackage.isNotEmpty() && notificationPackage.isNotEmpty() && notificationPackage != appPackage
}

/**
 * Stable notification snapshot entry exposed through the Android notifications command.
 */
data class DeviceNotificationEntry(
  val key: String,
  val packageName: String,
  val title: String?,
  val text: String?,
  val subText: String?,
  val category: String?,
  val channelId: String?,
  val postTimeMs: Long,
  val isOngoing: Boolean,
  val isClearable: Boolean,
)

internal fun DeviceNotificationEntry.toJsonObject(): JsonObject =
  buildJsonObject {
    put("key", JsonPrimitive(key))
    put("packageName", JsonPrimitive(packageName))
    put("postTimeMs", JsonPrimitive(postTimeMs))
    put("isOngoing", JsonPrimitive(isOngoing))
    put("isClearable", JsonPrimitive(isClearable))
    title?.let { put("title", JsonPrimitive(it)) }
    text?.let { put("text", JsonPrimitive(it)) }
    subText?.let { put("subText", JsonPrimitive(it)) }
    category?.let { put("category", JsonPrimitive(it)) }
    channelId?.let { put("channelId", JsonPrimitive(it)) }
  }

/**
 * Listener state exposed to the gateway, including whether Android has connected the service.
 */
data class DeviceNotificationSnapshot(
  val enabled: Boolean,
  val connected: Boolean,
  val notifications: List<DeviceNotificationEntry>,
)

/**
 * Gateway-supported notification actions mapped to Android listener operations.
 */
enum class NotificationActionKind {
  Open,
  Dismiss,
  Reply,
}

/**
 * Gateway action request; [key] must match Android's StatusBarNotification key.
 */
data class NotificationActionRequest(
  val key: String,
  val kind: NotificationActionKind,
  val replyText: String? = null,
)

/**
 * Normalized notification action result returned through node.invoke.
 */
data class NotificationActionResult(
  val ok: Boolean,
  val code: String? = null,
  val message: String? = null,
)

internal fun actionRequiresClearableNotification(kind: NotificationActionKind): Boolean = kind == NotificationActionKind.Dismiss

/**
 * Process-local cache of active notifications mirrored from Android listener callbacks.
 */
private object DeviceNotificationStore {
  private val lock = Any()
  private var connected = false
  private val byKey = LinkedHashMap<String, DeviceNotificationEntry>()

  fun replace(entries: List<DeviceNotificationEntry>) {
    synchronized(lock) {
      byKey.clear()
      for (entry in entries) {
        byKey[entry.key] = entry
      }
    }
  }

  fun upsert(entry: DeviceNotificationEntry) {
    synchronized(lock) {
      byKey[entry.key] = entry
    }
  }

  fun remove(key: String) {
    synchronized(lock) {
      byKey.remove(key)
    }
  }

  fun setConnected(value: Boolean) {
    synchronized(lock) {
      connected = value
      if (!value) {
        // Android invalidates activeNotifications when the listener disconnects.
        byKey.clear()
      }
    }
  }

  fun snapshot(
    enabled: Boolean,
    appPackageName: String,
  ): DeviceNotificationSnapshot {
    val (isConnected, entries) =
      synchronized(lock) {
        connected to
          byKey.values
            .filter { isGatewayVisibleNotification(appPackageName, it.packageName) }
            .sortedByDescending { it.postTimeMs }
      }
    return DeviceNotificationSnapshot(
      enabled = enabled,
      connected = isConnected,
      notifications = entries,
    )
  }
}

/**
 * Android notification listener that mirrors notification state and executes gateway actions.
 */
class DeviceNotificationListenerService : NotificationListenerService() {
  private val securePrefs by lazy { SecurePrefs(applicationContext) }
  private val forwardingLimiter = NotificationBurstLimiter()

  override fun onListenerConnected() {
    super.onListenerConnected()
    activeService = this
    DeviceNotificationStore.setConnected(true)
    refreshActiveNotifications()
  }

  override fun onListenerDisconnected() {
    if (activeService === this) {
      activeService = null
    }
    DeviceNotificationStore.setConnected(false)
    super.onListenerDisconnected()
  }

  override fun onDestroy() {
    if (activeService === this) {
      activeService = null
    }
    super.onDestroy()
  }

  override fun onNotificationPosted(sbn: StatusBarNotification?) {
    super.onNotificationPosted(sbn)
    val posted = sbn ?: return
    if (!isGatewayVisibleNotification(packageName, posted.packageName)) return
    val entry = posted.toEntry()
    DeviceNotificationStore.upsert(entry)
    rememberRecentPackage(entry.packageName)
    val payload = notificationChangedPayload(entry) ?: return
    emitNotificationsChanged(payload)
  }

  override fun onNotificationRemoved(sbn: StatusBarNotification?) {
    super.onNotificationRemoved(sbn)
    val removed = sbn ?: return
    val key = removed.key.trim()
    if (key.isEmpty()) {
      return
    }
    DeviceNotificationStore.remove(key)
    rememberRecentPackage(removed.packageName)
    if (removed.packageName == packageName) {
      return
    }
    val packageName = removed.packageName.trim()
    val payload =
      notificationChangedPayload(
        entry = null,
        change = "removed",
        key = key,
        packageName = packageName,
        postTimeMs = removed.postTime,
        isOngoing = removed.isOngoing,
        isClearable = removed.isClearable,
      ) ?: return
    emitNotificationsChanged(payload)
  }

  private fun notificationChangedPayload(entry: DeviceNotificationEntry): String? =
    notificationChangedPayload(
      entry = entry,
      change = "posted",
      key = entry.key,
      packageName = entry.packageName,
      postTimeMs = entry.postTimeMs,
      isOngoing = entry.isOngoing,
      isClearable = entry.isClearable,
    )

  private fun notificationChangedPayload(
    entry: DeviceNotificationEntry?,
    change: String,
    key: String,
    packageName: String,
    postTimeMs: Long,
    isOngoing: Boolean,
    isClearable: Boolean,
  ): String? {
    val normalizedPackage = packageName.trim()
    if (normalizedPackage.isEmpty()) {
      return null
    }
    val policy = securePrefs.getNotificationForwardingPolicy(appPackageName = this.packageName)
    if (!policy.enabled) {
      return null
    }
    if (!policy.allowsPackage(normalizedPackage)) {
      return null
    }
    val nowEpochMs = System.currentTimeMillis()
    if (policy.isWithinQuietHours(nowEpochMs = nowEpochMs)) {
      return null
    }
    // Apply burst limits after package/quiet-hour filters so blocked notifications do not consume quota.
    if (!forwardingLimiter.allow(nowEpochMs, policy.maxEventsPerMinute)) {
      return null
    }
    return buildJsonObject {
      put("change", JsonPrimitive(change))
      put("key", JsonPrimitive(key))
      put("packageName", JsonPrimitive(normalizedPackage))
      put("postTimeMs", JsonPrimitive(postTimeMs))
      put("isOngoing", JsonPrimitive(isOngoing))
      put("isClearable", JsonPrimitive(isClearable))
      policy.sessionKey?.let { put("sessionKey", JsonPrimitive(it)) }
      entry?.title?.let { put("title", JsonPrimitive(it)) }
      entry?.text?.let { put("text", JsonPrimitive(it)) }
      entry?.subText?.let { put("subText", JsonPrimitive(it)) }
      entry?.category?.let { put("category", JsonPrimitive(it)) }
      entry?.channelId?.let { put("channelId", JsonPrimitive(it)) }
    }.toString()
  }

  private fun refreshActiveNotifications() {
    val entries =
      runCatching {
        activeNotifications
          ?.asSequence()
          ?.filter { isGatewayVisibleNotification(packageName, it.packageName) }
          ?.mapNotNull { it.toEntry() }
          ?.toList()
          ?: emptyList()
      }.getOrElse { emptyList() }
    DeviceNotificationStore.replace(entries)
  }

  private fun StatusBarNotification.toEntry(): DeviceNotificationEntry {
    val extras = notification.extras
    val keyValue = key.takeIf { it.isNotBlank() } ?: "$packageName:$id:$postTime"
    val title = sanitizeNotificationText(extras?.getCharSequence(Notification.EXTRA_TITLE))
    val body =
      sanitizeNotificationText(extras?.getCharSequence(Notification.EXTRA_BIG_TEXT))
        ?: sanitizeNotificationText(extras?.getCharSequence(Notification.EXTRA_TEXT))
    val subText = sanitizeNotificationText(extras?.getCharSequence(Notification.EXTRA_SUB_TEXT))
    return DeviceNotificationEntry(
      key = keyValue,
      packageName = packageName,
      title = title,
      text = body,
      subText = subText,
      category = notification.category?.trim()?.ifEmpty { null },
      channelId = notification.channelId?.trim()?.ifEmpty { null },
      postTimeMs = postTime,
      isOngoing = isOngoing,
      isClearable = isClearable,
    )
  }

  companion object {
    private const val recentPackagesPref = "notifications.forwarding.recentPackages"
    private const val legacyRecentPackagesPref = "notifications.recentPackages"
    private const val recentPackagesLimit = 64

    @Volatile private var activeService: DeviceNotificationListenerService? = null

    @Volatile private var nodeEventSink: ((event: String, payloadJson: String?) -> Unit)? = null

    private fun serviceComponent(context: Context): ComponentName = ComponentName(context, DeviceNotificationListenerService::class.java)

    /** Installs the node event sink used to emit filtered notification change events. */
    fun setNodeEventSink(sink: ((event: String, payloadJson: String?) -> Unit)?) {
      nodeEventSink = sink
    }

    private fun recentPackagesPrefs(context: Context) = context.applicationContext.getSharedPreferences("openclaw.secure", Context.MODE_PRIVATE)

    private fun migrateLegacyRecentPackagesIfNeeded(context: Context) {
      val prefs = recentPackagesPrefs(context)
      val hasNew = prefs.contains(recentPackagesPref)
      val legacy = prefs.getString(legacyRecentPackagesPref, null)?.trim().orEmpty()
      if (!hasNew && legacy.isNotEmpty()) {
        // Keep recent package suggestions across the preference-key rename.
        prefs.edit {
          putString(recentPackagesPref, legacy)
          remove(legacyRecentPackagesPref)
        }
      } else if (hasNew && prefs.contains(legacyRecentPackagesPref)) {
        prefs.edit { remove(legacyRecentPackagesPref) }
      }
    }

    /** Returns recent third-party packages seen by the listener for settings suggestions. */
    fun recentPackages(context: Context): List<String> {
      migrateLegacyRecentPackagesIfNeeded(context)
      val prefs = recentPackagesPrefs(context)
      val stored = prefs.getString(recentPackagesPref, null).orEmpty()
      return stored
        .split(',')
        .map { it.trim() }
        .filter { it.isNotEmpty() }
        .distinct()
    }

    /** Checks whether Android has granted listener access to this service component. */
    fun isAccessEnabled(context: Context): Boolean {
      val manager = context.getSystemService(NotificationManager::class.java) ?: return false
      return manager.isNotificationListenerAccessGranted(serviceComponent(context))
    }

    /** Reads the current mirrored notification snapshot without forcing service startup. */
    fun snapshot(
      context: Context,
      enabled: Boolean = isAccessEnabled(context),
    ): DeviceNotificationSnapshot =
      DeviceNotificationStore.snapshot(
        enabled = enabled,
        appPackageName = context.packageName,
      )

    /** Asks Android to rebind the listener after settings grant access but callbacks have not arrived. */
    fun requestServiceRebind(context: Context) {
      runCatching {
        NotificationListenerService.requestRebind(serviceComponent(context))
      }
    }

    /** Executes an open, dismiss, or reply action through the active listener instance. */
    fun executeAction(
      context: Context,
      request: NotificationActionRequest,
    ): NotificationActionResult {
      if (!isAccessEnabled(context)) {
        return NotificationActionResult(
          ok = false,
          code = "NOTIFICATIONS_DISABLED",
          message = "NOTIFICATIONS_DISABLED: enable notification access in system Settings",
        )
      }
      val service =
        activeService
          ?: return NotificationActionResult(
            ok = false,
            code = "NOTIFICATIONS_UNAVAILABLE",
            message = "NOTIFICATIONS_UNAVAILABLE: notification listener not connected",
          )
      return service.executeActionInternal(request)
    }

    private fun emitNotificationsChanged(payloadJson: String) {
      runCatching {
        nodeEventSink?.invoke(NOTIFICATIONS_CHANGED_EVENT, payloadJson)
      }
    }

    private fun rememberRecentPackage(packageName: String?) {
      val service = activeService ?: return
      val normalized = packageName?.trim().orEmpty()
      if (normalized.isEmpty() || normalized == service.packageName) return
      migrateLegacyRecentPackagesIfNeeded(service.applicationContext)
      val prefs = recentPackagesPrefs(service.applicationContext)
      val existing =
        prefs
          .getString(recentPackagesPref, null)
          .orEmpty()
          .split(',')
          .map { it.trim() }
          .filter { it.isNotEmpty() && it != normalized }
          .take(recentPackagesLimit - 1)
      // Most recent package first keeps settings suggestions useful without storing notification content.
      val updated = listOf(normalized) + existing
      prefs.edit { putString(recentPackagesPref, updated.joinToString(",")) }
    }
  }

  private fun executeActionInternal(request: NotificationActionRequest): NotificationActionResult {
    val sbn =
      activeNotifications
        ?.firstOrNull {
          it.key == request.key &&
            isGatewayVisibleNotification(packageName, it.packageName)
        }
        ?: return NotificationActionResult(
          ok = false,
          code = "NOTIFICATION_NOT_FOUND",
          message = "NOTIFICATION_NOT_FOUND: notification key not found",
        )
    if (actionRequiresClearableNotification(request.kind) && !sbn.isClearable) {
      return NotificationActionResult(
        ok = false,
        code = "NOTIFICATION_NOT_CLEARABLE",
        message = "NOTIFICATION_NOT_CLEARABLE: notification is ongoing or protected",
      )
    }

    return when (request.kind) {
      NotificationActionKind.Open -> {
        val pendingIntent =
          sbn.notification.contentIntent
            ?: return NotificationActionResult(
              ok = false,
              code = "ACTION_UNAVAILABLE",
              message = "ACTION_UNAVAILABLE: notification has no open action",
            )
        runCatching {
          pendingIntent.send()
        }.fold(
          onSuccess = { NotificationActionResult(ok = true) },
          onFailure = { err ->
            NotificationActionResult(
              ok = false,
              code = "ACTION_FAILED",
              message = "ACTION_FAILED: ${err.message ?: "open failed"}",
            )
          },
        )
      }

      NotificationActionKind.Dismiss -> {
        runCatching {
          cancelNotification(sbn.key)
          DeviceNotificationStore.remove(sbn.key)
        }.fold(
          onSuccess = { NotificationActionResult(ok = true) },
          onFailure = { err ->
            NotificationActionResult(
              ok = false,
              code = "ACTION_FAILED",
              message = "ACTION_FAILED: ${err.message ?: "dismiss failed"}",
            )
          },
        )
      }

      NotificationActionKind.Reply -> {
        val replyText = request.replyText?.trim().orEmpty()
        if (replyText.isEmpty()) {
          return NotificationActionResult(
            ok = false,
            code = "INVALID_REQUEST",
            message = "INVALID_REQUEST: replyText required for reply action",
          )
        }
        val action =
          sbn.notification.actions
            ?.firstOrNull { candidate ->
              // Android reply actions are identified by RemoteInput, not by a stable action title.
              candidate.actionIntent != null && !candidate.remoteInputs.isNullOrEmpty()
            }
            ?: return NotificationActionResult(
              ok = false,
              code = "ACTION_UNAVAILABLE",
              message = "ACTION_UNAVAILABLE: notification has no reply action",
            )
        val remoteInputs = action.remoteInputs ?: emptyArray()
        val fillInIntent = Intent()
        val replyBundle = android.os.Bundle()
        for (remoteInput in remoteInputs) {
          replyBundle.putCharSequence(remoteInput.resultKey, replyText)
        }
        RemoteInput.addResultsToIntent(remoteInputs, fillInIntent, replyBundle)
        runCatching {
          action.actionIntent.send(this, 0, fillInIntent)
        }.fold(
          onSuccess = { NotificationActionResult(ok = true) },
          onFailure = { err ->
            NotificationActionResult(
              ok = false,
              code = "ACTION_FAILED",
              message = "ACTION_FAILED: ${err.message ?: "reply failed"}",
            )
          },
        )
      }
    }
  }
}

package ai.openclaw.app.node

import ai.openclaw.app.gateway.GatewaySession
import ai.openclaw.app.protocol.OpenClawCalendarCommand
import ai.openclaw.app.protocol.OpenClawCallLogCommand
import ai.openclaw.app.protocol.OpenClawCameraCommand
import ai.openclaw.app.protocol.OpenClawContactsCommand
import ai.openclaw.app.protocol.OpenClawDeviceCommand
import ai.openclaw.app.protocol.OpenClawLocationCommand
import ai.openclaw.app.protocol.OpenClawMobileUiCommand
