/** Runtime state for SMS search, split so permission prompts are not reported as hard unavailability. */
internal enum class SmsSearchAvailabilityReason {
  Available,
  PermissionRequired,
  Unavailable,
}

/**
 * Distinguish permanent SMS search unavailability from permission-gated search.
 */
internal fun classifySmsSearchAvailability(
  readSmsAvailable: Boolean,
  smsFeatureEnabled: Boolean,
  smsTelephonyAvailable: Boolean,
): SmsSearchAvailabilityReason {
  if (readSmsAvailable) return SmsSearchAvailabilityReason.Available
  if (!smsFeatureEnabled || !smsTelephonyAvailable) return SmsSearchAvailabilityReason.Unavailable
  return SmsSearchAvailabilityReason.PermissionRequired
}

internal fun smsSearchAvailabilityError(
  readSmsAvailable: Boolean,
  smsFeatureEnabled: Boolean,
  smsTelephonyAvailable: Boolean,
): GatewaySession.InvokeResult? =
  when (
    classifySmsSearchAvailability(
      readSmsAvailable = readSmsAvailable,
      smsFeatureEnabled = smsFeatureEnabled,
      smsTelephonyAvailable = smsTelephonyAvailable,
    )
  ) {
    SmsSearchAvailabilityReason.Available,
    SmsSearchAvailabilityReason.PermissionRequired,
    -> null
    SmsSearchAvailabilityReason.Unavailable ->
      GatewaySession.InvokeResult.error(
        code = "SMS_UNAVAILABLE",
        message = "SMS_UNAVAILABLE: SMS not available on this device",
      )
  }

/**
 * Gateway node.invoke command router for Android-owned capabilities.
 */
class InvokeDispatcher(
  private val cameraHandler: CameraHandler,
  private val locationHandler: LocationHandler,
  private val deviceHandler: DeviceHandler,
  private val notificationsHandler: NotificationsHandler,
  private val systemHandler: SystemHandler,
  private val talkHandler: TalkHandler,
  private val photosHandler: PhotosHandler,
  private val contactsHandler: ContactsHandler,
  private val calendarHandler: CalendarHandler,
  private val motionHandler: MotionHandler,
  private val smsHandler: SmsHandler,
  private val debugHandler: DebugHandler,
  private val callLogHandler: CallLogHandler,
  private val mobileUiHandler: MobileUiHandler,
  private val isForeground: () -> Boolean,
  private val cameraEnabled: () -> Boolean,
  private val locationEnabled: () -> Boolean,
  private val sendSmsAvailable: () -> Boolean,
  private val readSmsAvailable: () -> Boolean,
  private val smsFeatureEnabled: () -> Boolean,
  private val smsTelephonyAvailable: () -> Boolean,
  private val callLogAvailable: () -> Boolean,
  private val photosAvailable: () -> Boolean,
  private val installedAppsSharingEnabled: () -> Boolean,
  private val debugBuild: () -> Boolean,
  private val motionActivityAvailable: () -> Boolean,
  private val motionPedometerAvailable: () -> Boolean,
  private val mobileUiAvailable: () -> Boolean,
) {
  /** Dispatches one gateway node.invoke command after foreground and availability gates pass. */
  suspend fun handleInvoke(
    command: String,
    paramsJson: String?,
  ): GatewaySession.InvokeResult {
    val spec =
      InvokeCommandRegistry.find(command)
        ?: return GatewaySession.InvokeResult.error(
          code = "INVALID_REQUEST",
          message = "INVALID_REQUEST: unknown command",
        )
    if (spec.requiresForeground && !isForeground()) {
      // Foreground-only commands need an active Activity surface before touching UI or capture APIs.
      return GatewaySession.InvokeResult.error(
        code = "NODE_BACKGROUND_UNAVAILABLE",
        message = "NODE_BACKGROUND_UNAVAILABLE: command requires foreground",
      )
    }
    availabilityError(spec.availability)?.let { return it }

    return dispatchInvoke(command, paramsJson)
  }

  private suspend fun dispatchInvoke(
    command: String,
    paramsJson: String?,
  ): GatewaySession.InvokeResult {
    // Command strings come from OpenClawProtocolConstants; the registry above owns advertised availability.
    return when (command) {
      // Camera commands
      OpenClawCameraCommand.List.rawValue -> cameraHandler.handleList(paramsJson)
      OpenClawCameraCommand.Snap.rawValue -> cameraHandler.handleSnap(paramsJson)
      OpenClawCameraCommand.Clip.rawValue -> cameraHandler.handleClip(paramsJson)

      // Location command
      OpenClawLocationCommand.Get.rawValue -> locationHandler.handleLocationGet(paramsJson)

      // Device commands
      OpenClawDeviceCommand.Status.rawValue -> deviceHandler.handleDeviceStatus(paramsJson)
      OpenClawDeviceCommand.Info.rawValue -> deviceHandler.handleDeviceInfo(paramsJson)
      OpenClawDeviceCommand.Permissions.rawValue -> deviceHandler.handleDevicePermissions(paramsJson)
      OpenClawDeviceCommand.Health.rawValue -> deviceHandler.handleDeviceHealth(paramsJson)
      OpenClawDeviceCommand.Apps.rawValue -> deviceHandler.handleDeviceApps(paramsJson)

      // Notifications command
      OpenClawNotificationsCommand.List.rawValue -> notificationsHandler.handleNotificationsList(paramsJson)
      OpenClawNotificationsCommand.Actions.rawValue -> notificationsHandler.handleNotificationsActions(paramsJson)

      // System command
      OpenClawSystemCommand.Notify.rawValue -> systemHandler.handleSystemNotify(paramsJson)

      // Talk commands
      OpenClawTalkCommand.PttStart.rawValue -> talkHandler.handlePttStart(paramsJson)
      OpenClawTalkCommand.PttStop.rawValue -> talkHandler.handlePttStop(paramsJson)
      OpenClawTalkCommand.PttCancel.rawValue -> talkHandler.handlePttCancel(paramsJson)
      OpenClawTalkCommand.PttOnce.rawValue -> talkHandler.handlePttOnce(paramsJson)

      // Photos command
      ai.openclaw.app.protocol.OpenClawPhotosCommand.Latest.rawValue ->
        photosHandler.handlePhotosLatest(
          paramsJson,
        )

      // Contacts command
      OpenClawContactsCommand.Search.rawValue -> contactsHandler.handleContactsSearch(paramsJson)
      OpenClawContactsCommand.Add.rawValue -> contactsHandler.handleContactsAdd(paramsJson)

      // Calendar command
      OpenClawCalendarCommand.Events.rawValue -> calendarHandler.handleCalendarEvents(paramsJson)
      OpenClawCalendarCommand.Add.rawValue -> calendarHandler.handleCalendarAdd(paramsJson)

      // Motion command
      OpenClawMotionCommand.Activity.rawValue -> motionHandler.handleMotionActivity(paramsJson)
      OpenClawMotionCommand.Pedometer.rawValue -> motionHandler.handleMotionPedometer(paramsJson)

      // SMS command
      OpenClawSmsCommand.Send.rawValue -> smsHandler.handleSmsSend(paramsJson)
      OpenClawSmsCommand.Search.rawValue -> smsHandler.handleSmsSearch(paramsJson)

      // CallLog command
      OpenClawCallLogCommand.Search.rawValue -> callLogHandler.handleCallLogSearch(paramsJson)

      // Mobile accessibility commands
      OpenClawMobileUiCommand.Observe.rawValue -> mobileUiHandler.handleObserve(paramsJson)
      OpenClawMobileUiCommand.Act.rawValue -> mobileUiHandler.handleAct(paramsJson)

      // Debug commands
      "debug.ed25519" -> debugHandler.handleEd25519()
      "debug.logs" -> debugHandler.handleLogs()
      else -> GatewaySession.InvokeResult.error(code = "INVALID_REQUEST", message = "INVALID_REQUEST: unknown command")
    }
  }

  private fun availabilityError(availability: InvokeCommandAvailability): GatewaySession.InvokeResult? =
    when (availability) {
      InvokeCommandAvailability.Always -> null
      InvokeCommandAvailability.CameraEnabled ->
        if (cameraEnabled()) {
          null
        } else {
          GatewaySession.InvokeResult.error(
            code = "CAMERA_DISABLED",
            message = "CAMERA_DISABLED: enable Camera in Settings",
          )
        }
      InvokeCommandAvailability.LocationEnabled ->
        if (locationEnabled()) {
          null
        } else {
          GatewaySession.InvokeResult.error(
            code = "LOCATION_DISABLED",
            message = "LOCATION_DISABLED: enable Location in Settings",
          )
        }
      InvokeCommandAvailability.MotionActivityAvailable ->
        if (motionActivityAvailable()) {
          null
        } else {
          GatewaySession.InvokeResult.error(
            code = "MOTION_UNAVAILABLE",
            message = "MOTION_UNAVAILABLE: accelerometer not available",
          )
        }
      InvokeCommandAvailability.MotionPedometerAvailable ->
        if (motionPedometerAvailable()) {
          null
        } else {
          GatewaySession.InvokeResult.error(
            code = "PEDOMETER_UNAVAILABLE",
            message = "PEDOMETER_UNAVAILABLE: step counter not available",
          )
        }
      InvokeCommandAvailability.SendSmsAvailable ->
        if (sendSmsAvailable()) {
          null
        } else {
          GatewaySession.InvokeResult.error(
            code = "SMS_UNAVAILABLE",
            message = "SMS_UNAVAILABLE: SMS not available on this device",
          )
        }
      InvokeCommandAvailability.ReadSmsAvailable,
      InvokeCommandAvailability.RequestableSmsSearchAvailable,
      ->
        // SMS search may still be advertised as promptable; runtime invoke fails only on permanent unavailability.
        smsSearchAvailabilityError(
          readSmsAvailable = readSmsAvailable(),
          smsFeatureEnabled = smsFeatureEnabled(),
          smsTelephonyAvailable = smsTelephonyAvailable(),
        )
      InvokeCommandAvailability.CallLogAvailable ->
        if (callLogAvailable()) {
          null
        } else {
          GatewaySession.InvokeResult.error(
            code = "CALL_LOG_UNAVAILABLE",
            message = "CALL_LOG_UNAVAILABLE: call log not available on this build",
          )
        }
      InvokeCommandAvailability.PhotosAvailable ->
        if (photosAvailable()) {
          null
        } else {
          GatewaySession.InvokeResult.error(
            code = "PHOTOS_UNAVAILABLE",
            message = "PHOTOS_UNAVAILABLE: photos not available on this build",
          )
        }
      InvokeCommandAvailability.InstalledAppsSharingEnabled ->
        if (installedAppsSharingEnabled()) {
          null
        } else {
          GatewaySession.InvokeResult.error(
            code = "INSTALLED_APPS_SHARING_DISABLED",
            message = "INSTALLED_APPS_SHARING_DISABLED: enable Installed Apps in Settings",
          )
        }
      InvokeCommandAvailability.DebugBuild ->
        if (debugBuild()) {
          null
        } else {
          GatewaySession.InvokeResult.error(
            code = "INVALID_REQUEST",
            message = "INVALID_REQUEST: unknown command",
          )
        }
      InvokeCommandAvailability.MobileUiAvailable ->
        if (mobileUiAvailable()) {
          null
        } else {
          GatewaySession.InvokeResult.error(
            code = "MOBILE_UI_UNAVAILABLE",
            message = "MOBILE_UI_UNAVAILABLE: accessibility service is not connected",
          )
        }
    }
}

/**
 * Talk-mode command adapter implemented by the voice subsystem.
 */
interface TalkHandler {
  /** Starts a push-to-talk capture session and keeps it open until stop or cancel. */
  suspend fun handlePttStart(paramsJson: String?): GatewaySession.InvokeResult

  /** Finishes the active push-to-talk capture and submits recognized speech. */
  suspend fun handlePttStop(paramsJson: String?): GatewaySession.InvokeResult

  /** Aborts the active push-to-talk capture without submitting speech. */
  suspend fun handlePttCancel(paramsJson: String?): GatewaySession.InvokeResult

  /** Runs a bounded one-shot push-to-talk capture. */
  suspend fun handlePttOnce(paramsJson: String?): GatewaySession.InvokeResult
}

package ai.openclaw.app.node

import android.graphics.Bitmap
import android.graphics.Matrix
import androidx.exifinterface.media.ExifInterface
import java.io.InputStream
import kotlin.math.max
import kotlin.math.min
import kotlin.math.roundToInt

/**
 * Result of a JPEG compression attempt after quality and scale reductions.
 */
internal data class JpegSizeLimiterResult(
  val bytes: ByteArray,
  val width: Int,
  val height: Int,
  val quality: Int,
)

/**
 * Utility that searches quality/scale combinations until a JPEG fits a byte budget.
 */
internal object JpegSizeLimiter {
  fun readOrientation(open: () -> InputStream?): Int =
    try {
      open()?.use { stream ->
        ExifInterface(stream).getAttributeInt(ExifInterface.TAG_ORIENTATION, ExifInterface.ORIENTATION_NORMAL)
      } ?: ExifInterface.ORIENTATION_NORMAL
    } catch (_: Exception) {
      ExifInterface.ORIENTATION_NORMAL
    }

  /** Applies camera/gallery orientation before resize, display, or metadata-stripping JPEG encoding. */
  fun normalizeOrientation(
    bitmap: Bitmap,
    orientation: Int,
  ): Bitmap {
    val matrix = Matrix()
    when (orientation) {
      ExifInterface.ORIENTATION_ROTATE_90 -> matrix.postRotate(90f)
      ExifInterface.ORIENTATION_ROTATE_180 -> matrix.postRotate(180f)
      ExifInterface.ORIENTATION_ROTATE_270 -> matrix.postRotate(270f)
      ExifInterface.ORIENTATION_FLIP_HORIZONTAL -> matrix.postScale(-1f, 1f)
      ExifInterface.ORIENTATION_FLIP_VERTICAL -> matrix.postScale(1f, -1f)
      ExifInterface.ORIENTATION_TRANSPOSE -> {
        matrix.postRotate(90f)
        matrix.postScale(-1f, 1f)
      }
      ExifInterface.ORIENTATION_TRANSVERSE -> {
        matrix.postRotate(-90f)
        matrix.postScale(-1f, 1f)
      }
      else -> return bitmap
    }
    return Bitmap.createBitmap(bitmap, 0, 0, bitmap.width, bitmap.height, matrix, true).also { oriented ->
      if (oriented !== bitmap) bitmap.recycle()
    }
  }

  /** Compresses with the caller-provided encoder, reducing quality before image dimensions. */
  fun compressToLimit(
    initialWidth: Int,
    initialHeight: Int,
    startQuality: Int,
    maxBytes: Int,
    minQuality: Int = 20,
    minSize: Int = 256,
    scaleStep: Double = 0.85,
    maxScaleAttempts: Int = 6,
    maxQualityAttempts: Int = 6,
    encode: (width: Int, height: Int, quality: Int) -> ByteArray,
  ): JpegSizeLimiterResult {
    require(initialWidth > 0 && initialHeight > 0) { "Invalid image size" }
    require(maxBytes > 0) { "Invalid maxBytes" }

    val clampedStartQuality = startQuality.coerceIn(minQuality, 100)
    var width = initialWidth
    var height = initialHeight
    var best: JpegSizeLimiterResult? = null

    repeat(maxScaleAttempts + 1) { scaleAttempt ->
      var quality = clampedStartQuality
      repeat(maxQualityAttempts) {
        val bytes = encode(width, height, quality)
        val attempt = JpegSizeLimiterResult(bytes = bytes, width = width, height = height, quality = quality)
        best = attempt
        if (bytes.size <= maxBytes) return best
        if (quality <= minQuality) return@repeat
        quality = max(minQuality, (quality * 0.75).roundToInt())
      }

      if (scaleAttempt == maxScaleAttempts) return@repeat
      val minScale = (minSize.toDouble() / min(width, height).toDouble()).coerceAtMost(1.0)
      val nextScale = max(scaleStep, minScale)
      val nextWidth = max(minSize, (width * nextScale).roundToInt())
      val nextHeight = max(minSize, (height * nextScale).roundToInt())
      if (nextWidth == width && nextHeight == height) return@repeat
      width = min(nextWidth, width)
      height = min(nextHeight, height)
    }

    val failed = checkNotNull(best)
    if (failed.bytes.size > maxBytes) {
      throw IllegalStateException("CAMERA_TOO_LARGE: ${failed.bytes.size} bytes > $maxBytes bytes")
    }

    return failed
  }
}

package ai.openclaw.app.node

import android.Manifest
import android.content.Context
import android.content.pm.PackageManager
import android.location.Location
import android.location.LocationListener
import android.location.LocationManager
import android.os.CancellationSignal
import android.os.Looper
import androidx.core.content.ContextCompat
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.suspendCancellableCoroutine
import kotlinx.coroutines.withContext
import kotlinx.coroutines.withTimeout
import java.time.Instant
import java.time.format.DateTimeFormatter

/**
 * Android LocationManager-backed capture used by gateway location commands.
 */
class LocationCaptureManager(
  private val context: Context,
) {
  data class Payload(
    val payloadJson: String,
  )

  suspend fun getLocation(
    desiredProviders: List<String>,
    maxAgeMs: Long?,
    timeoutMs: Long,
    isPrecise: Boolean,
  ): Payload =
    withContext(Dispatchers.Main) {
      val manager = context.getSystemService(Context.LOCATION_SERVICE) as LocationManager
      if (!manager.isProviderEnabled(LocationManager.GPS_PROVIDER) &&
        !manager.isProviderEnabled(LocationManager.NETWORK_PROVIDER)
      ) {
        throw IllegalStateException("LOCATION_UNAVAILABLE: no location providers enabled")
      }

      // Prefer a recent cached fix before waking GPS/network providers.
      val location =
        bestLastKnown(manager, desiredProviders, maxAgeMs)
          ?: requestCurrent(manager, desiredProviders, timeoutMs, maxAgeMs)

      val timestamp = DateTimeFormatter.ISO_INSTANT.format(Instant.ofEpochMilli(location.time))
      val source = location.provider
      val altitudeMeters = if (location.hasAltitude()) location.altitude else null
      val speedMps = if (location.hasSpeed()) location.speed.toDouble() else null
      val headingDeg = if (location.hasBearing()) location.bearing.toDouble() else null
      Payload(
        buildString {
          append("{\"lat\":")
          append(location.latitude)
          append(",\"lon\":")
          append(location.longitude)
          append(",\"accuracyMeters\":")
          append(location.accuracy.toDouble())
          if (altitudeMeters != null) append(",\"altitudeMeters\":").append(altitudeMeters)
          if (speedMps != null) append(",\"speedMps\":").append(speedMps)
          if (headingDeg != null) append(",\"headingDeg\":").append(headingDeg)
          append(",\"timestamp\":\"").append(timestamp).append('"')
          append(",\"isPrecise\":").append(isPrecise)
          append(",\"source\":\"").append(source).append('"')
          append('}')
        },
      )
    }

  private fun bestLastKnown(
    manager: LocationManager,
    providers: List<String>,
    maxAgeMs: Long?,
  ): Location? {
    val fineOk =
      ContextCompat.checkSelfPermission(context, Manifest.permission.ACCESS_FINE_LOCATION) ==
        PackageManager.PERMISSION_GRANTED
    val coarseOk =
      ContextCompat.checkSelfPermission(context, Manifest.permission.ACCESS_COARSE_LOCATION) ==
        PackageManager.PERMISSION_GRANTED
    if (!fineOk && !coarseOk) {
      throw IllegalStateException("LOCATION_PERMISSION_REQUIRED: grant Location permission")
    }
    // maxAgeMs applies to every successful fix, regardless of which Android API supplied it.
    return providers
      .mapNotNull { provider -> manager.getLastKnownLocation(provider) }
      .filter { it.isFresh(maxAgeMs) }
      .maxByOrNull { it.time }
  }

  private fun Location.isFresh(maxAgeMs: Long?): Boolean {
    val ageMs = System.currentTimeMillis() - time
    return ageMs >= 0 && (maxAgeMs == null || ageMs <= maxAgeMs)
  }

  private suspend fun requestCurrent(
    manager: LocationManager,
    providers: List<String>,
    timeoutMs: Long,
    maxAgeMs: Long?,
  ): Location {
    val fineOk =
      ContextCompat.checkSelfPermission(context, Manifest.permission.ACCESS_FINE_LOCATION) ==
        PackageManager.PERMISSION_GRANTED
    val coarseOk =
      ContextCompat.checkSelfPermission(context, Manifest.permission.ACCESS_COARSE_LOCATION) ==
        PackageManager.PERMISSION_GRANTED
    if (!fineOk && !coarseOk) {
      throw IllegalStateException("LOCATION_PERMISSION_REQUIRED: grant Location permission")
    }
    val resolved =
      providers.firstOrNull { manager.isProviderEnabled(it) }
        ?: throw IllegalStateException("LOCATION_UNAVAILABLE: no providers available")
    // getCurrentLocation can return null; the handler maps timeout/null fixes to gateway error shapes.
    val location =
      withTimeout(timeoutMs.coerceAtLeast(1)) {
        suspendCancellableCoroutine<Location?> { cont ->
          val signal = CancellationSignal()
          var activeListener: LocationListener? = null
          cont.invokeOnCancellation {
            signal.cancel()
            activeListener?.let(manager::removeUpdates)
          }
          manager.getCurrentLocation(resolved, signal, context.mainExecutor) { location ->
            if (!cont.isActive) return@getCurrentLocation
            if (location == null || location.isFresh(maxAgeMs)) {
              cont.resume(location) { _, _, _ -> }
              return@getCurrentLocation
            }
            val listener =
              object : LocationListener {
                override fun onLocationChanged(update: Location) {
                  if (!cont.isActive) {
                    manager.removeUpdates(this)
                    return
                  }
                  if (!update.isFresh(maxAgeMs)) return
                  manager.removeUpdates(this)
                  cont.resume(update) { _, _, _ -> }
                }
              }
            activeListener = listener
            // Cancellation can remove before registration; fence both sides to avoid a live leak.
            if (!cont.isActive) return@getCurrentLocation
            manager.requestLocationUpdates(resolved, 0L, 0f, listener, Looper.getMainLooper())
            if (!cont.isActive) manager.removeUpdates(listener)
          }
        }
      }
    return location ?: throw IllegalStateException("LOCATION_UNAVAILABLE: no fix")
  }
}

package ai.openclaw.app.node

import ai.openclaw.app.LocationMode
import ai.openclaw.app.gateway.GatewaySession
import android.Manifest
import android.content.Context
import android.content.pm.PackageManager
import android.location.LocationManager
import androidx.core.content.ContextCompat
import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.TimeoutCancellationException
import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonPrimitive

/**
 * Injectable location facade for command tests and Android runtime access.
 */
internal interface LocationDataSource {
  fun hasFinePermission(context: Context): Boolean

  fun hasCoarsePermission(context: Context): Boolean

  fun hasBackgroundPermission(context: Context): Boolean

  suspend fun fetchLocation(
    desiredProviders: List<String>,
    maxAgeMs: Long?,
    timeoutMs: Long,
    isPrecise: Boolean,
  ): LocationCaptureManager.Payload
}

private class DefaultLocationDataSource(
  private val capture: LocationCaptureManager,
) : LocationDataSource {
  override fun hasFinePermission(context: Context): Boolean =
    ContextCompat.checkSelfPermission(context, Manifest.permission.ACCESS_FINE_LOCATION) ==
      PackageManager.PERMISSION_GRANTED

  override fun hasCoarsePermission(context: Context): Boolean =
    ContextCompat.checkSelfPermission(context, Manifest.permission.ACCESS_COARSE_LOCATION) ==
      PackageManager.PERMISSION_GRANTED

  override fun hasBackgroundPermission(context: Context): Boolean =
    ContextCompat.checkSelfPermission(context, Manifest.permission.ACCESS_BACKGROUND_LOCATION) ==
      PackageManager.PERMISSION_GRANTED

  override suspend fun fetchLocation(
    desiredProviders: List<String>,
    maxAgeMs: Long?,
    timeoutMs: Long,
    isPrecise: Boolean,
  ): LocationCaptureManager.Payload =
    capture.getLocation(
      desiredProviders = desiredProviders,
      maxAgeMs = maxAgeMs,
      timeoutMs = timeoutMs,
      isPrecise = isPrecise,
    )
}

class LocationHandler private constructor(
  private val appContext: Context,
  private val dataSource: LocationDataSource,
  private val json: Json,
  private val isForeground: () -> Boolean,
  private val locationMode: () -> LocationMode,
  private val backgroundLocationEnabled: () -> Boolean,
  private val locationPreciseEnabled: () -> Boolean,
) {
  constructor(
    appContext: Context,
    location: LocationCaptureManager,
    json: Json,
    isForeground: () -> Boolean,
    locationMode: () -> LocationMode,
    backgroundLocationEnabled: () -> Boolean,
    locationPreciseEnabled: () -> Boolean,
  ) : this(
    appContext = appContext,
    dataSource = DefaultLocationDataSource(location),
    json = json,
    isForeground = isForeground,
    locationMode = locationMode,
    backgroundLocationEnabled = backgroundLocationEnabled,
    locationPreciseEnabled = locationPreciseEnabled,
  )

  /** Reports whether precise GPS-backed location can be requested from Android. */
  fun hasFineLocationPermission(): Boolean = dataSource.hasFinePermission(appContext)

  /** Reports whether network/coarse location can be requested from Android. */
  fun hasCoarseLocationPermission(): Boolean = dataSource.hasCoarsePermission(appContext)

  companion object {
    /** Creates a handler with injected location state for permission and payload tests. */
    internal fun forTesting(
      appContext: Context,
      dataSource: LocationDataSource,
      json: Json = Json { ignoreUnknownKeys = true },
      isForeground: () -> Boolean = { true },
      locationMode: () -> LocationMode = { LocationMode.WhileUsing },
      backgroundLocationEnabled: () -> Boolean = { false },
      locationPreciseEnabled: () -> Boolean = { true },
    ): LocationHandler =
      LocationHandler(
        appContext = appContext,
        dataSource = dataSource,
        json = json,
        isForeground = isForeground,
        locationMode = locationMode,
        backgroundLocationEnabled = backgroundLocationEnabled,
        locationPreciseEnabled = locationPreciseEnabled,
      )
  }

  /** Handles location.get with foreground, permission, and user precision gates applied. */
  suspend fun handleLocationGet(paramsJson: String?): GatewaySession.InvokeResult {
    if (!isForeground() && !allowsBackgroundLocation()) {
      // Android foreground restrictions and user expectation keep live location tied to the visible app.
      return GatewaySession.InvokeResult.error(
        code = "LOCATION_BACKGROUND_UNAVAILABLE",
        message =
          "LOCATION_BACKGROUND_UNAVAILABLE: choose Always and grant background location access",
      )
    }
    if (!dataSource.hasFinePermission(appContext) && !dataSource.hasCoarsePermission(appContext)) {
      return GatewaySession.InvokeResult.error(
        code = "LOCATION_PERMISSION_REQUIRED",
        message = "LOCATION_PERMISSION_REQUIRED: grant Location permission",
      )
    }
    val (maxAgeMs, timeoutMs, desiredAccuracy) = parseLocationParams(paramsJson)
    val preciseEnabled = locationPreciseEnabled()
    // Gateway requests are advisory; Android permission and user settings decide
    // whether precise capture is actually allowed for this invocation.
    val accuracy =
      when (desiredAccuracy) {
        "precise" -> if (preciseEnabled && dataSource.hasFinePermission(appContext)) "precise" else "balanced"
        "coarse" -> "coarse"
        else -> if (preciseEnabled && dataSource.hasFinePermission(appContext)) "precise" else "balanced"
      }
    val providers =
      when (accuracy) {
        // Provider order is part of the accuracy policy: GPS first for precise, network first otherwise.
        "precise" -> listOf(LocationManager.GPS_PROVIDER, LocationManager.NETWORK_PROVIDER)
        "coarse" -> listOf(LocationManager.NETWORK_PROVIDER, LocationManager.GPS_PROVIDER)
        else -> listOf(LocationManager.NETWORK_PROVIDER, LocationManager.GPS_PROVIDER)
      }
    try {
      val payload =
        dataSource.fetchLocation(
          desiredProviders = providers,
          maxAgeMs = maxAgeMs,
          timeoutMs = timeoutMs,
          isPrecise = accuracy == "precise",
        )
      return GatewaySession.InvokeResult.ok(payload.payloadJson)
    } catch (err: TimeoutCancellationException) {
      return GatewaySession.InvokeResult.error(
        code = "LOCATION_TIMEOUT",
        message = "LOCATION_TIMEOUT: no fix in time",
      )
    } catch (err: CancellationException) {
      throw err
    } catch (err: Throwable) {
      val message = err.message ?: "LOCATION_UNAVAILABLE: no fix"
      return GatewaySession.InvokeResult.error(code = "LOCATION_UNAVAILABLE", message = message)
    }
  }

  private fun allowsBackgroundLocation(): Boolean =
    backgroundLocationEnabled() &&
      locationMode() == LocationMode.Always &&
      dataSource.hasBackgroundPermission(appContext)

  private fun parseLocationParams(paramsJson: String?): Triple<Long?, Long, String?> {
    if (paramsJson.isNullOrBlank()) {
      return Triple(null, 10_000L, null)
    }
    val root =
      try {
        json.parseToJsonElement(paramsJson).asObjectOrNull()
      } catch (_: Throwable) {
        null
      }
    val maxAgeMs = (root?.get("maxAgeMs") as? JsonPrimitive)?.content?.toLongOrNull()
    val timeoutMs =
      (root?.get("timeoutMs") as? JsonPrimitive)?.content?.toLongOrNull()?.coerceIn(1_000L, 60_000L)
        ?: 10_000L
    // desiredAccuracy is advisory; invalid values fall through to the default policy.
    val desiredAccuracy =
      (root?.get("desiredAccuracy") as? JsonPrimitive)?.content?.trim()?.lowercase()
    return Triple(maxAgeMs, timeoutMs, desiredAccuracy)
  }
}

package ai.openclaw.app.node

import ai.openclaw.app.gateway.GatewaySession
import android.Manifest
import android.content.Context
import android.hardware.Sensor
import android.hardware.SensorEvent
import android.hardware.SensorEventListener
import android.hardware.SensorManager
import android.os.SystemClock
import androidx.core.content.ContextCompat
import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.InternalCoroutinesApi
import kotlinx.coroutines.suspendCancellableCoroutine
import kotlinx.coroutines.withTimeoutOrNull
import kotlinx.serialization.json.JsonPrimitive
import kotlinx.serialization.json.buildJsonArray
import kotlinx.serialization.json.buildJsonObject
import kotlinx.serialization.json.put
import java.time.Instant
import kotlin.math.abs
import kotlin.math.max
import kotlin.math.sqrt

private const val ACCELEROMETER_SAMPLE_TARGET = 20
private const val ACCELEROMETER_SAMPLE_TIMEOUT_MS = 6_000L

/** Gateway request for motion.activity after parsing and limit bounds. */
internal data class MotionActivityRequest(
  val startISO: String?,
  val endISO: String?,
  val limit: Int,
)

/** Gateway request for motion.pedometer. */
internal data class MotionPedometerRequest(
  val startISO: String?,
  val endISO: String?,
)

/** Motion activity sample returned in gateway-compatible boolean flags. */
internal data class MotionActivityRecord(
  val startISO: String,
  val endISO: String,
  val confidence: String,
  val isWalking: Boolean,
  val isRunning: Boolean,
  val isCycling: Boolean,
  val isAutomotive: Boolean,
  val isStationary: Boolean,
  val isUnknown: Boolean,
)

/** Pedometer sample returned from Android's cumulative step counter. */
internal data class PedometerRecord(
  val startISO: String,
  val endISO: String,
  val steps: Int?,
  val distanceMeters: Double?,
  val floorsAscended: Int?,
  val floorsDescended: Int?,
)

/** Motion data seam for Android sensors and tests. */
internal interface MotionDataSource {
  fun isActivityAvailable(context: Context): Boolean

  fun isPedometerAvailable(context: Context): Boolean

  fun isAvailable(context: Context): Boolean = isActivityAvailable(context) || isPedometerAvailable(context)

  fun hasPermission(context: Context): Boolean

  suspend fun activity(
    context: Context,
    request: MotionActivityRequest,
  ): MotionActivityRecord

  suspend fun pedometer(
    context: Context,
    request: MotionPedometerRequest,
  ): PedometerRecord
}

private object SystemMotionDataSource : MotionDataSource {
  override fun isActivityAvailable(context: Context): Boolean {
    val sensorManager = context.getSystemService(SensorManager::class.java)
    return sensorManager?.getDefaultSensor(Sensor.TYPE_ACCELEROMETER) != null
  }

  override fun isPedometerAvailable(context: Context): Boolean {
    val sensorManager = context.getSystemService(SensorManager::class.java)
    return sensorManager?.getDefaultSensor(Sensor.TYPE_STEP_COUNTER) != null
  }

  override fun hasPermission(context: Context): Boolean =
    ContextCompat.checkSelfPermission(context, Manifest.permission.ACTIVITY_RECOGNITION) ==
      android.content.pm.PackageManager.PERMISSION_GRANTED

  override suspend fun activity(
    context: Context,
    request: MotionActivityRequest,
  ): MotionActivityRecord {
    if (!request.startISO.isNullOrBlank() || !request.endISO.isNullOrBlank()) {
      // Android does not expose historical activity samples here; fail with a
      // stable gateway code instead of pretending the range is empty.
      throw IllegalArgumentException("MOTION_RANGE_UNAVAILABLE: historical activity range not supported on Android")
    }
    val sensorManager =
      context.getSystemService(SensorManager::class.java)
        ?: throw IllegalStateException("MOTION_UNAVAILABLE: sensor manager unavailable")
    val accelerometer =
      sensorManager.getDefaultSensor(Sensor.TYPE_ACCELEROMETER)
        ?: throw IllegalStateException("MOTION_UNAVAILABLE: accelerometer not available")

    val sample =
      readAccelerometerSample(sensorManager, accelerometer)
        ?: throw IllegalStateException("MOTION_UNAVAILABLE: no accelerometer sample")
    val end = Instant.now()
    val start = end.minusSeconds(2)
    val classification = classifyActivity(sample.averageDelta)
    return MotionActivityRecord(
      startISO = start.toString(),
      endISO = end.toString(),
      confidence = classifyConfidence(sample.samples, sample.averageDelta),
      isWalking = classification == "walking",
      isRunning = classification == "running",
      isCycling = false,
      isAutomotive = false,
      isStationary = classification == "stationary",
      isUnknown = classification == "unknown",
    )
  }

  override suspend fun pedometer(
    context: Context,
    request: MotionPedometerRequest,
  ): PedometerRecord {
    if (!request.startISO.isNullOrBlank() || !request.endISO.isNullOrBlank()) {
      // TYPE_STEP_COUNTER is cumulative since boot, not a historical query API.
      throw IllegalArgumentException("PEDOMETER_RANGE_UNAVAILABLE: historical pedometer range not supported on Android")
    }
    val sensorManager =
      context.getSystemService(SensorManager::class.java)
        ?: throw IllegalStateException("PEDOMETER_UNAVAILABLE: sensor manager unavailable")
    val stepCounter =
      sensorManager.getDefaultSensor(Sensor.TYPE_STEP_COUNTER)
        ?: throw IllegalStateException("PEDOMETER_UNAVAILABLE: step counting not supported")

    val steps =
      readStepCounter(sensorManager, stepCounter)
        ?: throw IllegalStateException("PEDOMETER_UNAVAILABLE: no step counter sample")
    val bootMs = System.currentTimeMillis() - SystemClock.elapsedRealtime()
    return PedometerRecord(
      startISO = Instant.ofEpochMilli(max(0L, bootMs)).toString(),
      endISO = Instant.now().toString(),
      steps = steps,
      distanceMeters = null,
      floorsAscended = null,
      floorsDescended = null,
    )
  }

  private data class AccelerometerSample(
    val samples: Int,
    val averageDelta: Double,
  )

  @OptIn(InternalCoroutinesApi::class)
  private suspend fun readStepCounter(
    sensorManager: SensorManager,
    sensor: Sensor,
  ): Int? {
    val sample =
      withTimeoutOrNull(1200L) {
        suspendCancellableCoroutine<Float?> { cont ->
          val listener =
            object : SensorEventListener {
              override fun onSensorChanged(event: SensorEvent?) {
                val value = event?.values?.firstOrNull()
                val token = cont.tryResume(value) ?: return
                cont.completeResume(token)
                sensorManager.unregisterListener(this)
              }

              override fun onAccuracyChanged(
                sensor: Sensor?,
                accuracy: Int,
              ) = Unit
            }
          val registered = sensorManager.registerListener(listener, sensor, SensorManager.SENSOR_DELAY_NORMAL)
          if (!registered) {
            sensorManager.unregisterListener(listener)
            cont.resume(null) { _, _, _ -> }
            return@suspendCancellableCoroutine
          }
          cont.invokeOnCancellation { sensorManager.unregisterListener(listener) }
        }
      }
    return sample?.toInt()?.takeIf { it >= 0 }
  }

  @OptIn(InternalCoroutinesApi::class)
  private suspend fun readAccelerometerSample(
    sensorManager: SensorManager,
    sensor: Sensor,
  ): AccelerometerSample? {
    val sample =
      withTimeoutOrNull(ACCELEROMETER_SAMPLE_TIMEOUT_MS) {
        suspendCancellableCoroutine<AccelerometerSample?> { cont ->
          var count = 0
          var sumDelta = 0.0
          val listener =
            object : SensorEventListener {
              override fun onSensorChanged(event: SensorEvent?) {
                val values = event?.values ?: return
                if (values.size < 3) return
                val magnitude =
                  sqrt(
                    values[0] * values[0] +
                      values[1] * values[1] +
                      values[2] * values[2],
                  ).toDouble()
                sumDelta += abs(magnitude - SensorManager.GRAVITY_EARTH.toDouble())
                count += 1
                if (count >= ACCELEROMETER_SAMPLE_TARGET) {
                  // Average gravity-adjusted magnitude across a short window so
                  // one noisy sensor event cannot decide the activity label.
                  val result =
                    AccelerometerSample(
                      samples = count,
                      averageDelta = sumDelta / count,
                    )
                  val token = cont.tryResume(result) ?: return
                  cont.completeResume(token)
                  sensorManager.unregisterListener(this)
                }
              }

              override fun onAccuracyChanged(
                sensor: Sensor?,
                accuracy: Int,
              ) = Unit
            }
          val registered = sensorManager.registerListener(listener, sensor, SensorManager.SENSOR_DELAY_NORMAL)
          if (!registered) {
            cont.resume(null) { _, _, _ -> }
            return@suspendCancellableCoroutine
          }
          cont.invokeOnCancellation { sensorManager.unregisterListener(listener) }
        }
      }
    return sample
  }

  private fun classifyActivity(averageDelta: Double): String =
    when {
      averageDelta <= 0.55 -> "stationary"
      averageDelta <= 1.80 -> "walking"
      else -> "running"
    }

  private fun classifyConfidence(
    samples: Int,
    averageDelta: Double,
  ): String {
    if (samples < 6) return "low"
    if (samples >= 14 && averageDelta > 0.4) return "high"
    return "medium"
  }
}

/** Handles Android motion-related node.invoke commands backed by live sensors. */
class MotionHandler private constructor(
  private val appContext: Context,
  private val dataSource: MotionDataSource,
) {
  constructor(appContext: Context) : this(appContext = appContext, dataSource = SystemMotionDataSource)

  /** Classifies a short accelerometer sample into the gateway activity shape. */
  suspend fun handleMotionActivity(paramsJson: String?): GatewaySession.InvokeResult {
    if (!dataSource.hasPermission(appContext)) {
      return GatewaySession.InvokeResult.error(
        code = "MOTION_PERMISSION_REQUIRED",
        message = "MOTION_PERMISSION_REQUIRED: grant Motion permission",
      )
    }
    val request =
      parseActivityRequest(paramsJson)
        ?: return GatewaySession.InvokeResult.error(
          code = "INVALID_REQUEST",
          message = "INVALID_REQUEST: expected JSON object",
        )
    return try {
      val activity = dataSource.activity(appContext, request)
      GatewaySession.InvokeResult.ok(
        buildJsonObject {
          put(
            "activities",
            buildJsonArray {
              add(
                buildJsonObject {
                  put("startISO", JsonPrimitive(activity.startISO))
                  put("endISO", JsonPrimitive(activity.endISO))
                  put("confidence", JsonPrimitive(activity.confidence))
                  put("isWalking", JsonPrimitive(activity.isWalking))
                  put("isRunning", JsonPrimitive(activity.isRunning))
                  put("isCycling", JsonPrimitive(activity.isCycling))
                  put("isAutomotive", JsonPrimitive(activity.isAutomotive))
                  put("isStationary", JsonPrimitive(activity.isStationary))
                  put("isUnknown", JsonPrimitive(activity.isUnknown))
                },
              )
            },
          )
        }.toString(),
      )
    } catch (err: IllegalArgumentException) {
      GatewaySession.InvokeResult.error(code = "MOTION_UNAVAILABLE", message = err.message ?: "MOTION_UNAVAILABLE")
    } catch (err: CancellationException) {
      throw err
    } catch (err: Throwable) {
      GatewaySession.InvokeResult.error(
        code = "MOTION_UNAVAILABLE",
        message = "MOTION_UNAVAILABLE: ${err.message ?: "motion activity failed"}",
      )
    }
  }

  /** Returns the current boot-scoped Android step-counter reading. */
  suspend fun handleMotionPedometer(paramsJson: String?): GatewaySession.InvokeResult {
    if (!dataSource.hasPermission(appContext)) {
      return GatewaySession.InvokeResult.error(
        code = "MOTION_PERMISSION_REQUIRED",
        message = "MOTION_PERMISSION_REQUIRED: grant Motion permission",
      )
    }
    val request =
      parsePedometerRequest(paramsJson)
        ?: return GatewaySession.InvokeResult.error(
          code = "INVALID_REQUEST",
          message = "INVALID_REQUEST: expected JSON object",
        )
    return try {
      val payload = dataSource.pedometer(appContext, request)
      GatewaySession.InvokeResult.ok(
        buildJsonObject {
          put("startISO", JsonPrimitive(payload.startISO))
          put("endISO", JsonPrimitive(payload.endISO))
          payload.steps?.let { put("steps", JsonPrimitive(it)) }
          payload.distanceMeters?.let { put("distanceMeters", JsonPrimitive(it)) }
          payload.floorsAscended?.let { put("floorsAscended", JsonPrimitive(it)) }
          payload.floorsDescended?.let { put("floorsDescended", JsonPrimitive(it)) }
        }.toString(),
      )
    } catch (err: IllegalArgumentException) {
      GatewaySession.InvokeResult.error(code = "MOTION_UNAVAILABLE", message = err.message ?: "MOTION_UNAVAILABLE")
    } catch (err: CancellationException) {
      throw err
    } catch (err: Throwable) {
      GatewaySession.InvokeResult.error(
        code = "MOTION_UNAVAILABLE",
        message = "MOTION_UNAVAILABLE: ${err.message ?: "pedometer query failed"}",
      )
    }
  }

  fun isAvailable(): Boolean = dataSource.isAvailable(appContext)

  /** Returns true when live accelerometer classification can be sampled. */
  fun isActivityAvailable(): Boolean = dataSource.isActivityAvailable(appContext)

  /** Returns true when Android exposes a cumulative step-counter sensor. */
  fun isPedometerAvailable(): Boolean = dataSource.isPedometerAvailable(appContext)

  private fun parseActivityRequest(paramsJson: String?): MotionActivityRequest? {
    if (paramsJson.isNullOrBlank()) {
      return MotionActivityRequest(startISO = null, endISO = null, limit = 200)
    }
    val params = parseJsonParamsObject(paramsJson) ?: return null
    // Keep the accepted gateway parameter even though Android can only return
    // one live classification sample for now.
    val limit = ((params["limit"] as? JsonPrimitive)?.content?.toIntOrNull() ?: 200).coerceIn(1, 1000)
    return MotionActivityRequest(
      startISO = parseJsonString(params, "startISO")?.trim()?.ifEmpty { null },
      endISO = parseJsonString(params, "endISO")?.trim()?.ifEmpty { null },
      limit = limit,
    )
  }

  private fun parsePedometerRequest(paramsJson: String?): MotionPedometerRequest? {
    if (paramsJson.isNullOrBlank()) {
      return MotionPedometerRequest(startISO = null, endISO = null)
    }
    val params = parseJsonParamsObject(paramsJson) ?: return null
    return MotionPedometerRequest(
      startISO = parseJsonString(params, "startISO")?.trim()?.ifEmpty { null },
      endISO = parseJsonString(params, "endISO")?.trim()?.ifEmpty { null },
    )
  }

  companion object {
    /** Static capability probe used before a MotionHandler instance is needed. */
    fun isMotionCapabilityAvailable(context: Context): Boolean = SystemMotionDataSource.isAvailable(context)

    /** Creates a handler with an injected sensor source for parser and payload tests. */
    internal fun forTesting(
      appContext: Context,
      dataSource: MotionDataSource,
    ): MotionHandler = MotionHandler(appContext = appContext, dataSource = dataSource)
  }
}

package ai.openclaw.app.node

import ai.openclaw.app.takeUtf16Safe
import android.os.Build
import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonPrimitive
import kotlinx.serialization.json.buildJsonObject

internal object NodePresenceAliveBeacon {
  /** Gateway event emitted by Android when background execution confirms liveness. */
  const val EVENT_NAME: String = "node.presence.alive"

  /** Avoids spamming presence when multiple background triggers fire together. */
  const val MIN_SUCCESS_INTERVAL_MS: Long = 10 * 60 * 1000
  private const val MAX_RESPONSE_JSON_CHARS: Int = 16 * 1024

  /**
   * Source of the liveness event, serialized as gateway-stable wire values.
   */
  enum class Trigger(
    val rawValue: String,
  ) {
    Background("background"),
    SilentPush("silent_push"),
    BackgroundAppRefresh("bg_app_refresh"),
    SignificantLocation("significant_location"),
    Manual("manual"),
    Connect("connect"),
  }

  /**
   * Minimal gateway response fields used to decide whether a liveness event was accepted.
   */
  data class ResponsePayload(
    val ok: Boolean?,
    val event: String?,
    val handled: Boolean?,
    val reason: String?,
  )

  private val json = Json { ignoreUnknownKeys = true }

  /** Skips sends after a recent successful presence update. */
  fun shouldSkipRecentSuccess(
    nowMs: Long,
    lastSuccessAtMs: Long?,
    minIntervalMs: Long = MIN_SUCCESS_INTERVAL_MS,
  ): Boolean {
    val last = lastSuccessAtMs ?: return false
    if (last <= 0) return false
    val elapsed = nowMs - last
    return elapsed >= 0 && elapsed < minIntervalMs
  }

  /** Human-readable Android version label included in presence payloads. */
  fun androidPlatformMetadata(): String {
    val release =
      Build.VERSION.RELEASE
        ?.trim()
        .orEmpty()
        .ifEmpty { "unknown" }
    return "Android $release (SDK ${Build.VERSION.SDK_INT})"
  }

  /** Builds the compact JSON payload consumed by gateway node-presence handlers. */
  fun makePayloadJson(
    trigger: Trigger,
    sentAtMs: Long,
    displayName: String,
    version: String,
    platform: String,
    deviceFamily: String?,
    modelIdentifier: String?,
    pushTransport: String? = null,
  ): String =
    buildJsonObject {
      put("trigger", JsonPrimitive(trigger.rawValue))
      put("sentAtMs", JsonPrimitive(sentAtMs))
      put("displayName", JsonPrimitive(displayName))
      put("version", JsonPrimitive(version))
      put("platform", JsonPrimitive(platform))
      deviceFamily?.trim()?.takeIf { it.isNotEmpty() }?.let { put("deviceFamily", JsonPrimitive(it)) }
      modelIdentifier?.trim()?.takeIf { it.isNotEmpty() }?.let { put("modelIdentifier", JsonPrimitive(it)) }
      pushTransport?.trim()?.takeIf { it.isNotEmpty() }?.let { put("pushTransport", JsonPrimitive(it)) }
    }.toString()

  /** Parses the gateway response while rejecting empty, oversized, or malformed payloads. */
  fun decodeResponse(payloadJson: String?): ResponsePayload? {
    val raw = payloadJson?.trim()?.takeIf { it.isNotEmpty() } ?: return null
    // Bound log/IPC responses before JSON parsing to avoid memory spikes from
    // malformed gateway replies.
    if (raw.length > MAX_RESPONSE_JSON_CHARS) return null
    val obj =
      try {
        json.parseToJsonElement(raw).asObjectOrNull()
      } catch (_: Throwable) {
        null
      } ?: return null
    return ResponsePayload(
      ok = parseJsonBooleanFlag(obj, "ok"),
      event = parseJsonString(obj, "event"),
      handled = parseJsonBooleanFlag(obj, "handled"),
      reason = parseJsonString(obj, "reason"),
    )
  }

  /** Sanitizes gateway response reasons before writing them into Android logs. */
  fun sanitizeReasonForLog(raw: String?): String {
    val value = raw?.trim()?.takeIf { it.isNotEmpty() } ?: "unsupported"
    return value
      .map { ch -> if (ch.isISOControl()) ' ' else ch }
      .joinToString("")
      .takeUtf16Safe(200)
  }
}

package ai.openclaw.app.node

import ai.openclaw.app.gateway.parseInvokeErrorFromThrowable
import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonElement
import kotlinx.serialization.json.JsonNull
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.JsonPrimitive
import kotlinx.serialization.json.contentOrNull

fun JsonElement?.asObjectOrNull(): JsonObject? = this as? JsonObject

/** Parses invoke params into a JSON object, returning null for absent/malformed input. */
fun parseJsonParamsObject(paramsJson: String?): JsonObject? {
  if (paramsJson.isNullOrBlank()) return null
  return try {
    Json.parseToJsonElement(paramsJson).asObjectOrNull()
  } catch (_: Throwable) {
    null
  }
}

/** Reads a primitive field from invoke params without accepting arrays/objects. */
fun readJsonPrimitive(
  params: JsonObject?,
  key: String,
): JsonPrimitive? = params?.get(key) as? JsonPrimitive

/** Parses an optional integer invoke param. */
fun parseJsonInt(
  params: JsonObject?,
  key: String,
): Int? = readJsonPrimitive(params, key)?.contentOrNull?.toIntOrNull()

/** Parses an optional decimal invoke param. */
fun parseJsonDouble(
  params: JsonObject?,
  key: String,
): Double? = readJsonPrimitive(params, key)?.contentOrNull?.toDoubleOrNull()

/** Parses an optional string invoke param. */
fun parseJsonString(
  params: JsonObject?,
  key: String,
): String? = readJsonPrimitive(params, key)?.contentOrNull

/** Parses true/false flags from JSON primitives, including common string aliases. */
fun parseJsonBooleanFlag(
  params: JsonObject?,
  key: String,
): Boolean? {
  val value = readJsonPrimitive(params, key)?.contentOrNull?.trim()?.lowercase() ?: return null
  return when (value) {
    "true", "yes", "1" -> true
    "false", "no", "0" -> false
    else -> null
  }
}

/** Converts JSON null to Kotlin null while preserving primitive text content. */
fun JsonElement?.asStringOrNull(): String? =
  when (this) {
    is JsonNull -> null
    is JsonPrimitive -> content
    else -> null
  }

/** Parses #RRGGBB or RRGGBB into opaque ARGB. */
fun parseHexColorArgb(raw: String?): Long? {
  val trimmed = raw?.trim().orEmpty()
  if (trimmed.isEmpty()) return null
  val hex = if (trimmed.startsWith("#")) trimmed.drop(1) else trimmed
  if (hex.length != 6) return null
  val rgb = hex.toLongOrNull(16) ?: return null
  return 0xFF000000L or rgb
}

/**
 * Per-profile accent from a users.prefs.get entries payload. Null for missing or
 * malformed values so callers fall back to the gateway accent.
 */
fun resolveProfileAccentArgb(entries: JsonObject?): Long? {
  val value = entries?.get("ui.accent")?.takeIf { it !is JsonNull }
  return parseHexColorArgb((value as? JsonPrimitive)?.takeIf { it.isString }?.contentOrNull)
}

fun resolveGatewayAccentArgb(config: JsonObject?): Long? {
  val ui = config?.get("ui").asObjectOrNull()
  // Control UI precedence (gateway talk.config): a present user accent wins over the
  // operator seam color even when it is not a usable hex string; only an absent or
  // JSON-null accent falls through, matching the gateway's `??` selection.
  val chosen =
    ui
      ?.get("prefs")
      .asObjectOrNull()
      ?.get("accent")
      ?.takeIf { it !is JsonNull }
      ?: ui?.get("seamColor")
  return parseHexColorArgb((chosen as? JsonPrimitive)?.takeIf { it.isString }?.contentOrNull)
}

/** Converts gateway invocation throwables into protocol code/message pairs. */
fun invokeErrorFromThrowable(err: Throwable): Pair<String, String> {
  val parsed = parseInvokeErrorFromThrowable(err, fallbackMessage = "UNAVAILABLE: error")
  val message = if (parsed.hadExplicitCode) parsed.prefixedMessage else parsed.message
  return parsed.code to message
}

/** Normalizes user/session keys while preserving main as the canonical session id. */
fun normalizeMainKey(raw: String?): String? {
  val trimmed = raw?.trim().orEmpty()
  return if (trimmed.isEmpty()) null else trimmed
}

package ai.openclaw.app.node

import ai.openclaw.app.gateway.GatewaySession
import android.content.Context
import kotlinx.serialization.json.JsonArray
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.JsonPrimitive
import kotlinx.serialization.json.buildJsonObject
import kotlinx.serialization.json.contentOrNull
import kotlinx.serialization.json.put

/**
 * Injectable notification listener facade so command parsing can be tested without Android service state.
 */
internal interface NotificationsStateProvider {
  fun readSnapshot(context: Context): DeviceNotificationSnapshot

  fun requestServiceRebind(context: Context)

  fun executeAction(
    context: Context,
    request: NotificationActionRequest,
  ): NotificationActionResult
}

private object SystemNotificationsStateProvider : NotificationsStateProvider {
  /** Reads listener state through Android APIs and returns a disabled snapshot when access is missing. */
  override fun readSnapshot(context: Context): DeviceNotificationSnapshot {
    val enabled = DeviceNotificationListenerService.isAccessEnabled(context)
    if (!enabled) {
      return DeviceNotificationSnapshot(
        enabled = false,
        connected = false,
        notifications = emptyList(),
      )
    }
    return DeviceNotificationListenerService.snapshot(context, enabled = true)
  }

  /** Requests a platform listener rebind after access has been granted. */
  override fun requestServiceRebind(context: Context) {
    DeviceNotificationListenerService.requestServiceRebind(context)
  }

  /** Delegates actions to the active listener service instance. */
  override fun executeAction(
    context: Context,
    request: NotificationActionRequest,
  ): NotificationActionResult = DeviceNotificationListenerService.executeAction(context, request)
}

/** Handles notification listing and actions via the Android listener service. */
class NotificationsHandler private constructor(
  private val appContext: Context,
  private val stateProvider: NotificationsStateProvider,
) {
  constructor(appContext: Context) : this(appContext = appContext, stateProvider = SystemNotificationsStateProvider)

  /** Lists the current listener snapshot after nudging Android to reconnect if needed. */
  suspend fun handleNotificationsList(_paramsJson: String?): GatewaySession.InvokeResult {
    val snapshot = readSnapshotWithRebind()
    return GatewaySession.InvokeResult.ok(snapshotPayloadJson(snapshot))
  }

  /** Executes an action against a notification key from the current listener snapshot. */
  suspend fun handleNotificationsActions(paramsJson: String?): GatewaySession.InvokeResult {
    readSnapshotWithRebind()

    val params =
      parseJsonParamsObject(paramsJson)
        ?: return GatewaySession.InvokeResult.error(
          code = "INVALID_REQUEST",
          message = "INVALID_REQUEST: expected JSON object",
        )
    val key =
      readString(params, "key")
        ?: return GatewaySession.InvokeResult.error(
          code = "INVALID_REQUEST",
          message = "INVALID_REQUEST: key required",
        )
    val actionRaw =
      readString(params, "action")?.lowercase()
        ?: return GatewaySession.InvokeResult.error(
          code = "INVALID_REQUEST",
          message = "INVALID_REQUEST: action required (open|dismiss|reply)",
        )
    // Keep accepted action names aligned with the cross-platform notification
    // command contract rather than Android-specific PendingIntent labels.
    val action =
      when (actionRaw) {
        "open" -> NotificationActionKind.Open
        "dismiss" -> NotificationActionKind.Dismiss
        "reply" -> NotificationActionKind.Reply
        else ->
          return GatewaySession.InvokeResult.error(
            code = "INVALID_REQUEST",
            message = "INVALID_REQUEST: action must be open|dismiss|reply",
          )
      }
    val replyText = readString(params, "replyText")
    if (action == NotificationActionKind.Reply && replyText.isNullOrBlank()) {
      return GatewaySession.InvokeResult.error(
        code = "INVALID_REQUEST",
        message = "INVALID_REQUEST: replyText required for reply action",
      )
    }

    val result =
      stateProvider.executeAction(
        appContext,
        NotificationActionRequest(
          key = key,
          kind = action,
          replyText = replyText,
        ),
      )
    if (!result.ok) {
      return GatewaySession.InvokeResult.error(
        code = result.code ?: "UNAVAILABLE",
        message = result.message ?: "notification action failed",
      )
    }

    val payload =
      buildJsonObject {
        put("ok", JsonPrimitive(true))
        put("key", JsonPrimitive(key))
        put("action", JsonPrimitive(actionRaw))
      }.toString()
    return GatewaySession.InvokeResult.ok(payload)
  }

  private fun readSnapshotWithRebind(): DeviceNotificationSnapshot {
    val snapshot = stateProvider.readSnapshot(appContext)
    if (snapshot.enabled && !snapshot.connected) {
      // Access can be granted while Android has not rebound the listener yet.
      stateProvider.requestServiceRebind(appContext)
    }
    return snapshot
  }

  private fun snapshotPayloadJson(snapshot: DeviceNotificationSnapshot): String =
    buildJsonObject {
      put("enabled", JsonPrimitive(snapshot.enabled))
      put("connected", JsonPrimitive(snapshot.connected))
      put("count", JsonPrimitive(snapshot.notifications.size))
      put(
        "notifications",
        JsonArray(
          snapshot.notifications.map { entry -> entry.toJsonObject() },
        ),
      )
    }.toString()

  private fun readString(
    params: JsonObject,
    key: String,
  ): String? =
    (params[key] as? JsonPrimitive)
      ?.contentOrNull
      ?.trim()
      ?.takeIf { it.isNotEmpty() }

  companion object {
    internal fun forTesting(
      appContext: Context,
      stateProvider: NotificationsStateProvider,
    ): NotificationsHandler = NotificationsHandler(appContext = appContext, stateProvider = stateProvider)
  }
}

package ai.openclaw.app.node

import ai.openclaw.app.gateway.GatewaySession
import ai.openclaw.app.hasPhotoReadPermission
import android.content.ContentResolver
import android.content.ContentUris
import android.content.Context
import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.net.Uri
import android.os.Bundle
import android.provider.MediaStore
import androidx.core.graphics.scale
import androidx.exifinterface.media.ExifInterface
import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonPrimitive
import kotlinx.serialization.json.buildJsonArray
import kotlinx.serialization.json.buildJsonObject
import kotlinx.serialization.json.put
import java.io.ByteArrayOutputStream
import java.time.Instant
import kotlin.math.max
import kotlin.math.roundToInt

private const val DEFAULT_PHOTOS_LIMIT = 1
private const val DEFAULT_PHOTOS_MAX_WIDTH = 1600
private const val DEFAULT_PHOTOS_QUALITY = 0.85
private const val MAX_TOTAL_BASE64_CHARS = 340 * 1024
private const val MAX_PER_PHOTO_BASE64_CHARS = 300 * 1024

/** Request shape for photos.latest after defaults and bounds are applied. */
internal data class PhotosLatestRequest(
  val limit: Int,
  val maxWidth: Int,
  val quality: Double,
)

/** Encoded photo payload returned to the gateway. */
internal data class EncodedPhotoPayload(
  val format: String,
  val base64: String,
  val width: Int,
  val height: Int,
  val createdAt: String?,
)

/** Photo access seam for Android MediaStore and tests. */
internal interface PhotosDataSource {
  fun hasPermission(context: Context): Boolean

  fun latest(
    context: Context,
    request: PhotosLatestRequest,
  ): List<EncodedPhotoPayload>
}

private object SystemPhotosDataSource : PhotosDataSource {
  override fun hasPermission(context: Context): Boolean = hasPhotoReadPermission(context)

  override fun latest(
    context: Context,
    request: PhotosLatestRequest,
  ): List<EncodedPhotoPayload> {
    val resolver = context.contentResolver
    val rows = queryLatestRows(resolver, request.limit)
    if (rows.isEmpty()) return emptyList()

    var remainingBudget = MAX_TOTAL_BASE64_CHARS
    val out = mutableListOf<EncodedPhotoPayload>()
    for (row in rows) {
      if (remainingBudget <= 0) break
      val bitmap = decodeScaledBitmap(resolver, row.uri, request.maxWidth) ?: continue
      try {
        // Enforce both per-photo and total payload budgets before returning
        // base64 data through the gateway invoke response.
        val encoded = encodeJpegUnderBudget(bitmap, request.quality, MAX_PER_PHOTO_BASE64_CHARS)
        if (encoded == null) continue
        if (encoded.base64.length > remainingBudget) break
        remainingBudget -= encoded.base64.length
        out +=
          EncodedPhotoPayload(
            format = "jpeg",
            base64 = encoded.base64,
            width = encoded.width,
            height = encoded.height,
            createdAt = row.createdAtMs?.let { Instant.ofEpochMilli(it).toString() },
          )
      } finally {
        bitmap.recycle()
      }
    }
    return out
  }

  private data class PhotoRow(
    val uri: Uri,
    val createdAtMs: Long?,
  )

  private data class EncodedJpeg(
    val base64: String,
    val width: Int,
    val height: Int,
  )

  private fun queryLatestRows(
    resolver: ContentResolver,
    limit: Int,
  ): List<PhotoRow> {
    val projection =
      arrayOf(
        MediaStore.Images.Media._ID,
        MediaStore.Images.Media.DATE_TAKEN,
        MediaStore.Images.Media.DATE_ADDED,
      )
    val sortOrder =
      "COALESCE(NULLIF(${MediaStore.Images.Media.DATE_TAKEN}, 0), " +
        "${MediaStore.Images.Media.DATE_ADDED} * 1000) DESC, ${MediaStore.Images.Media._ID} DESC"
    val args =
      Bundle().apply {
        putString(ContentResolver.QUERY_ARG_SQL_SORT_ORDER, sortOrder)
        putInt(ContentResolver.QUERY_ARG_LIMIT, limit)
      }

    resolver
      .query(
        MediaStore.Images.Media.EXTERNAL_CONTENT_URI,
        projection,
        args,
        null,
      ).use { cursor ->
        if (cursor == null) return emptyList()
        val idIndex = cursor.getColumnIndexOrThrow(MediaStore.Images.Media._ID)
        val takenIndex = cursor.getColumnIndexOrThrow(MediaStore.Images.Media.DATE_TAKEN)
        val addedIndex = cursor.getColumnIndexOrThrow(MediaStore.Images.Media.DATE_ADDED)
        val rows = mutableListOf<PhotoRow>()
        while (cursor.moveToNext()) {
          val id = cursor.getLong(idIndex)
          val takenMs = cursor.getLong(takenIndex).takeIf { it > 0L }
          val addedMs = cursor.getLong(addedIndex).takeIf { it > 0L }?.times(1000L)
          rows +=
            PhotoRow(
              uri = ContentUris.withAppendedId(MediaStore.Images.Media.EXTERNAL_CONTENT_URI, id),
              createdAtMs = takenMs ?: addedMs,
            )
        }
        return rows
      }
  }

  private fun decodeScaledBitmap(
    resolver: ContentResolver,
    uri: Uri,
    maxWidth: Int,
  ): Bitmap? {
    val bounds = BitmapFactory.Options().apply { inJustDecodeBounds = true }
    resolver.openInputStream(uri).use { input ->
      if (input == null) return null
      BitmapFactory.decodeStream(input, null, bounds)
    }
    if (bounds.outWidth <= 0 || bounds.outHeight <= 0) return null

    val orientation = JpegSizeLimiter.readOrientation { resolver.openInputStream(uri) }
    val sourceWidth =
      if (orientation in ExifInterface.ORIENTATION_TRANSPOSE..ExifInterface.ORIENTATION_ROTATE_270) {
        bounds.outHeight
      } else {
        bounds.outWidth
      }
    val inSampleSize = computeInSampleSize(sourceWidth, maxWidth)
    val decodeOptions = BitmapFactory.Options().apply { this.inSampleSize = inSampleSize }
    val decoded =
      resolver.openInputStream(uri).use { input ->
        if (input == null) return null
        BitmapFactory.decodeStream(input, null, decodeOptions)
      } ?: return null

    val oriented = JpegSizeLimiter.normalizeOrientation(decoded, orientation)
    if (oriented.width <= maxWidth) return oriented
    // Decode sampling is power-of-two only; finish with exact scaling when the
    // sampled bitmap is still wider than the requested max width.
    val targetHeight = max(1, ((oriented.height.toDouble() * maxWidth) / oriented.width).roundToInt())
    return try {
      oriented.scale(maxWidth, targetHeight, true)
    } finally {
      oriented.recycle()
    }
  }

  private fun computeInSampleSize(
    width: Int,
    maxWidth: Int,
  ): Int {
    var sample = 1
    while (width / sample / 2 >= maxWidth) {
      sample *= 2
    }
    return sample
  }

  private fun encodeJpegUnderBudget(
    bitmap: Bitmap,
    quality: Double,
    maxBase64Chars: Int,
  ): EncodedJpeg? {
    var working = bitmap
    try {
      var jpegQuality = (quality.coerceIn(0.1, 1.0) * 100.0).roundToInt().coerceIn(10, 100)
      repeat(10) {
        val out = ByteArrayOutputStream()
        val ok = working.compress(Bitmap.CompressFormat.JPEG, jpegQuality, out)
        if (!ok) return null
        val bytes = out.toByteArray()
        val base64 = android.util.Base64.encodeToString(bytes, android.util.Base64.NO_WRAP)
        if (base64.length <= maxBase64Chars) {
          return EncodedJpeg(
            base64 = base64,
            width = working.width,
            height = working.height,
          )
        }
        if (jpegQuality > 35) {
          // Try quality reduction before resizing so small images keep detail.
          jpegQuality = max(25, jpegQuality - 15)
          return@repeat
        }
        val nextWidth = max(240, (working.width * 0.75f).roundToInt())
        if (nextWidth >= working.width) return null
        val nextHeight = max(1, ((working.height.toDouble() * nextWidth) / working.width).roundToInt())
        val previous = working
        working = working.scale(nextWidth, nextHeight, true)
        if (previous !== bitmap) previous.recycle()
      }
      return null
    } finally {
      if (working !== bitmap) working.recycle()
    }
  }
}

/** Handles photos.latest by querying MediaStore and returning bounded JPEG payloads. */
class PhotosHandler private constructor(
  private val appContext: Context,
  private val dataSource: PhotosDataSource,
) {
  constructor(appContext: Context) : this(appContext = appContext, dataSource = SystemPhotosDataSource)

  /** Returns the newest accessible photos as gateway-sized base64 JPEGs. */
  fun handlePhotosLatest(paramsJson: String?): GatewaySession.InvokeResult {
    if (!dataSource.hasPermission(appContext)) {
      return GatewaySession.InvokeResult.error(
        code = "PHOTOS_PERMISSION_REQUIRED",
        message = "PHOTOS_PERMISSION_REQUIRED: grant Photos permission",
      )
    }
    val request =
      parseRequest(paramsJson)
        ?: return GatewaySession.InvokeResult.error(
          code = "INVALID_REQUEST",
          message = "INVALID_REQUEST: expected JSON object",
        )
    return try {
      val photos = dataSource.latest(appContext, request)
      val payload =
        buildJsonObject {
          put(
            "photos",
            buildJsonArray {
              photos.forEach { photo ->
                add(
                  buildJsonObject {
                    put("format", JsonPrimitive(photo.format))
                    put("base64", JsonPrimitive(photo.base64))
                    put("width", JsonPrimitive(photo.width))
                    put("height", JsonPrimitive(photo.height))
                    photo.createdAt?.let { put("createdAt", JsonPrimitive(it)) }
                  },
                )
              }
            },
          )
        }.toString()
      GatewaySession.InvokeResult.ok(payload)
    } catch (err: Throwable) {
      GatewaySession.InvokeResult.error(
        code = "PHOTOS_UNAVAILABLE",
        message = "PHOTOS_UNAVAILABLE: ${err.message ?: "photo fetch failed"}",
      )
    }
  }

  private fun parseRequest(paramsJson: String?): PhotosLatestRequest? {
    if (paramsJson.isNullOrBlank()) {
      return PhotosLatestRequest(
        limit = DEFAULT_PHOTOS_LIMIT,
        maxWidth = DEFAULT_PHOTOS_MAX_WIDTH,
        quality = DEFAULT_PHOTOS_QUALITY,
      )
    }
    val params =
      try {
        Json.parseToJsonElement(paramsJson).asObjectOrNull()
      } catch (_: Throwable) {
        null
      } ?: return null

    val limitRaw = (params["limit"] as? JsonPrimitive)?.content?.toIntOrNull()
    val maxWidthRaw = (params["maxWidth"] as? JsonPrimitive)?.content?.toIntOrNull()
    val qualityRaw = (params["quality"] as? JsonPrimitive)?.content?.toDoubleOrNull()

    // Clamp model-supplied values to protect memory and response-size limits.
    val limit = (limitRaw ?: DEFAULT_PHOTOS_LIMIT).coerceIn(1, 20)
    val maxWidth = (maxWidthRaw ?: DEFAULT_PHOTOS_MAX_WIDTH).coerceIn(240, 4096)
    val quality = (qualityRaw ?: DEFAULT_PHOTOS_QUALITY).coerceIn(0.1, 1.0)
    return PhotosLatestRequest(limit = limit, maxWidth = maxWidth, quality = quality)
  }

  companion object {
    /** Creates a handler with an injected photo source for parser and payload tests. */
    internal fun forTesting(
      appContext: Context,
      dataSource: PhotosDataSource,
    ): PhotosHandler = PhotosHandler(appContext = appContext, dataSource = dataSource)
  }
}

