@Composable
internal fun ChatQuestionCard(
  prompt: ChatQuestionPrompt,
  onDraftChanged: (ChatQuestionPrompt, (ChatQuestionDraft) -> ChatQuestionDraft) -> Unit,
  onSubmit: (ChatQuestionPrompt, Map<String, List<String>>) -> Unit,
  onSkip: (ChatQuestionPrompt) -> Unit,
  modifier: Modifier = Modifier,
) {
  val draft = prompt.draft
  var nowMs by remember(prompt.record.id) { mutableLongStateOf(System.currentTimeMillis()) }
  val status = prompt.status(nowMs)
  val pending = status == ChatQuestionStatus.Pending
  if (!pending && status != ChatQuestionStatus.Submitting) {
    ChatQuestionSummary(prompt = prompt, status = status, modifier = modifier)
    return
  }
  LaunchedEffect(prompt.record.id, prompt.record.expiresAtMs, status) {
    while (status == ChatQuestionStatus.Pending || status == ChatQuestionStatus.Submitting) {
      delay(1000)
      nowMs = System.currentTimeMillis()
    }
  }

  Surface(
    modifier = modifier.fillMaxWidth(),
    shape = RoundedCornerShape(ClawTheme.radii.sheet),
    color = ClawTheme.colors.surfaceRaised,
    border = BorderStroke(1.dp, ClawTheme.colors.border),
  ) {
    Column(
      modifier = Modifier.padding(16.dp),
      verticalArrangement = Arrangement.spacedBy(14.dp),
    ) {
      prompt.record.questions.forEach { question ->
        if (question.secretStore != null) {
          SecretStoreConsent(
            prompt = prompt,
            question = question,
            enabled = pending,
            onDraftChanged = { update -> onDraftChanged(prompt, update) },
          )
        }
        QuestionSection(
          question = question,
          draft = draft,
          enabled = pending,
          onDraftChanged = { update -> onDraftChanged(prompt, update) },
        )
      }
      QuestionFooter(
        prompt = prompt,
        draft = draft,
        status = status,
        nowMs = nowMs,
        onSubmit = onSubmit,
        onSkip = onSkip,
      )
    }
  }
}

@Composable
private fun SecretStoreConsent(
  prompt: ChatQuestionPrompt,
  question: Question,
  enabled: Boolean,
  onDraftChanged: ((ChatQuestionDraft) -> ChatQuestionDraft) -> Unit,
) {
  val store = question.secretStore ?: return
  Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
    Text(
      text = nativeString("Requested by \$agent • \$session", prompt.record.agentId ?: nativeString("Unknown"), prompt.record.sessionKey ?: nativeString("Unknown")),
      style = ClawTheme.type.caption,
      color = ClawTheme.colors.textMuted,
    )
    Text(
      text = nativeString("Stores \$name as \$kind", store.name, if (store.kind == "secret") nativeString("Protected secret") else nativeString("Agent-readable environment")),
      style = ClawTheme.type.body,
      color = ClawTheme.colors.text,
    )
    store.reason?.takeIf { it.isNotEmpty() }?.let {
      Text(text = it, style = ClawTheme.type.body, color = ClawTheme.colors.text)
    }
    question.secretStoreExisting?.let { existing ->
      val updated = DateFormat.getDateTimeInstance(DateFormat.MEDIUM, DateFormat.SHORT).format(Date(existing.updatedAtMs))
      Text(
        text = nativeString("Replaces \$name — last updated \$updated", store.name, updated),
        style = ClawTheme.type.caption,
        fontWeight = FontWeight.SemiBold,
        color = ClawTheme.colors.danger,
      )
      existing.updatedBy?.let {
        Text(text = nativeString("Updated by \$name", it), style = ClawTheme.type.caption, color = ClawTheme.colors.textMuted)
      }
    }
    if (store.kind == "secret") {
      OutlinedTextField(
        value = prompt.draft.secretStoreAllowedHostsText ?: store.allowedHosts.orEmpty().joinToString(", "),
        onValueChange = { value -> onDraftChanged { it.copy(secretStoreAllowedHostsText = value) } },
        modifier = Modifier.fillMaxWidth(),
        enabled = enabled,
        label = { Text(nativeString("Allowed HTTPS hosts"), style = ClawTheme.type.body) },
        placeholder = { Text(nativeString("api.example.com, uploads.example.com"), style = ClawTheme.type.body) },
        textStyle = ClawTheme.type.body,
        keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Uri),
        maxLines = 4,
      )
      Text(
        text = nativeString("Exact hostnames only, separated by commas or spaces. Leave empty for config SecretRefs without proxy use."),
        style = ClawTheme.type.caption,
        color = ClawTheme.colors.textMuted,
      )
    }
  }
}

@Composable
private fun ChatQuestionSummary(
  prompt: ChatQuestionPrompt,
  status: ChatQuestionStatus,
  modifier: Modifier = Modifier,
) {
  Surface(
    modifier = modifier.fillMaxWidth(),
    shape = RoundedCornerShape(ClawTheme.radii.row),
    color = ClawTheme.colors.surfaceRaised,
    border = BorderStroke(1.dp, ClawTheme.colors.border),
  ) {
    Column(
      modifier = Modifier.padding(horizontal = 12.dp, vertical = 10.dp),
      verticalArrangement = Arrangement.spacedBy(4.dp),
    ) {
      prompt.record.questions.forEach { question ->
        Column {
          Text(
            text = question.header + ':',
            style = ClawTheme.type.caption,
            color = ClawTheme.colors.text,
            fontWeight = FontWeight.SemiBold,
          )
          Text(
            text = terminalQuestionAnswer(prompt, question, status),
            style = ClawTheme.type.caption,
            color = ClawTheme.colors.textMuted,
          )
        }
      }
    }
  }
}

@Composable
private fun QuestionSection(
  question: Question,
  draft: ChatQuestionDraft,
  enabled: Boolean,
  onDraftChanged: ((ChatQuestionDraft) -> ChatQuestionDraft) -> Unit,
) {
  Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
    Text(
      text = question.header.uppercase(),
      style = ClawTheme.type.caption,
      color = ClawTheme.colors.primary,
      fontWeight = FontWeight.SemiBold,
    )
    Text(text = question.question, style = ClawTheme.type.body, color = ClawTheme.colors.text)
    question.options.forEach { option ->
      val selected = option.label in draft.selectedOptions[question.questionId].orEmpty()
      Surface(
        onClick = { onDraftChanged { it.toggle(question, option.label) } },
        enabled = enabled,
        shape = RoundedCornerShape(ClawTheme.radii.row),
        color = if (selected) ClawTheme.colors.surfacePressed else ClawTheme.colors.surface,
      ) {
        Row(
          modifier = Modifier.fillMaxWidth().padding(horizontal = 8.dp, vertical = 6.dp),
          verticalAlignment = Alignment.Top,
        ) {
          if (question.multiSelect == true) {
            Checkbox(checked = selected, onCheckedChange = null, enabled = enabled)
          } else {
            RadioButton(selected = selected, onClick = null, enabled = enabled)
          }
          Spacer(Modifier.width(6.dp))
          Column(modifier = Modifier.weight(1f)) {
            Text(text = option.label, style = ClawTheme.type.body, color = ClawTheme.colors.text)
            option.description?.takeIf { it.isNotBlank() }?.let { description ->
              Text(text = description, style = ClawTheme.type.caption, color = ClawTheme.colors.textMuted)
            }
          }
        }
      }
    }
    if (question.options.isEmpty() || question.isOther == true) {
      // Secret answers must never render on screen or feed the keyboard's
      // prediction/autocorrect stores; password transformation + keyboard type
      // cover both, and single-line keeps the masked value one obscured run.
      val secret = question.isSecret == true
      OutlinedTextField(
        value = draft.otherText[question.questionId].orEmpty(),
        onValueChange = { value -> onDraftChanged { it.setOther(question, value) } },
        modifier = Modifier.fillMaxWidth(),
        enabled = enabled,
        label = { Text(if (secret) nativeString("Secret value") else nativeString("Other answer")) },
        visualTransformation = if (secret) PasswordVisualTransformation() else VisualTransformation.None,
        keyboardOptions =
          if (secret) KeyboardOptions(keyboardType = KeyboardType.Password) else KeyboardOptions.Default,
        minLines = 1,
        maxLines = if (secret) 1 else 4,
      )
    }
  }
}

@Composable
private fun QuestionFooter(
  prompt: ChatQuestionPrompt,
  draft: ChatQuestionDraft,
  status: ChatQuestionStatus,
  nowMs: Long,
  onSubmit: (ChatQuestionPrompt, Map<String, List<String>>) -> Unit,
  onSkip: (ChatQuestionPrompt) -> Unit,
) {
  val answers = draft.answers(prompt.record.questions)
  if (status == ChatQuestionStatus.Pending || status == ChatQuestionStatus.Submitting) {
    Row(verticalAlignment = Alignment.CenterVertically) {
      Text(
        text = questionCountdown(prompt.record.expiresAtMs, nowMs),
        style = ClawTheme.type.caption,
        color = ClawTheme.colors.textMuted,
      )
      Spacer(Modifier.weight(1f))
      TextButton(
        onClick = { onSkip(prompt) },
        enabled = status == ChatQuestionStatus.Pending,
      ) {
        Text(nativeString("Skip"))
      }
      Button(
        onClick = { answers?.let { onSubmit(prompt, it) } },
        enabled = answers != null && status == ChatQuestionStatus.Pending,
      ) {
        Text(
          if (status == ChatQuestionStatus.Submitting && !prompt.skipping) {
            nativeString("Submitting…")
          } else {
            nativeString("Submit")
          },
        )
      }
    }
    prompt.errorText?.let { error ->
      Text(text = error, style = ClawTheme.type.caption, color = ClawTheme.colors.danger)
    }
  }
}

internal fun terminalQuestionAnswer(
  prompt: ChatQuestionPrompt,
  question: Question,
  status: ChatQuestionStatus,
): String {
  if (status == ChatQuestionStatus.Cancelled) return nativeString("Skipped")
  if (status == ChatQuestionStatus.Expired) return nativeString("Expired")
  if (status == ChatQuestionStatus.Unavailable) return nativeString("Unavailable")
  // Secret terminal summaries never echo submitted answer text.
  if (question.isSecret != true) {
    prompt.record.answers?.answers?.get(question.questionId)?.takeIf { it.isNotEmpty() }?.let {
      return it.joinToString(", ")
    }
  }
  return if (status == ChatQuestionStatus.AnsweredElsewhere) nativeString("Answered elsewhere") else nativeString("Answered")
}

// nativeString is the non-composable resource accessor (nativeStringResource
// is the @Composable variant), so this helper is safe outside composition.
internal fun questionCountdown(
  expiresAtMs: Long,
  nowMs: Long,
): String {
  val seconds = ((expiresAtMs - nowMs).coerceAtLeast(0) + 999) / 1000
  return (seconds / 60).toString() + ':' + (seconds % 60).toString().padStart(2, '0')
}

package ai.openclaw.app.ui.chat

import androidx.compose.foundation.gestures.stopScroll
import androidx.compose.foundation.lazy.LazyListState
import androidx.compose.foundation.lazy.rememberLazyListState
import androidx.compose.runtime.Composable
import androidx.compose.runtime.LaunchedEffect
import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableIntStateOf
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.remember
import androidx.compose.runtime.rememberCoroutineScope
import androidx.compose.runtime.rememberUpdatedState
import androidx.compose.runtime.saveable.listSaver
import androidx.compose.runtime.saveable.rememberSaveable
import androidx.compose.runtime.setValue
import androidx.compose.runtime.snapshotFlow
import androidx.compose.runtime.staticCompositionLocalOf
import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.input.nestedscroll.NestedScrollConnection
import androidx.compose.ui.input.nestedscroll.NestedScrollSource
import androidx.compose.ui.platform.LocalDensity
import androidx.compose.ui.unit.dp
import kotlinx.coroutines.CoroutineStart
import kotlinx.coroutines.launch

internal enum class ChatScrollFollowTarget {
  ReadAnchor,
  LatestContent,
}

internal data class ChatReaderState(
  val ownerSessionKey: String? = null,
  val initialized: Boolean = false,
  val followTarget: ChatScrollFollowTarget? = null,
  val hasNewerContent: Boolean = false,
  val latestUserMessageId: String? = null,
  val latestUserMessageVersion: String? = null,
  val latestContentVersion: String? = null,
)

internal fun createChatReaderStateSaver(expectedSessionKey: String? = null) =
  listSaver<ChatReaderState, Any>(
    save = { state ->
      listOf(
        state.ownerSessionKey != null,
        state.ownerSessionKey.orEmpty(),
        state.initialized,
        state.followTarget?.name.orEmpty(),
        state.hasNewerContent,
        state.latestUserMessageId != null,
        state.latestUserMessageId.orEmpty(),
        state.latestUserMessageVersion != null,
        state.latestUserMessageVersion.orEmpty(),
        state.latestContentVersion != null,
        state.latestContentVersion.orEmpty(),
      )
    },
    restore = { saved ->
      val restored =
        ChatReaderState(
          ownerSessionKey = (saved[1] as String).takeIf { saved[0] as Boolean },
          initialized = saved[2] as Boolean,
          followTarget =
            (saved[3] as String).takeIf(String::isNotEmpty)?.let(ChatScrollFollowTarget::valueOf),
          hasNewerContent = saved[4] as Boolean,
          latestUserMessageId = (saved[6] as String).takeIf { saved[5] as Boolean },
          latestUserMessageVersion = (saved[8] as String).takeIf { saved[7] as Boolean },
          latestContentVersion = (saved[10] as String).takeIf { saved[9] as Boolean },
        )
      restored.takeIf { expectedSessionKey == null || it.ownerSessionKey == expectedSessionKey }
    },
  )

internal val ChatReaderStateSaver = createChatReaderStateSaver()

internal data class ChatReaderTransition(
  val state: ChatReaderState,
  val scrollIndex: Int? = null,
  val animated: Boolean = false,
)

internal data class ChatReaderScrollController(
  val listState: LazyListState,
  val showJumpToLatest: Boolean,
  val jumpToLatest: () -> Unit,
  val onManualNavigation: () -> Unit,
  val nestedScrollConnection: NestedScrollConnection,
)

internal val LocalChatReaderNavigation = staticCompositionLocalOf<() -> Unit> { {} }

@Composable
internal fun rememberChatReaderScrollController(
  sessionKey: String,
  timeline: ChatTimeline,
  historyLoading: Boolean,
): ChatReaderScrollController {
  val listState = rememberLazyListState()
  val scope = rememberCoroutineScope()
  val targetTolerancePx = with(LocalDensity.current) { 24.dp.roundToPx() }
  val currentTimeline by rememberUpdatedState(timeline)
  val readerStateSaver = remember(sessionKey) { createChatReaderStateSaver(sessionKey) }
  var readerState by
    rememberSaveable(sessionKey, stateSaver = readerStateSaver) {
      mutableStateOf(ChatReaderState(ownerSessionKey = sessionKey))
    }
  var applyingScrollCount by remember(sessionKey) { mutableIntStateOf(0) }
  var isUserScrolling by remember(sessionKey) { mutableStateOf(false) }

  fun pauseFollowing() {
    readerState = readerState.copy(followTarget = null)
    // Stop an older automatic animation at its default priority, never interrupt
    // a newer user drag that has already taken ownership of the scroll state.
    if (applyingScrollCount > 0) scope.launch(start = CoroutineStart.UNDISPATCHED) { listState.stopScroll() }
  }

  val nestedScroll =
    remember(sessionKey) {
      object : NestedScrollConnection {
        override fun onPreScroll(
          available: Offset,
          source: NestedScrollSource,
        ): Offset {
          // A code viewport can consume the whole drag without scrolling the transcript.
          // Its reader intent must still retire follow, without consuming the gesture.
          if (source == NestedScrollSource.UserInput && available.y != 0f) pauseFollowing()
          return Offset.Zero
        }
      }
    }

  suspend fun applyTransition(transition: ChatReaderTransition) {
    readerState = transition.state
    val index = transition.scrollIndex ?: return
    // A replacement cancels its predecessor before the predecessor's finally runs.
    // Count active invocations so that cleanup cannot hide the newer animation.
    applyingScrollCount += 1
    try {
      if (transition.animated) {
        listState.animateScrollToItem(index)
      } else {
        listState.scrollToItem(index)
      }
    } finally {
      applyingScrollCount -= 1
    }
  }

  LaunchedEffect(sessionKey, timeline, historyLoading) {
    val transition =
      if (readerState.initialized) {
        readerState.onTimelineChanged(timeline, historyLoading)
      } else {
        initialChatReaderTransition(timeline, ownerSessionKey = sessionKey)
      }
    applyTransition(transition)
  }

  LaunchedEffect(sessionKey) {
    snapshotFlow {
      Triple(
        listState.isScrollInProgress,
        listState.firstVisibleItemIndex,
        listState.firstVisibleItemScrollOffset,
      )
    }.collect { (scrolling, index, offset) ->
      if (!readerState.initialized || applyingScrollCount > 0) return@collect
      if (scrolling) {
        isUserScrolling = true
        readerState = readerState.copy(followTarget = null)
      } else if (isUserScrolling) {
        isUserScrolling = false
        readerState = readerState.onViewportChanged(index, offset, currentTimeline, targetTolerancePx)
      }
    }
  }

  return ChatReaderScrollController(
    listState = listState,
    showJumpToLatest = readerState.hasNewerContent && timeline.items.isNotEmpty(),
    jumpToLatest = {
      scope.launch {
        applyTransition(readerState.jumpToLatest(currentTimeline))
      }
    },
    onManualNavigation = ::pauseFollowing,
    nestedScrollConnection = nestedScroll,
  )
}

internal fun initialChatReaderTransition(
  timeline: ChatTimeline,
  ownerSessionKey: String? = null,
): ChatReaderTransition {
  val initialIndex = timeline.readAnchorIndex ?: timeline.latestContentIndex
  val followTarget = timeline.followTargetForIndex(initialIndex)
  return ChatReaderTransition(
    state =
      ChatReaderState(
        ownerSessionKey = ownerSessionKey,
        initialized = initialIndex != null,
        followTarget = followTarget,
        hasNewerContent =
          followTarget == ChatScrollFollowTarget.ReadAnchor && initialIndex != timeline.latestContentIndex,
        latestUserMessageId = timeline.latestUserMessageId,
        latestUserMessageVersion = timeline.latestUserMessageVersion,
        latestContentVersion = timeline.latestContentVersion,
      ),
    scrollIndex = initialIndex,
  )
}

internal fun ChatReaderState.onTimelineChanged(
  timeline: ChatTimeline,
  historyLoading: Boolean = false,
): ChatReaderTransition {
  if (timeline.items.isEmpty()) {
    return ChatReaderTransition(
      state = if (historyLoading) this else ChatReaderState(ownerSessionKey = ownerSessionKey),
    )
  }
  if (timeline.latestContentVersion == latestContentVersion) {
    return ChatReaderTransition(state = this)
  }
  val previousUserStillPresent =
    if (latestUserMessageVersion == null) {
      latestUserMessageId == null
    } else {
      latestUserMessageId?.let(timeline::containsMessage) == true ||
        timeline.containsUserMessageVersion(latestUserMessageVersion)
    }
  if (!previousUserStillPresent) {
    return ChatReaderTransition(
      state =
        copy(
          followTarget = null,
          hasNewerContent = false,
          latestUserMessageId = timeline.latestUserMessageId,
          latestUserMessageVersion = timeline.latestUserMessageVersion,
          latestContentVersion = timeline.latestContentVersion,
        ),
    )
  }
  val hasNewUserTurn =
    timeline.latestUserMessageVersion != null && timeline.latestUserMessageVersion != latestUserMessageVersion
  if (hasNewUserTurn) {
    // A live turn follows the bottom so the reply streams into view (parity with the
    // iOS reader, #108692/#108693). ReadAnchor remains the session-restore bookmark only;
    // re-pinning the prompt here would hide the reply below the fold behind a jump pill.
    return ChatReaderTransition(
      state =
        copy(
          followTarget = ChatScrollFollowTarget.LatestContent,
          hasNewerContent = false,
          latestUserMessageId = timeline.latestUserMessageId,
          latestUserMessageVersion = timeline.latestUserMessageVersion,
          latestContentVersion = timeline.latestContentVersion,
        ),
      scrollIndex = timeline.latestContentIndex ?: timeline.readAnchorIndex,
      animated = true,
    )
  }

  val target = followTarget
  if (target == null) {
    return ChatReaderTransition(
      state =
        copy(
          hasNewerContent = true,
          latestUserMessageId = timeline.latestUserMessageId,
          latestUserMessageVersion = timeline.latestUserMessageVersion,
          latestContentVersion = timeline.latestContentVersion,
        ),
    )
  }

  val targetIndex = timeline.indexForFollowTarget(target)
  return ChatReaderTransition(
    state =
      copy(
        hasNewerContent = target == ChatScrollFollowTarget.ReadAnchor && targetIndex != timeline.latestContentIndex,
        latestUserMessageId = timeline.latestUserMessageId,
        latestUserMessageVersion = timeline.latestUserMessageVersion,
        latestContentVersion = timeline.latestContentVersion,
      ),
    scrollIndex = targetIndex,
  )
}

internal fun ChatReaderState.onViewportChanged(
  index: Int,
  offset: Int,
  timeline: ChatTimeline,
  targetTolerancePx: Int,
): ChatReaderState {
  val nextTarget =
    if (isAtTarget(index, offset, timeline.latestContentIndex, targetTolerancePx)) {
      ChatScrollFollowTarget.LatestContent
    } else {
      null
    }
  return copy(
    followTarget = nextTarget,
    hasNewerContent = nextTarget == null && timeline.latestContentIndex != null,
  )
}

internal fun ChatReaderState.jumpToLatest(timeline: ChatTimeline): ChatReaderTransition =
  ChatReaderTransition(
    state = copy(followTarget = ChatScrollFollowTarget.LatestContent, hasNewerContent = false),
    scrollIndex = timeline.latestContentIndex ?: timeline.readAnchorIndex,
    animated = true,
  )

private fun ChatTimeline.indexForFollowTarget(target: ChatScrollFollowTarget): Int? =
  when (target) {
    ChatScrollFollowTarget.ReadAnchor -> readAnchorIndex
    ChatScrollFollowTarget.LatestContent -> latestContentIndex
  }

private fun ChatTimeline.containsMessage(id: String): Boolean =
  items
    .filterIsInstance<ChatTimelineItem.Message>()
    .any { item -> item.message.id == id }

private fun ChatTimeline.followTargetForIndex(index: Int?): ChatScrollFollowTarget? {
  if (index == null) return null
  return when {
    latestUserMessageId != null && index == readAnchorIndex -> ChatScrollFollowTarget.ReadAnchor
    index == latestContentIndex -> ChatScrollFollowTarget.LatestContent
    else -> null
  }
}

private fun isAtTarget(
  index: Int,
  offset: Int,
  target: Int?,
  tolerancePx: Int,
): Boolean = target != null && index == target && offset <= tolerancePx

