/** Attachment staged in a composer until the next chat.send call. */
data class PendingAttachment(
  val id: String,
  val fileName: String,
  val mimeType: String,
  val base64: String,
  val durationMs: Long? = null,
  val videoThumbnailBase64: String? = null,
