internal data class RealtimeAgentSession(
  val relaySessionId: String,
  val sessionKey: String,
)

private data class RealtimeAgentRun(
  val callId: String,
  val session: RealtimeAgentSession,
  val agentSessionKey: String,
)

private data class RealtimeAgentCompletion(
  val sessionKey: String?,
  val state: String,
  val message: JsonElement?,
  val pendingCalls: Set<RealtimeAgentPendingCall> = emptySet(),
)

internal data class RealtimeAgentUnhandledCompletion(
  val sessionKey: String?,
  val runId: String,
  val state: String,
  val message: JsonElement?,
)

private class RealtimeAgentPendingCall(
  val callId: String,
  val session: RealtimeAgentSession,
) {
  var job: Job? = null
  var failed = false
}

private data class RealtimeAgentCacheOverflow(
  val unhandled: List<RealtimeAgentUnhandledCompletion>,
  val failedCalls: List<RealtimeAgentPendingCall>,
)

private data class RealtimeAgentPendingFinish(
  val canSubmitError: Boolean,
  val unhandled: List<RealtimeAgentUnhandledCompletion>,
)

private data class RealtimeAgentRunRegistration(
  val completion: RealtimeAgentCompletion?,
  val errorMessage: String?,
  val unhandled: List<RealtimeAgentUnhandledCompletion>,
)

/**
 * Owns Android's provider-tool-call lifecycle for every realtime Talk surface.
 * Replacing the session cancels session-owned work while retaining bounded
 * correlation for late Gateway responses; transport replacement cancels both.
 */
internal class RealtimeAgentCoordinator(
  parentScope: CoroutineScope,
  private val requestGateway: suspend (method: String, paramsJson: String?, timeoutMs: Long) -> String,
  private val onWorking: (RealtimeAgentSession) -> Unit = {},
  private val onError: (RealtimeAgentSession, String) -> Unit = { _, message ->
    Log.w(TAG, message)
  },
  private val onUnhandledCompletion: (RealtimeAgentUnhandledCompletion) -> Unit = {},
  private val maxCachedCompletions: Int = MAX_CACHED_COMPLETIONS,
) {
  private val json = Json { ignoreUnknownKeys = true }
  private val lock = Any()
  private val parentContext = parentScope.coroutineContext
  private val parentJob = parentContext[Job]
  private var transportGeneration = Any()
  private var activeSession: RealtimeAgentSession? = null
  private var sessionScope: CoroutineScope? = null
  private val correlationJobs = LinkedHashSet<Job>()
  private val runs = LinkedHashMap<String, RealtimeAgentRun>()
  private val pendingCalls = LinkedHashSet<RealtimeAgentPendingCall>()
  private val earlyCompletions = LinkedHashMap<Pair<String, String?>, RealtimeAgentCompletion>()

  // A replacement can reuse the same chat session key, so keep known old run IDs
  // long enough to consume delayed finals instead of leaking them into normal Talk TTS.
  private val retiredRunIds = LinkedHashSet<String>()

  init {
    require(maxCachedCompletions > 0)
  }

  fun beginSession(session: RealtimeAgentSession) {
    val unhandled =
      synchronized(lock) {
        if (activeSession == session) return
        clearSessionLocked().also {
          activeSession = session
          sessionScope = CoroutineScope(parentContext + SupervisorJob(parentJob))
        }
      }
    unhandled.forEach(onUnhandledCompletion)
  }

  fun endSession(expectedRelaySessionId: String? = null) {
    val unhandled =
      synchronized(lock) {
        if (expectedRelaySessionId != null && activeSession?.relaySessionId != expectedRelaySessionId) return
        clearSessionLocked()
      }
    unhandled.forEach(onUnhandledCompletion)
  }

  /** Cancels requests that must not survive a Gateway or account replacement. */
  fun resetTransport() {
    // Lazy correlation jobs can complete synchronously during cancellation. Drop
    // account-bound state first so their handlers cannot release stale output.
    val staleJobs =
      synchronized(lock) {
        clearSessionLocked()
        transportGeneration = Any()
        val jobs = correlationJobs.toList()
        correlationJobs.clear()
        pendingCalls.clear()
        earlyCompletions.clear()
        jobs
      }
    staleJobs.forEach(Job::cancel)
  }

  fun handleToolCall(
    callId: String,
    name: String,
    args: JsonElement?,
    forced: Boolean,
  ): Boolean {
    val sessionAndScopes =
      synchronized(lock) {
        val session = activeSession ?: return false
        val resultScope = sessionScope ?: return false
        Triple(session, resultScope, transportGeneration)
      }
    val (session, resultScope, generation) = sessionAndScopes
    when (name) {
      AGENT_CONSULT_TOOL -> {
        val pendingCall = RealtimeAgentPendingCall(callId = callId, session = session)
        val accepted =
          synchronized(lock) {
            activeSession == session &&
              pendingCalls.size + runs.size < maxCachedCompletions &&
              pendingCalls.add(pendingCall)
          }
        if (accepted) {
          val supervisor = SupervisorJob(parentJob)
          val job =
            CoroutineScope(parentContext + supervisor).launch(start = CoroutineStart.LAZY) {
              runConsult(pendingCall, args, forced)
            }
          job.invokeOnCompletion {
            supervisor.cancel()
            synchronized(lock) { correlationJobs.remove(job) }
            finishPending(pendingCall).unhandled.forEach(onUnhandledCompletion)
          }
          val shouldStart =
            synchronized(lock) {
              if (
                activeSession == session &&
                transportGeneration === generation &&
                isPendingLocked(pendingCall)
              ) {
                pendingCall.job = job
                correlationJobs += job
                true
              } else {
                false
              }
            }
          if (shouldStart) job.start() else job.cancel()
        } else {
          resultScope.launch { submitError(session, callId, "too many concurrent realtime Talk tool calls") }
        }
      }
      AGENT_CONTROL_TOOL -> resultScope.launch { runControl(session, callId, args) }
      else -> resultScope.launch { submitError(session, callId, "unsupported realtime Talk tool: $name") }
    }
    return true
  }

  fun handleChatEvent(
    sessionKey: String?,
    runId: String,
    state: String,
    message: JsonElement?,
  ): Boolean {
    if (state !in TERMINAL_STATES) return false
    val completion = RealtimeAgentCompletion(sessionKey = sessionKey, state = state, message = message)
    var dispatch: Pair<RealtimeAgentRun, RealtimeAgentCompletion>? = null
    var overflow: RealtimeAgentCacheOverflow? = null
    val handled =
      synchronized(lock) {
        if (runId in retiredRunIds) return@synchronized true
        val run = runs[runId]
        if (run != null && (sessionKey == null || sessionKey == run.agentSessionKey)) {
          runs.remove(runId)
          retireRunLocked(runId)
          if (run.session == activeSession) {
            dispatch = run to completion
          }
          true
        } else if (run != null) {
          false
        } else if (pendingCalls.any { !it.failed }) {
          overflow = cacheEarlyCompletionLocked(runId, completion)
          true
        } else {
          false
        }
      }
    dispatch?.let { dispatchCompletion(it.first, it.second) }
    overflow?.let { result ->
      result.unhandled.forEach(onUnhandledCompletion)
      failOverflowedCalls(result.failedCalls)
    }
    return handled
  }

  private suspend fun runConsult(
    pendingCall: RealtimeAgentPendingCall,
    args: JsonElement?,
    forced: Boolean,
  ) {
    val session = pendingCall.session
    val callId = pendingCall.callId
    try {
      if (forced) submitWorking(session, callId)
      if (!isActive(session)) return
      val params =
        buildJsonObject {
          put("sessionKey", JsonPrimitive(session.sessionKey))
          put("callId", JsonPrimitive(callId))
          put("name", JsonPrimitive(AGENT_CONSULT_TOOL))
          put("relaySessionId", JsonPrimitive(session.relaySessionId))
          if (args != null) put("args", args)
        }
      val response = requestGateway("talk.client.toolCall", params.toString(), TOOL_CALL_TIMEOUT_MILLIS)
      val ack = runCatching { json.parseToJsonElement(response) as? JsonObject }.getOrNull()
      val runId = ack?.get("runId").asStringOrNull()
      if (runId.isNullOrBlank()) {
        val finish = finishPending(pendingCall)
        finish.unhandled.forEach(onUnhandledCompletion)
        if (finish.canSubmitError) submitError(session, callId, "tool call returned no run id")
        return
      }
      // Stable v2026.8.1 Gateways omit the target; newer ACKs own chat correlation
      // while the original session key continues to identify the voice relay.
      val run = RealtimeAgentRun(callId, session, ack?.get("agentSessionKey").asStringOrNull() ?: session.sessionKey)
      if (!isPending(pendingCall)) {
        synchronized(lock) { retireRunLocked(runId) }
        return
      }
      // Surface callbacks may take their own lifecycle locks, so never invoke one
      // while holding the coordinator lock. A final racing this callback is cached
      // against the pending call and consumed immediately after registration.
      if (isActive(session)) onWorking(session)
      val registration =
        synchronized(lock) {
          if (!isPendingLocked(pendingCall)) {
            retireRunLocked(runId)
            return
          }
          val cached =
            (earlyCompletions[runId to run.agentSessionKey] ?: earlyCompletions[runId to null])
              ?.takeIf { pendingCall in it.pendingCalls }
          val duplicate =
            runId in retiredRunIds ||
              runId in runs ||
              earlyCompletions.any { (key, event) -> key.first == runId && pendingCall !in event.pendingCalls }
          if (cached != null && !duplicate) {
            earlyCompletions.remove(runId to cached.sessionKey)
            // A legacy keyless copy is the same run, never a separate local TTS reply.
            earlyCompletions.remove(runId to null)
          }
          pendingCalls.remove(pendingCall)
          val errorMessage =
            when {
              activeSession == session && duplicate -> "tool call returned a duplicate run id"
              activeSession != session || cached != null -> {
                retireRunLocked(runId)
                null
              }
              else -> {
                runs[runId] = run
                null
              }
            }
          RealtimeAgentRunRegistration(
            completion = cached.takeIf { activeSession == session && !duplicate },
            errorMessage = errorMessage,
            unhandled = drainUnclaimedCompletionsLocked(),
          )
        }
      registration.unhandled.forEach(onUnhandledCompletion)
      if (registration.errorMessage != null) {
        submitError(session, callId, registration.errorMessage)
      } else if (registration.completion != null) {
        dispatchCompletion(run, registration.completion)
      }
    } catch (err: TimeoutCancellationException) {
      val finish = finishPending(pendingCall)
      finish.unhandled.forEach(onUnhandledCompletion)
      if (finish.canSubmitError) submitError(session, callId, "tool call timed out")
    } catch (err: CancellationException) {
      throw err
    } catch (err: Throwable) {
      val message = err.message ?: "tool call failed"
      val finish = finishPending(pendingCall)
      finish.unhandled.forEach(onUnhandledCompletion)
      if (finish.canSubmitError) {
        onError(session, "realtime toolCall failed: $message")
        submitError(session, callId, message)
      }
    }
  }

  private suspend fun runControl(
    session: RealtimeAgentSession,
    callId: String,
    args: JsonElement?,
  ) {
    try {
      val argsObject = args as? JsonObject
      val text =
        argsObject
          ?.get("text")
          .asStringOrNull()
          ?.trim()
          .orEmpty()
      val mode =
        argsObject
          ?.get("mode")
          .asStringOrNull()
          ?.trim()
          ?.takeIf(String::isNotEmpty)
      val params =
        buildJsonObject {
          put("sessionId", JsonPrimitive(session.relaySessionId))
          put("sessionKey", JsonPrimitive(session.sessionKey))
          put("text", JsonPrimitive(text.ifEmpty { "status" }))
          if (mode != null) put("mode", JsonPrimitive(mode))
        }
      val response = requestGateway("talk.session.steer", params.toString(), TOOL_CALL_TIMEOUT_MILLIS)
      val result = runCatching { json.parseToJsonElement(response) as? JsonObject }.getOrNull()
      if (result == null) {
        submitError(session, callId, "control call returned no result")
      } else {
        submitResult(session, callId, result)
      }
    } catch (err: TimeoutCancellationException) {
      submitError(session, callId, "control call timed out")
    } catch (err: CancellationException) {
      throw err
    } catch (err: Throwable) {
      val message = err.message ?: "control call failed"
      onError(session, "realtime control failed: $message")
      submitError(session, callId, message)
    }
  }

  private fun dispatchCompletion(
    run: RealtimeAgentRun,
    completion: RealtimeAgentCompletion,
  ) {
    val scope = synchronized(lock) { sessionScope.takeIf { activeSession == run.session } } ?: return
    scope.launch {
      when (completion.state) {
        "final" -> {
          val text = ChatEventText.assistantTextFromMessage(completion.message).orEmpty()
          submitResult(
            run.session,
            run.callId,
            buildJsonObject { put("text", JsonPrimitive(text)) },
          )
        }
        "aborted", "error" -> submitError(run.session, run.callId, completion.state)
      }
    }
  }

  private fun failOverflowedCalls(calls: List<RealtimeAgentPendingCall>) {
    calls.forEach { it.job?.cancel() }
    calls.forEach { call ->
      val scope = synchronized(lock) { sessionScope.takeIf { activeSession == call.session } } ?: return@forEach
      scope.launch { submitError(call.session, call.callId, "tool completion correlation buffer overflow") }
    }
  }

  private suspend fun submitWorking(
    session: RealtimeAgentSession,
    callId: String,
  ) {
    submitResult(
      session = session,
      callId = callId,
      result =
        buildJsonObject {
          put("status", JsonPrimitive("working"))
          put("tool", JsonPrimitive(AGENT_CONSULT_TOOL))
          put(
            "message",
            JsonPrimitive(
              "Tell the person briefly that you are checking, then wait for the final OpenClaw result before answering with the actual result.",
            ),
          )
        },
      options = buildJsonObject { put("willContinue", JsonPrimitive(true)) },
    )
  }

  private suspend fun submitError(
    session: RealtimeAgentSession,
    callId: String,
    message: String,
  ) {
    submitResult(
      session = session,
      callId = callId,
      result = buildJsonObject { put("error", JsonPrimitive(message)) },
    )
  }

  private suspend fun submitResult(
    session: RealtimeAgentSession,
    callId: String,
    result: JsonObject,
    options: JsonObject? = null,
  ) {
    if (!isActive(session)) return
    val params =
      buildJsonObject {
        put("sessionId", JsonPrimitive(session.relaySessionId))
        put("callId", JsonPrimitive(callId))
        put("result", result)
        if (options != null) put("options", options)
      }
    try {
      requestGateway("talk.session.submitToolResult", params.toString(), TOOL_CALL_TIMEOUT_MILLIS)
    } catch (err: TimeoutCancellationException) {
      onError(session, "realtime submitToolResult timed out")
    } catch (err: CancellationException) {
      throw err
    } catch (err: Throwable) {
      onError(session, "realtime submitToolResult failed: ${err.message ?: err::class.simpleName}")
    }
  }

  private fun isActive(session: RealtimeAgentSession): Boolean = synchronized(lock) { activeSession == session }

  private fun isPending(call: RealtimeAgentPendingCall): Boolean = synchronized(lock) { isPendingLocked(call) }

  private fun isPendingLocked(call: RealtimeAgentPendingCall): Boolean = call in pendingCalls && !call.failed

  private fun clearSessionLocked(): List<RealtimeAgentUnhandledCompletion> {
    runs.keys.forEach(::retireRunLocked)
    activeSession = null
    sessionScope?.cancel()
    sessionScope = null
    runs.clear()
    return drainUnclaimedCompletionsLocked()
  }

  private fun finishPending(call: RealtimeAgentPendingCall): RealtimeAgentPendingFinish =
    synchronized(lock) {
      val removed = pendingCalls.remove(call)
      RealtimeAgentPendingFinish(
        canSubmitError = removed && !call.failed && activeSession == call.session,
        unhandled = if (removed) drainUnclaimedCompletionsLocked() else emptyList(),
      )
    }

  private fun drainUnclaimedCompletionsLocked(): List<RealtimeAgentUnhandledCompletion> {
    val ready = earlyCompletions.filterValues { completion -> completion.pendingCalls.none(::isPendingLocked) }
    ready.keys.forEach(earlyCompletions::remove)
    return ready.map { (key, completion) -> completion.toUnhandled(key.first) }
  }

  private fun cacheEarlyCompletionLocked(
    runId: String,
    completion: RealtimeAgentCompletion,
  ): RealtimeAgentCacheOverflow? {
    // Only calls already awaiting ACK can own this event. Later calls must not
    // prolong unrelated completions or claim output produced before they started.
    earlyCompletions.putIfAbsent(runId to completion.sessionKey, completion.copy(pendingCalls = pendingCalls.filterNot { it.failed }.toSet()))
    if (earlyCompletions.size <= maxCachedCompletions) return null
    val unhandled = earlyCompletions.map { (key, cached) -> cached.toUnhandled(key.first) }
    val failedCalls = pendingCalls.filterNot { it.failed }
    failedCalls.forEach { it.failed = true }
    earlyCompletions.clear()
    return RealtimeAgentCacheOverflow(unhandled = unhandled, failedCalls = failedCalls)
  }

  private fun retireRunLocked(runId: String) {
    retiredRunIds += runId
    while (retiredRunIds.size > maxCachedCompletions) {
      retiredRunIds.remove(retiredRunIds.first())
    }
  }

  private companion object {
    const val TAG = "RealtimeAgent"
    const val AGENT_CONSULT_TOOL = "openclaw_agent_consult"
    const val AGENT_CONTROL_TOOL = "openclaw_agent_control"
    const val TOOL_CALL_TIMEOUT_MILLIS = 15_000L
    const val MAX_CACHED_COMPLETIONS = 128
    val TERMINAL_STATES = setOf("final", "aborted", "error")
  }
}

private fun RealtimeAgentCompletion.toUnhandled(runId: String) =
  RealtimeAgentUnhandledCompletion(
    sessionKey = sessionKey,
    runId = runId,
    state = state,
    message = message,
  )

private fun JsonElement?.asStringOrNull(): String? = (this as? JsonPrimitive)?.takeIf { it.isString }?.content

package ai.openclaw.app.voice

import android.content.Context
import android.media.AudioAttributes
import android.speech.tts.TextToSpeech
import android.speech.tts.UtteranceProgressListener
import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.CompletableDeferred
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.Job
import kotlinx.coroutines.coroutineScope
import kotlinx.coroutines.ensureActive
import kotlinx.coroutines.job
import kotlinx.coroutines.withContext
import java.util.Locale
import java.util.UUID

/** Speaks text with the on-device engine when the gateway cannot render audio. */
internal interface LocalSpeechSpeaking {
  suspend fun speak(text: String)

  fun stop()
}

/** Owns initialization and one cancellable, ordered local speech request for Chat or Talk. */
internal class SystemSpeechSpeaker(
  private val context: Context,
) : LocalSpeechSpeaking {
  private val lock = Any()
  private var engine: TextToSpeech? = null
  private var ready: CompletableDeferred<Int>? = null
  private var active: Job? = null

  override suspend fun speak(text: String) {
    speak(text, locale = null, speechRate = null, beforeSpeak = {})
  }

  suspend fun speak(
    text: String,
    locale: Locale?,
    speechRate: Float?,
    beforeSpeak: () -> Unit,
  ) = coroutineScope {
    val request = coroutineContext.job
    try {
      synchronized(lock) {
        request.ensureActive()
        val previous = active
        active = request
        previous?.cancel()
        engine?.stop()
      }
      val speechEngine = ensureEngine(request)
      var start = 0
      while (start < text.length) {
        // Android caps each utterance in UTF-16 units. Keep every character, including
        // boundary whitespace, and never split a surrogate pair or flush an unfinished chunk.
        var end = start + minOf(TextToSpeech.getMaxSpeechInputLength(), text.length - start)
        if (end < text.length) {
          if (text[end - 1].isHighSurrogate() && text[end].isLowSurrogate()) end -= 1
          (end - 1 downTo start).firstOrNull { text[it].isWhitespace() }?.let { end = it + 1 }
        }
        val utteranceId = UUID.randomUUID().toString()
        val finished = CompletableDeferred<Unit>()
        try {
          withContext(Dispatchers.Main.immediate) {
            synchronized(lock) {
              checkActive(request)
              if (start == 0) {
                // Chat retains the engine's defaults; Talk supplies its validated directive.
                locale?.let {
                  val result = speechEngine.setLanguage(it)
                  check(result != TextToSpeech.LANG_MISSING_DATA && result != TextToSpeech.LANG_NOT_SUPPORTED) {
                    "Language unavailable on this device"
                  }
                }
                speechRate?.let { speechEngine.setSpeechRate(it) }
                speechEngine.setAudioAttributes(
                  AudioAttributes
                    .Builder()
                    .setContentType(AudioAttributes.CONTENT_TYPE_SPEECH)
                    .setUsage(AudioAttributes.USAGE_MEDIA)
                    .build(),
                )
                beforeSpeak()
                checkActive(request)
              }
              speechEngine.setOnUtteranceProgressListener(
                object : UtteranceProgressListener() {
                  override fun onStart(id: String?) = Unit

                  override fun onDone(id: String?) {
                    if (id == utteranceId) finished.complete(Unit)
                  }

                  @Suppress("OVERRIDE_DEPRECATION")
                  @Deprecated("Deprecated in Java")
                  override fun onError(id: String?) {
                    onError(id, TextToSpeech.ERROR_SYNTHESIS)
                  }

                  override fun onError(
                    id: String?,
                    errorCode: Int,
                  ) {
                    if (id == utteranceId) finished.completeExceptionally(IllegalStateException("TextToSpeech playback failed ($errorCode)"))
                  }

                  override fun onStop(
                    id: String?,
                    interrupted: Boolean,
                  ) {
                    if (id == utteranceId) finished.cancel()
                  }
                },
              )
              check(speechEngine.speak(text.substring(start, end), TextToSpeech.QUEUE_FLUSH, null, utteranceId) == TextToSpeech.SUCCESS) {
                "TextToSpeech start failed"
              }
            }
          }
          finished.await()
        } finally {
          finished.cancel()
        }
        start = end
      }
    } finally {
      synchronized(lock) {
        // A canceled request's callbacks/finally must not stop its replacement.
        if (active === request) {
          active = null
          engine?.stop()
        }
      }
    }
  }

  override fun stop() {
    synchronized(lock) {
      val request = active
      active = null
      request?.cancel()
      engine?.stop()
    }
  }

  fun shutdown() {
    synchronized(lock) {
      val request = active
      val pending = ready
      val retired = engine
      active = null
      ready = null
      engine = null
      request?.cancel()
      pending?.cancel()
      retired?.stop()
      retired?.shutdown()
    }
  }

  private fun checkActive(request: Job) {
    request.ensureActive()
    if (active !== request) throw CancellationException("Speech request superseded")
  }

  private suspend fun ensureEngine(request: Job): TextToSpeech =
    withContext(Dispatchers.Main.immediate) {
      val pending =
        synchronized(lock) {
          checkActive(request)
          ready ?: CompletableDeferred<Int>().also { initialization ->
            ready = initialization
            try {
              // Allocate and publish without suspension. A late callback only completes its
              // own initialization; it cannot republish an engine retired by shutdown.
              engine = TextToSpeech(context) { initialization.complete(it) }
            } catch (err: Throwable) {
              if (ready === initialization) ready = null
              initialization.completeExceptionally(err)
              throw err
            }
          }
        }
      val result = pending.await()
      synchronized(lock) {
        checkActive(request)
        if (result != TextToSpeech.SUCCESS) {
          val failed = engine
          engine = null
          ready = null
          failed?.shutdown()
          error("TextToSpeech init failed ($result)")
        }
        checkNotNull(engine)
      }
    }
}

package ai.openclaw.app.voice

import kotlin.math.log10
import kotlin.math.max
import kotlin.math.sqrt

/**
 * Kotlin port of OpenClawKit's `TalkAudioLevel`: the shared 0..1 UI level scale
 * (dB full scale over a 50 dB window) used by every talk waveform surface, so
 * Android levels read identically to iOS/macOS. Change the Swift original in
 * `TalkPlaybackLevelMeters.swift` first; every constant mirrors it.
 */
internal object TalkAudioLevel {
  fun normalized(rms: Double): Float = normalizedDecibels(20.0 * log10(max(rms, 1e-7)))

  fun normalizedDecibels(decibels: Double): Float = ((decibels + 50.0) / 50.0).coerceIn(0.0, 1.0).toFloat()

  /** Normalized level of little-endian PCM16 audio; 0 for empty frames. */
  fun pcm16Level(
    frame: ByteArray,
    length: Int,
  ): Float = normalized(pcm16Rms(frame, length))

  /** RMS of little-endian PCM16 audio in 0..1; 0 for empty or odd-length frames. */
  fun pcm16Rms(
    frame: ByteArray,
    length: Int,
  ): Double {
    var sum = 0.0
    var count = 0
    var index = 0
    val limit = length - (length % 2)
    while (index < limit) {
      val sample =
        ((frame[index].toInt() and 0xff) or (frame[index + 1].toInt() shl 8))
          .toShort()
          .toInt()
      val value = sample / Short.MAX_VALUE.toDouble()
      sum += value * value
      count += 1
      index += 2
    }
    if (count == 0) return 0.0
    return sqrt(sum / count)
  }

  /** iOS-parity level smoothing (new = old*0.8 + raw*0.2) for waveform meters. */
  fun smoothed(
    previous: Float,
    raw: Float,
  ): Float = previous * 0.8f + raw * 0.2f
}

package ai.openclaw.app.voice

import android.content.Context
import android.media.AudioAttributes
import android.media.AudioFormat
import android.media.AudioTrack
import android.media.MediaPlayer
import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.CompletableDeferred
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.NonCancellable
import kotlinx.coroutines.delay
import kotlinx.coroutines.withContext
import java.io.File

internal interface TalkAudioPlaying {
  /** Plays one assistant reply, replacing any active playback. */
  suspend fun play(audio: TalkSpeakAudio)

  /** Cancels any active assistant reply playback. */
  fun stop()
}

/** Android playback adapter for remote talk.speak audio payloads. */
internal class TalkAudioPlayer(
  private val context: Context,
) : TalkAudioPlaying {
  private val lock = Any()
  private var active: ActivePlayback? = null

  override suspend fun play(audio: TalkSpeakAudio) {
    when (val mode = resolvePlaybackMode(audio)) {
      is TalkPlaybackMode.Pcm -> playPcm(audio.bytes, mode.sampleRate)
      is TalkPlaybackMode.Compressed -> playCompressed(audio.bytes, mode.fileExtension)
    }
  }

  override fun stop() {
    synchronized(lock) {
      active?.cancel()
      active = null
    }
  }

  /** Resolves playback mode from the metadata carried with a talk.speak response. */
  internal fun resolvePlaybackMode(audio: TalkSpeakAudio): TalkPlaybackMode =
    resolvePlaybackMode(
      outputFormat = audio.outputFormat,
      mimeType = audio.mimeType,
      fileExtension = audio.fileExtension,
    )

  companion object {
    /** Chooses PCM streaming or MediaPlayer-backed playback from provider metadata. */
    internal fun resolvePlaybackMode(
      outputFormat: String?,
      mimeType: String?,
      fileExtension: String?,
    ): TalkPlaybackMode {
      val normalizedOutputFormat = outputFormat?.trim()?.lowercase()
      if (normalizedOutputFormat != null) {
        val pcmSampleRate = parsePcmSampleRate(normalizedOutputFormat)
        if (pcmSampleRate != null) {
          return TalkPlaybackMode.Pcm(sampleRate = pcmSampleRate)
        }
      }
      val normalizedMimeType = mimeType?.trim()?.lowercase()
      val extension =
        normalizeExtension(
          fileExtension ?: inferExtension(outputFormat = normalizedOutputFormat, mimeType = normalizedMimeType),
        )
      if (extension != null) {
        return TalkPlaybackMode.Compressed(fileExtension = extension)
      }
      throw IllegalStateException("Unsupported talk audio format")
    }

    private fun parsePcmSampleRate(outputFormat: String): Int? =
      when (outputFormat) {
        "pcm_16000" -> 16_000
        "pcm_22050" -> 22_050
        "pcm_24000" -> 24_000
        "pcm_44100" -> 44_100
        else -> null
      }

    private fun inferExtension(
      outputFormat: String?,
      mimeType: String?,
    ): String? =
      when {
        outputFormat == "mp3" || outputFormat?.startsWith("mp3_") == true || mimeType == "audio/mpeg" -> ".mp3"
        outputFormat == "opus" || outputFormat?.startsWith("opus_") == true || mimeType == "audio/ogg" -> ".ogg"
        outputFormat?.endsWith("-wav") == true || mimeType == "audio/wav" -> ".wav"
        outputFormat?.endsWith("-webm") == true || mimeType == "audio/webm" -> ".webm"
        else -> null
      }

    private fun normalizeExtension(value: String?): String? {
      val trimmed = value?.trim()?.lowercase().orEmpty()
      if (trimmed.isEmpty()) return null
      return if (trimmed.startsWith(".")) trimmed else ".$trimmed"
    }
  }

  private suspend fun playPcm(
    bytes: ByteArray,
    sampleRate: Int,
  ) {
    withContext(Dispatchers.IO) {
      val minBufferSize =
        AudioTrack.getMinBufferSize(
          sampleRate,
          AudioFormat.CHANNEL_OUT_MONO,
          AudioFormat.ENCODING_PCM_16BIT,
        )
      if (minBufferSize <= 0) {
        throw IllegalStateException("AudioTrack buffer unavailable")
      }
      val track =
        AudioTrack
          .Builder()
          .setAudioAttributes(
            AudioAttributes
              .Builder()
              .setUsage(AudioAttributes.USAGE_MEDIA)
              .setContentType(AudioAttributes.CONTENT_TYPE_SPEECH)
              .build(),
          ).setAudioFormat(
            AudioFormat
              .Builder()
              .setEncoding(AudioFormat.ENCODING_PCM_16BIT)
              .setSampleRate(sampleRate)
              .setChannelMask(AudioFormat.CHANNEL_OUT_MONO)
              .build(),
          ).setTransferMode(AudioTrack.MODE_STATIC)
          .setBufferSizeInBytes(maxOf(minBufferSize, bytes.size))
          .build()
      val finished = CompletableDeferred<Unit>()
      val playback =
        ActivePlayback(
          cancel = {
            finished.completeExceptionally(CancellationException("assistant speech cancelled"))
            runCatching { track.pause() }
            runCatching { track.flush() }
            runCatching { track.stop() }
          },
        )
      register(playback)
      try {
        val written = track.write(bytes, 0, bytes.size)
        if (written != bytes.size) {
          throw IllegalStateException("AudioTrack write failed")
        }
        val totalFrames = bytes.size / 2
        track.play()
        while (track.playState == AudioTrack.PLAYSTATE_PLAYING) {
          if (track.playbackHeadPosition >= totalFrames) {
            finished.complete(Unit)
            break
          }
          delay(20)
        }
        if (!finished.isCompleted) {
          finished.complete(Unit)
        }
        finished.await()
      } finally {
        clear(playback)
        runCatching { track.pause() }
        runCatching { track.flush() }
        runCatching { track.stop() }
        track.release()
      }
    }
  }

  private suspend fun playCompressed(
    bytes: ByteArray,
    fileExtension: String,
  ) {
    // MediaPlayer needs a seekable data source for several compressed formats,
    // so cache the response bytes briefly instead of streaming from memory.
    // Own resources immediately: cancellation can discard a dispatcher result after allocation.
    var tempFile: File? = null
    try {
      val audioFile =
        withContext(Dispatchers.IO) {
          File.createTempFile("talk-audio-", fileExtension, context.cacheDir).also { created ->
            tempFile = created
            created.writeBytes(bytes)
          }
        }
      val finished = CompletableDeferred<Unit>()
      var mediaPlayer: MediaPlayer? = null
      try {
        val player =
          withContext(Dispatchers.Main) {
            MediaPlayer().also { mediaPlayer = it }.apply {
              setAudioAttributes(
                AudioAttributes
                  .Builder()
                  .setUsage(AudioAttributes.USAGE_MEDIA)
                  .setContentType(AudioAttributes.CONTENT_TYPE_SPEECH)
                  .build(),
              )
              setDataSource(audioFile.absolutePath)
              setOnCompletionListener {
                finished.complete(Unit)
              }
              setOnErrorListener { _, what, extra ->
                finished.completeExceptionally(IllegalStateException("MediaPlayer error ($what/$extra)"))
                true
              }
              prepare()
            }
          }
        val playback =
          ActivePlayback(
            cancel = {
              finished.completeExceptionally(CancellationException("assistant speech cancelled"))
              runCatching { player.stop() }
            },
          )
        register(playback)
        try {
          withContext(Dispatchers.Main) {
            player.start()
          }
          finished.await()
        } finally {
          clear(playback)
        }
      } finally {
        withContext(NonCancellable + Dispatchers.Main) {
          mediaPlayer?.let { player ->
            runCatching { player.stop() }
            player.release()
          }
        }
      }
    } finally {
      withContext(NonCancellable + Dispatchers.IO) {
        tempFile?.delete()
      }
    }
  }

  private fun register(playback: ActivePlayback) {
    synchronized(lock) {
      active?.cancel()
      active = playback
    }
  }

  private fun clear(playback: ActivePlayback) {
    synchronized(lock) {
      if (active === playback) {
        active = null
      }
    }
  }
}

internal sealed interface TalkPlaybackMode {
  /** Raw signed 16-bit mono PCM returned by providers that support low-latency output. */
  data class Pcm(
    val sampleRate: Int,
  ) : TalkPlaybackMode

  /** Compressed audio that Android decodes through MediaPlayer. */
  data class Compressed(
    val fileExtension: String,
  ) : TalkPlaybackMode
}

private class ActivePlayback(
  val cancel: () -> Unit,
)

