    val first = ChatShareDraft(id = 1, text = "first", attachments = emptyList(), droppedAttachmentCount = 0)
    val overflow = ChatShareDraft(id = 2, text = "overflow", attachments = emptyList(), droppedAttachmentCount = 0)

    assertTrue(queue.enqueue(first, owner))
    assertFalse(queue.enqueue(overflow, owner))
    assertEquals(1, queue.size())
    assertEquals(first, queue.head.value)
  }

  @Test
  fun anotherOwnersShareCanAdvanceWithoutRetargetingTheGlobalHead() =
    runBlocking {
      val queue = ChatShareDraftQueue(capacity = 2)
      val ownerA = composerOwner("agent-a", "session-a")
      val ownerB = composerOwner("agent-b", "session-b")
      val first = ChatShareDraft(id = 1, text = "first", attachments = emptyList(), droppedAttachmentCount = 0)
      val second = ChatShareDraft(id = 2, text = "second", attachments = emptyList(), droppedAttachmentCount = 0)
      queue.enqueue(first, ownerA)
      queue.enqueue(second, ownerB)

      assertEquals(first, queue.head.value)
      assertTrue(queue.withHeadLease(second.id, ownerB) {})
      assertTrue(queue.acknowledgeHead(second.id, ownerB))
      assertEquals(first, queue.head.value)
      assertTrue(queue.withHeadLease(first.id, ownerA) {})
    }

  @Test
  fun overlappingActivityLoadersCannotCommitTheSameHead() =
    runBlocking {
      val queue = ChatShareDraftQueue(capacity = 2)
      val first = ChatShareDraft(id = 1, text = "first", attachments = emptyList(), droppedAttachmentCount = 0)
      val next = ChatShareDraft(id = 2, text = "second", attachments = emptyList(), droppedAttachmentCount = 0)
      val owner = composerOwner("main", "agent:main:device")
      queue.enqueue(first, owner)
      queue.enqueue(next, owner)
      val entered = CompletableDeferred<Unit>()
      val release = CompletableDeferred<Unit>()

      val firstLoader =
        async {
          queue.withHeadLease(first.id, owner) {
            entered.complete(Unit)
            release.await()
            assertTrue(queue.acknowledgeHead(first.id, owner))
          }
        }
      entered.await()
      var staleLoaderRan = false
      val staleLoader =
        async {
          queue.withHeadLease(first.id, owner) {
            staleLoaderRan = true
          }
        }
      release.complete(Unit)

      assertTrue(firstLoader.await())
      assertFalse(staleLoader.await())
      assertFalse(staleLoaderRan)
      assertEquals(next, queue.head.value)
    }

  @Test
  fun claimedShareCannotRetargetAcrossComposerNavigation() =
    runBlocking {
      val queue = ChatShareDraftQueue(capacity = 1)
      val share = ChatShareDraft(id = 1, text = "private", attachments = emptyList(), droppedAttachmentCount = 0)
      val ownerA = composerOwner("agent-a", "session-a")
      val ownerB = composerOwner("agent-b", "session-b")
      val resolvedA = ownerA.copy(sessionKey = "agent:agent-a:device")
      queue.enqueue(share, ownerA)

      assertTrue(queue.withHeadLease(share.id, ownerA) {})
      assertFalse(queue.withHeadLease(share.id, ownerB) {})
      assertFalse(queue.acknowledgeHead(share.id, ownerB))

      queue.migrateOwner(ownerA, resolvedA)
      assertTrue(queue.withHeadLease(share.id, resolvedA) {})
      assertTrue(queue.acknowledgeHead(share.id, resolvedA))
    }

  @Test
  fun shareOwnerIsCapturedBeforeAnyLoaderRuns() =
    runBlocking {
      val queue = ChatShareDraftQueue(capacity = 1)
      val share = ChatShareDraft(id = 1, text = "private", attachments = emptyList(), droppedAttachmentCount = 0)
      val ownerA = composerOwner("agent-a", "session-a")
      val ownerB = composerOwner("agent-b", "session-b")

      assertTrue(queue.enqueue(share, ownerA))
      assertEquals(ownerA, queue.ownerOf(share.id))
      assertFalse(queue.withHeadLease(share.id, ownerB) {})
      assertTrue(queue.withHeadLease(share.id, ownerA) {})
    }

  @Test
  fun removingGatewaySharesKeepsOtherGatewayOwners() =
    runBlocking {
      val queue = ChatShareDraftQueue(capacity = 2)
      val ownerA = composerOwner("agent-a", "session-a", gatewayStableId = "gateway-a")
      val ownerB = composerOwner("agent-b", "session-b", gatewayStableId = "gateway-b")
      val first = ChatShareDraft(id = 1, text = "private a", attachments = emptyList(), droppedAttachmentCount = 0)
      val second = ChatShareDraft(id = 2, text = "private b", attachments = emptyList(), droppedAttachmentCount = 0)
      queue.enqueue(first, ownerA)
      queue.enqueue(second, ownerB)

      queue.removeOwners { it.gatewayStableId == "gateway-a" }

      assertEquals(listOf(second), queue.queued.value)
      assertNull(queue.ownerOf(first.id))
      assertEquals(ownerB, queue.ownerOf(second.id))
    }

  private fun composerOwner(
    agentId: String,
    sessionKey: String,
    gatewayStableId: String = "gateway",
  ): ai.openclaw.app.chat.ChatComposerOwner =
    ai.openclaw.app.chat.ChatComposerOwner(
      gatewayStableId = gatewayStableId,
      agentId = agentId,
      sessionKey = sessionKey,
    )

  private fun parseShare(
    intent: Intent,
    mimeTypes: Map<Uri, String> = emptyMap(),
  ): ShareLaunchRequest? = parseShareLaunchIntent(intent) { uri -> mimeTypes[uri] }
}

package ai.openclaw.app

import ai.openclaw.app.gateway.GatewayErrorDetails
import ai.openclaw.app.gateway.GatewaySession
import kotlinx.serialization.json.Json
import kotlinx.serialization.json.int
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test

class SkillManagementTest {
  private val json = Json { ignoreUnknownKeys = true }

  @Test
  fun searchResultsKeepOnlyIdentifiedSkills() {
    val results =
      parseClawHubSearchResults(
        """{"results":[{"slug":" alpha ","installRef":"@alice/alpha","displayName":"Alpha","summary":"Useful","version":"1.2.3"},{"slug":"missing-name"},{"displayName":"Missing slug"}]}""",
        json,
      )

    assertEquals(
      listOf(
        GatewayClawHubSkillSummary(
          slug = "alpha",
          installRef = "@alice/alpha",
          installOnly = null,
          trustState = null,
          displayName = "Alpha",
          summary = "Useful",
          version = "1.2.3",
        ),
      ),
      results,
    )
  }

  @Test
  fun sameSlugResultsKeepSeparatePublisherReferences() {
    val results =
      parseClawHubSearchResults(
        """{"results":[{"slug":"email","installRef":"@alice/email","displayName":"Email"},{"slug":"email","installRef":"@bob/email","displayName":"Email"},{"slug":"orphan","displayName":"Orphan"}]}""",
        json,
      )

    assertEquals(listOf("@alice/email", "@bob/email", "orphan"), results.map { it.reference })
  }

  @Test
  fun installOnlyResultsKeepTheirSourceAndExposeNoDetailAction() {
    val results =
      parseClawHubSearchResults(
        """{"results":[{"slug":"pdf","installRef":"skills-sh:openai/skills/pdf","installOnly":true,"trustState":"not-scanned-by-clawhub","displayName":"Pdf"},{"slug":"pdf","installRef":"@awspace/pdf","displayName":"Pdf"}]}""",
        json,
      )

    val external = results.first()
    val native = results.last()
    // Rewriting the external reference to @openai/pdf would install a different skill.
    assertEquals("skills-sh:openai/skills/pdf", external.reference)
    assertFalse(external.canReadDetails)
    assertTrue(external.isUnscannedSource)
    assertTrue(native.canReadDetails)

    // Android installs this exact reference directly; it never creates a release review.
    assertEquals("skills-sh:openai/skills/pdf", external.reference)
  }

  @Test
  fun resultsWithoutTheInstallOnlyFlagKeepTheReviewFlow() {
    // A Gateway released before the flag existed omits it from every row.
    val results =
      parseClawHubSearchResults(
        """{"results":[{"slug":"email","installRef":"@alice/email","displayName":"Email"}]}""",
        json,
      )

    // Treating omission as install-only would bypass the reviewed-version step those Gateways
    // still expect.
    assertTrue(results.first().canReadDetails)
    assertFalse(results.first().isUnscannedSource)
  }

  @Test
  fun installOnlyReadbackMatchesTheRecordedReference() {
    val installed =
      listOf(
        GatewaySkillSummary(
          skillKey = "pdf",
          name = "pdf",
          description = null,
          source = "clawhub",
          emoji = null,
          disabled = false,
          eligible = true,
          blockedByAllowlist = false,
          blockedByAgentFilter = false,
          bundled = false,
          missingCount = 0,
          installCount = 0,
          clawHubSlug = "pdf",
          clawHubValid = true,
          clawHubRequestedReference = "skills-sh:openai/skills/pdf",
        ),
      )

    // The canonical slug is "pdf", so matching by the sent reference is the only readback that
    // identifies this install without colliding with a registry skill of the same slug.
    assertTrue(isClawHubSkillInstalledByReference(installed, "skills-sh:openai/skills/pdf"))
    assertTrue(
      isClawHubSkillInstalled(
        installed,
        GatewayClawHubSkillSummary(
          slug = "pdf",
          installRef = "skills-sh:openai/skills/pdf",
          installOnly = true,
          trustState = "not-scanned-by-clawhub",
          displayName = "Pdf",
          summary = null,
          version = null,
        ),
      ),
    )
    assertFalse(isClawHubSkillInstalledByReference(installed, "skills-sh:other/skills/pdf"))
  }

  @Test
  fun detailBindsExactVersionAndPublisherIdentity() {
    val review =
      parseClawHubInstallReview(
        """{"skill":{"displayName":"Alpha Skill","summary":"Reviewed metadata"},"latestVersion":{"version":"2.0.0"},"owner":{"displayName":"Alice","handle":"alice"}}""",
        GatewayClawHubSkillSummary("alpha", null, null, null, "Alpha", null, null),
        json,
      )

    assertEquals(
      GatewayClawHubInstallReview(
        slug = "@alice/alpha",
        displayName = "Alpha Skill",
        summary = "Reviewed metadata",
        version = "2.0.0",
        author = "Alice",
      ),
      review,
    )
  }

  @Test
  fun detailVersionWinsWhenSearchResultIsStale() {
    val review =
      parseClawHubInstallReview(
        """{"skill":{"displayName":"Alpha"},"latestVersion":{"version":"2.0.0"},"owner":{"handle":"alice"}}""",
        GatewayClawHubSkillSummary("alpha", null, null, null, "Alpha", null, "1.9.0"),
        json,
      )

    assertEquals("2.0.0", review?.version)
  }

  @Test
  fun detailFailsClosedWithoutAnInstallableVersion() {
    val review =
      parseClawHubInstallReview(
        """{"skill":{"displayName":"Alpha"},"owner":{"handle":"alice"}}""",
        GatewayClawHubSkillSummary("alpha", null, null, null, "Alpha", null, null),
        json,
      )

    assertNull(review)
  }

  @Test
  fun installParamsKeepRegistryAndTrustPolicyOnGateway() {
    for ((reference, version) in listOf("@alice/alpha" to " 1.2.3 ", "skills-sh:openai/skills/pdf" to null)) {
      val params = json.parseToJsonElement(clawHubInstallParams(reference, version)).jsonObject
      val expectedKeys = setOf("source", "slug", "timeoutMs") + if (version == null) emptySet() else setOf("version")

      assertEquals(expectedKeys, params.keys)
      assertEquals("clawhub", params.getValue("source").jsonPrimitive.content)
      assertEquals(reference, params.getValue("slug").jsonPrimitive.content)
      assertEquals(version?.trim(), params["version"]?.jsonPrimitive?.content)
      assertEquals(120_000, params.getValue("timeoutMs").jsonPrimitive.int)
    }
  }

  @Test
  fun rejectionKeepsGatewayMessageAndWarning() {
    for (message in listOf("review required", "download blocked", "security verification unavailable")) {
      val rejection =
        clawHubInstallRejection(
          GatewaySession.ErrorShape(
            code = "UNAVAILABLE",
            message = message,
            details =
              GatewayErrorDetails(
                code = null,
                canRetryWithDeviceToken = false,
                recommendedNextStep = null,
                clawhubWarning = "  ClawHub audit details.\n ",
              ),
          ),
        )

      assertEquals(message, rejection.message)
      assertEquals("ClawHub audit details.", rejection.warning)
      assertEquals("$message\n\nClawHub audit details.", formatClawHubInstallMessage(rejection.message, rejection.warning))
    }
  }

  @Test
  fun rejectionFallsBackForBlankMessagesAndOmitsEmptyWarnings() {
    for (warning in listOf(null, "", " \n ")) {
      val rejection =
        clawHubInstallRejection(
          GatewaySession.ErrorShape(
            code = "UNAVAILABLE",
            message = " \n ",
            details =
              warning?.let {
                GatewayErrorDetails(
                  code = null,
                  canRetryWithDeviceToken = false,
                  recommendedNextStep = null,
                  clawhubWarning = it,
                )
              },
          ),
        )

      assertEquals("The Gateway rejected this ClawHub install.", rejection.message)
      assertNull(rejection.warning)
      assertEquals(rejection.message, formatClawHubInstallMessage(rejection.message, rejection.warning))
    }
  }

  @Test
  fun unknownInstallReadbackUsesClawHubProvenanceSlug() {
    val skill =
      GatewaySkillSummary(
        skillKey = "custom-frontmatter-key",
        name = "Custom display name",
        description = null,
        source = "openclaw-managed",
        emoji = null,
        disabled = false,
        eligible = true,
        blockedByAllowlist = false,
        blockedByAgentFilter = false,
        bundled = false,
        missingCount = 0,
        installCount = 0,
        clawHubSlug = "registry-slug",
        clawHubValid = true,
        clawHubOwnerHandle = "registry-owner",
        clawHubInstalledVersion = "1.2.3",
      )

    assertTrue(isClawHubSkillInstalled(listOf(skill), "registry-slug", "1.2.3"))
    assertTrue(isClawHubSkillInstalled(listOf(skill), "registry-slug"))
    assertTrue(isClawHubSkillInstalled(listOf(skill), "@registry-owner/registry-slug", "1.2.3"))
    assertFalse(isClawHubSkillInstalled(listOf(skill), "@other-owner/registry-slug", "1.2.3"))
    assertFalse(isClawHubSkillInstalled(listOf(skill), "registry-slug", "1.2.4"))
    assertFalse(isClawHubSkillInstalled(listOf(skill.copy(clawHubValid = false)), "registry-slug", "1.2.3"))
    assertFalse(isClawHubSkillInstalled(listOf(skill), "custom-frontmatter-key", "1.2.3"))
  }

  @Test
  fun ownerQualifiedInstallStaysActiveForBrowseSlug() {
    assertTrue(isClawHubSkillOperationActive(setOf("@registry-owner/registry-slug"), "registry-slug"))
    assertTrue(
      isClawHubSkillOperationActive(
        setOf("@registry-owner/registry-slug"),
        "@registry-owner/registry-slug",
      ),
    )
    assertFalse(
      isClawHubSkillOperationActive(
        setOf("@other-owner/registry-slug"),
        "@registry-owner/registry-slug",
      ),
    )
  }

  @Test
  fun clawHubManagementRequiresEveryAdvertisedMethod() {
    assertTrue(supportsClawHubSkillManagement(CLAWHUB_SKILL_GATEWAY_METHODS))
    assertFalse(supportsClawHubSkillManagement(CLAWHUB_SKILL_GATEWAY_METHODS - "skills.detail"))
  }
}

package ai.openclaw.app

import ai.openclaw.app.gateway.GatewayEndpoint
import ai.openclaw.app.i18n.NativeText
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.jsonObject
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertNull
import org.junit.Before
import org.junit.Test
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.RuntimeEnvironment
import org.robolectric.annotation.Config
import java.lang.reflect.Field
import java.util.UUID
import java.util.concurrent.atomic.AtomicLong

@RunWith(RobolectricTestRunner::class)
@Config(sdk = [34])
class SkillWorkshopAgentScopeRuntimeTest {
  private val json = Json { ignoreUnknownKeys = true }

  @Before
  fun clearPlainPrefs() {
    RuntimeEnvironment
      .getApplication()
      .getSharedPreferences("openclaw.node", android.content.Context.MODE_PRIVATE)
      .edit()
      .clear()
      .commit()
  }

  @Test
  fun gatewayActionsCarryClosedLocalizedPresentation() {
    val cases =
      listOf(
        SkillWorkshopGatewayAction.Apply to Triple("apply", "applied", "Proposal applied."),
        SkillWorkshopGatewayAction.Reject to Triple("reject", "rejected", "Proposal rejected."),
        SkillWorkshopGatewayAction.Quarantine to Triple("quarantine", "quarantined", "Proposal quarantined."),
      )

    for ((action, expected) in cases) {
      val (methodSuffix, expectedStatus, noticeSource) = expected
      assertEquals(methodSuffix, action.methodSuffix)
      assertEquals(expectedStatus, action.expectedStatus)
      assertEquals(NativeText.Resource(noticeSource, emptyList()), action.notice)
      assertEquals(NativeText.Resource(methodSuffix, emptyList()), action.verb)
      assertEquals(
        NativeText.Resource(
          source = "Gateway returned status '\$statusLabel' after \${action.verb}.",
          formatArgs = listOf(NativeText.Verbatim("future_status"), action.verb),
        ),
        skillWorkshopUnexpectedStatusText("future_status", action),
      )
      assertEquals(
        NativeText.Resource(
          source = "Could not \${action.verb} Skill Workshop proposal.",
          formatArgs = listOf(action.verb),
        ),
        skillWorkshopActionFailureText(action),
      )
    }
  }

  @Test
  fun missingGatewayActionStatusUsesLocalizedUnknownFallback() {
    assertEquals(
      NativeText.Resource(
        source = "Gateway returned status '\$statusLabel' after \${action.verb}.",
        formatArgs =
          listOf(
            NativeText.Resource(source = "unknown", formatArgs = emptyList()),
            SkillWorkshopGatewayAction.Apply.verb,
          ),
      ),
      skillWorkshopUnexpectedStatusText(null, SkillWorkshopGatewayAction.Apply),
    )
  }

  @Test
  fun resetSkillWorkshopAgentScopeClearsRowsAndInFlightActionState() {
    val runtime = createTestRuntime()
    seedConnectedRuntime(runtime)
    runtime.resetSkillWorkshopAgentScope("main")
    readField<MutableStateFlow<GatewaySkillWorkshopSummary>>(runtime, "_skillWorkshopSummary").value =
      GatewaySkillWorkshopSummary(
        agentId = "main",
        proposals = listOf(skillWorkshopProposal("main-proposal")),
      )

    runtime.resetSkillWorkshopAgentScope("ops")

    assertEquals("ops", runtime.skillWorkshopSummary.value.agentId)
    assertEquals(emptyList<GatewaySkillWorkshopProposal>(), runtime.skillWorkshopSummary.value.proposals)
    assertFalse(runtime.skillWorkshopRefreshing.value)
    assertNull(runtime.skillWorkshopErrorText.value)
    assertNull(runtime.skillWorkshopNoticeText.value)
    assertNull(runtime.skillWorkshopInspectingProposalId.value)
    assertNull(runtime.skillWorkshopMutatingProposalId.value)
  }

  @Test
  fun inspectAndMutateDoNotStartForStaleSelectedAgentScope() {
    val runtime = createTestRuntime()
    seedConnectedRuntime(runtime)
    runtime.resetSkillWorkshopAgentScope("main")

    runtime.inspectSkillWorkshopProposal(proposalId = "ops-proposal", agentId = "ops")
    readField<MutableStateFlow<List<String>>>(runtime, "_operatorScopes").value = listOf("operator.admin")
    waitUntil { runtime.operatorAdminScopeAvailable.value }
    runtime.applySkillWorkshopProposal(proposalId = "ops-proposal", agentId = "ops")
    Thread.sleep(100)

    assertEquals("main", runtime.skillWorkshopSummary.value.agentId)
    assertNull(runtime.skillWorkshopInspectingProposalId.value)
    assertNull(runtime.skillWorkshopMutatingProposalId.value)
    assertNull(runtime.skillWorkshopErrorText.value)
    assertNull(runtime.skillWorkshopNoticeText.value)
  }

  @Test
  fun busyProposalActionDoesNotInvalidateActiveRequestGenerations() {
    val runtime = createTestRuntime()
    seedConnectedRuntime(runtime)
    readField<MutableStateFlow<GatewaySkillWorkshopSummary>>(runtime, "_skillWorkshopSummary").value =
      GatewaySkillWorkshopSummary(
        agentId = "main",
        proposals = listOf(skillWorkshopProposal("proposal-1")),
      )
    readField<MutableStateFlow<List<String>>>(runtime, "_operatorScopes").value = listOf("operator.admin")
    waitUntil { runtime.operatorAdminScopeAvailable.value }
    readField<MutableStateFlow<String?>>(runtime, "_skillWorkshopMutatingProposalId").value = "proposal-1"
    val mutationSeq = readField<AtomicLong>(runtime, "skillWorkshopMutationSeq").apply { set(41) }
    val inspectSeq = readField<AtomicLong>(runtime, "skillWorkshopInspectSeq").apply { set(17) }

    runtime.applySkillWorkshopProposal(proposalId = "proposal-1", agentId = "main")
    runtime.inspectSkillWorkshopProposal(proposalId = "proposal-1", agentId = "main")
    Thread.sleep(100)

    assertEquals(41, mutationSeq.get())
    assertEquals(17, inspectSeq.get())
    assertEquals("proposal-1", runtime.skillWorkshopMutatingProposalId.value)
    assertNull(runtime.skillWorkshopInspectingProposalId.value)
  }

  @Test
  fun proposalActionResultUsesGatewayReturnedStatusAndPreservesInspectedDetails() {
    val runtime = createTestRuntime()
    val supportFiles =
      listOf(GatewaySkillWorkshopSupportFile(path = "references/proof.md", content = "proof"))
    val previous =
      skillWorkshopProposal("proposal-1")
        .copy(
          status = "pending",
          content = "inspected markdown",
          supportFiles = supportFiles,
        )

    val rejected =
      parseSkillWorkshopActionResult(
        runtime,
        """
        {
          "record": {
            "id": "proposal-1",
            "kind": "create",
            "status": "rejected",
            "title": "Rejected proposal",
            "description": "Gateway action response",
            "createdAt": "2026-07-08T00:00:00Z",
            "updatedAt": "2026-07-09T00:00:00Z",
            "scan": { "state": "clean" },
            "target": { "skillName": "Rejected Skill", "skillKey": "rejected-skill" }
          }
        }
        """.trimIndent(),
        previous,
      )

    assertEquals("rejected", rejected?.status)
    assertEquals("2026-07-09T00:00:00Z", rejected?.updatedAt)
    assertEquals("Rejected Skill", rejected?.skillName)
    assertEquals("clean", rejected?.scanState)
    assertEquals("inspected markdown", rejected?.content)
    assertEquals(supportFiles, rejected?.supportFiles)
  }

  private fun createTestRuntime(): NodeRuntime {
    val app = RuntimeEnvironment.getApplication()
    val securePrefs =
      app.getSharedPreferences(
        "openclaw.node.secure.test.${UUID.randomUUID()}",
        android.content.Context.MODE_PRIVATE,
      )
    return NodeRuntime(app, SecurePrefs(app, securePrefsOverride = securePrefs))
  }

  private fun seedConnectedRuntime(runtime: NodeRuntime) {
    writeField(runtime, "connectedEndpoint", GatewayEndpoint.manual("127.0.0.1", 18789))
    writeField(runtime, "operatorConnected", true)
  }

  private fun skillWorkshopProposal(id: String): GatewaySkillWorkshopProposal =
    GatewaySkillWorkshopProposal(
      id = id,
      status = "pending",
      kind = "create",
      title = "Proposal $id",
      skillKey = id,
      skillName = "Proposal $id",
      description = "desc",
      createdAt = "2026-07-08T00:00:00Z",
      updatedAt = "2026-07-08T00:00:00Z",
      scanState = null,
    )

  private fun parseSkillWorkshopActionResult(
    runtime: NodeRuntime,
    payloadJson: String,
    previous: GatewaySkillWorkshopProposal,
  ): GatewaySkillWorkshopProposal? {
    val method =
      runtime.javaClass.getDeclaredMethod(
        "parseSkillWorkshopProposalActionResult",
        JsonObject::class.java,
        GatewaySkillWorkshopProposal::class.java,
      )
    method.isAccessible = true
    @Suppress("UNCHECKED_CAST")
    return method.invoke(
      runtime,
      json.parseToJsonElement(payloadJson).jsonObject,
      previous,
    ) as GatewaySkillWorkshopProposal?
  }

  private fun waitUntil(condition: () -> Boolean) {
    repeat(50) {
      if (condition()) return
      Thread.sleep(10)
    }
    error("Expected condition to become true")
  }

  private fun writeField(
    target: Any,
    name: String,
    value: Any?,
  ) {
    var type: Class<*>? = target.javaClass
    while (type != null) {
      try {
        val field: Field = type.getDeclaredField(name)
        field.isAccessible = true
        field.set(target, value)
        return
      } catch (_: NoSuchFieldException) {
        type = type.superclass
      }
    }
    error("Field $name not found on ${target.javaClass.name}")
  }

  private fun <T> readField(
    target: Any,
    name: String,
  ): T {
    var type: Class<*>? = target.javaClass
    while (type != null) {
      try {
        val field: Field = type.getDeclaredField(name)
        field.isAccessible = true
        @Suppress("UNCHECKED_CAST")
        return field.get(target) as T
      } catch (_: NoSuchFieldException) {
        type = type.superclass
      }
    }
    error("Field $name not found on ${target.javaClass.name}")
  }
}

package ai.openclaw.app

import ai.openclaw.app.gateway.GatewayEndpoint
import ai.openclaw.app.ui.usageRefreshVisible
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertNotNull
import org.junit.Test
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.RuntimeEnvironment
import org.robolectric.annotation.Config
import java.lang.reflect.Field
import java.util.UUID
import java.util.concurrent.atomic.AtomicInteger

@RunWith(RobolectricTestRunner::class)
@Config(sdk = [34])
class UsageStatusRuntimeTest {
  @Test
  fun incompleteUsageConvergesOnACompletedPayload() {
    val runtime = createRuntime()
    connect(runtime)
    runtime.usageIncompleteRetryDelayMsForTests = 10L
    val calls = AtomicInteger()
    runtime.gatewayDataRequestOverrideForTests = { _, method, _ ->
      check(method == "usage.status")
      if (calls.incrementAndGet() == 1) {
        """{"updatedAt":1,"providers":[],"refreshing":true}"""
      } else {
        """{"updatedAt":2,"providers":[{"displayName":"Claude","plan":"Pro","windows":[]}]}"""
      }
    }

    runtime.refreshUsage()
    waitUntil {
      runtime.usageSummary.value.providers
        .isNotEmpty()
    }
    assertEquals(2, calls.get())
    assertFalse(runtime.usageSummary.value.refreshing)
  }

  @Test
  fun incompleteUsageRetriesStayBounded() {
    val runtime = createRuntime()
    connect(runtime)
    runtime.usageIncompleteRetryDelayMsForTests = 10L
    val calls = AtomicInteger()
    runtime.gatewayDataRequestOverrideForTests = { _, _, _ ->
      calls.incrementAndGet()
      """{"updatedAt":1,"providers":[],"refreshing":true}"""
    }

    runtime.refreshUsage()
    waitUntil { calls.get() == 4 }
    Thread.sleep(100)
    assertEquals(4, calls.get())
    assertFalse(runtime.usageSummary.value.refreshing)
    assertFalse(
      usageRefreshVisible(
        requestRefreshing = runtime.usageRefreshing.value,
        summaryRefreshing = runtime.usageSummary.value.refreshing,
      ),
    )
    // Clearing the marker without this would render "No usage data yet.",
    // claiming the operator has no providers instead of a failed load.
    assertNotNull(runtime.usageErrorText.value)
  }

  @Test
  fun aTransientFailurePreservesRowsAndStopsTheRetryChain() {
    val runtime = createRuntime()
    connect(runtime)
    runtime.usageIncompleteRetryDelayMsForTests = 10L
    val calls = AtomicInteger()
    runtime.gatewayDataRequestOverrideForTests = { _, _, _ ->
      if (calls.incrementAndGet() == 1) {
        """{"updatedAt":1,"providers":[{"displayName":"Claude","plan":"Pro","windows":[]}],"refreshing":true}"""
      } else {
        error("usage unavailable")
      }
    }

    runtime.refreshUsage()
    waitUntil {
      runtime.usageErrorText.value != null
    }
    Thread.sleep(100)
    assertEquals(2, calls.get())
    assertEquals(
      "Claude",
      runtime.usageSummary.value.providers
        .single()
        .displayName,
    )
    assertFalse(runtime.usageSummary.value.refreshing)
  }

  private fun createRuntime(): NodeRuntime {
    val app = RuntimeEnvironment.getApplication()
    val prefs =
      app.getSharedPreferences(
        "usage.${UUID.randomUUID()}",
        android.content.Context.MODE_PRIVATE,
      )
    return NodeRuntime(app, SecurePrefs(app, securePrefsOverride = prefs))
  }

  private fun connect(runtime: NodeRuntime) {
    field(runtime, "connectedEndpoint").set(runtime, GatewayEndpoint.manual("127.0.0.1", 18789))
    field(runtime, "operatorConnected").set(runtime, true)
  }

  private fun waitUntil(condition: () -> Boolean) {
    repeat(200) {
      if (condition()) return
      Thread.sleep(10)
    }
    error("condition did not become true")
  }

  private fun field(
    target: Any,
    name: String,
  ): Field {
    var type: Class<*>? = target.javaClass
    while (type != null) {
      try {
        return type.getDeclaredField(name).apply { isAccessible = true }
      } catch (_: NoSuchFieldException) {
        type = type.superclass
      }
    }
    error("field $name not found")
  }
}

package ai.openclaw.app

import ai.openclaw.app.ui.localizedInitial
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Test
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.annotation.Config
import java.util.Locale

@RunWith(RobolectricTestRunner::class)
@Config(sdk = [34])
class Utf16TextTest {
  @Test
  fun firstGraphemeOrNullPreservesUserPerceivedCharacters() {
    assertEquals("🧭", "🧭 Scout".firstGraphemeOrNull())
    assertEquals("🇺🇸", "🇺🇸 Scout".firstGraphemeOrNull())
    assertEquals("👩🏽‍💻", "👩🏽‍💻 Dev".firstGraphemeOrNull())
    assertEquals("A\u0308", "A\u0308lice".firstGraphemeOrNull())
    assertEquals("S", "Scout".firstGraphemeOrNull())
    assertNull("".firstGraphemeOrNull())
  }

  @Test
  fun uppercaseFirstGraphemeOrNullPreservesUserPerceivedCharacters() {
    assertEquals("🧭", "🧭 Scout".uppercaseFirstGraphemeOrNull())
    assertEquals("🇺🇸", "🇺🇸 Scout".uppercaseFirstGraphemeOrNull())
    assertEquals("👩🏽‍💻", "👩🏽‍💻 Dev".uppercaseFirstGraphemeOrNull())
    assertEquals("A\u0308", "a\u0308lice".uppercaseFirstGraphemeOrNull())
    assertEquals("S", "scout".uppercaseFirstGraphemeOrNull())
    assertEquals("ß", "ßcout".uppercaseFirstGraphemeOrNull())
    assertEquals("\uD801\uDC00", "\uD801\uDC28cout".uppercaseFirstGraphemeOrNull())
    assertNull("".uppercaseFirstGraphemeOrNull())
  }

  @Test
  fun localizedInitialPreservesGraphemesAndLocale() {
    assertEquals("🧭", localizedInitial("🧭 Scout", languageTag = "en", fallbackLocale = Locale.US))
    assertEquals("🇺🇸", localizedInitial("🇺🇸 Scout", languageTag = "en", fallbackLocale = Locale.US))
    assertEquals("👩🏽‍💻", localizedInitial("👩🏽‍💻 Dev", languageTag = "en", fallbackLocale = Locale.US))
    assertEquals("İ", localizedInitial("istanbul", languageTag = "tr", fallbackLocale = Locale.US))
    assertNull(localizedInitial("", languageTag = "en", fallbackLocale = Locale.US))
  }

  @Test
  fun takeUtf16SafePreservesCodeUnitLimitWithoutSplittingSurrogatePairs() {
    assertEquals("ab", "ab".takeUtf16Safe(2))
    assertEquals("ab", "abc".takeUtf16Safe(2))
    assertEquals("", "\uD83D\uDE00tail".takeUtf16Safe(1))
    assertEquals("\uD83D\uDE00", "\uD83D\uDE00tail".takeUtf16Safe(2))

    val splitPairPrefix = "a".repeat(156)
    assertEquals(splitPairPrefix, "$splitPairPrefix😀tail".takeUtf16Safe(157))
    val completePairPrefix = "a".repeat(155)
    assertEquals("$completePairPrefix😀", "$completePairPrefix😀tail".takeUtf16Safe(157))
  }
}

