private class InMemoryDeviceAuthStore : DeviceAuthTokenStore {
  private val tokens = mutableMapOf<String, DeviceAuthEntry>()

  override fun loadEntry(
    gatewayId: String,
    deviceId: String,
    role: String,
  ): DeviceAuthEntry? = tokens["${gatewayId.trim()}|${deviceId.trim()}|${role.trim()}"]

  override fun saveToken(
    gatewayId: String,
    deviceId: String,
    role: String,
    token: String,
    scopes: List<String>,
  ) {
    tokens["${gatewayId.trim()}|${deviceId.trim()}|${role.trim()}"] =
      DeviceAuthEntry(
        token = token.trim(),
        role = role.trim(),
        scopes = scopes,
        updatedAtMs = System.currentTimeMillis(),
      )
  }

  override fun clearToken(
    gatewayId: String,
    deviceId: String,
    role: String,
  ) {
    tokens.remove("${gatewayId.trim()}|${deviceId.trim()}|${role.trim()}")
  }
}

