        defaultTrust = defaultTrust,
      )

    val failure =
      runCatching {
        Socket().use { socket ->
          (config.trustManager as X509ExtendedTrustManager).checkServerTrusted(
            emptyArray(),
            "RSA",
            socket,
          )
        }
      }.exceptionOrNull()

    assertTrue(failure is java.security.cert.CertificateException)
    assertEquals(0, defaultTrust.serverSocketCalls)
    assertEquals(0, defaultTrust.serverTwoArgumentCalls)
  }

  @Test
  fun probeGatewayTlsFingerprint_reportsHandshakeTimeoutAfterTcpConnect() =
    runBlocking {
      TcpTestServer { socket ->
        socket.soTimeout = 1_000
        runCatching { socket.getInputStream().read(ByteArray(512)) }
        Thread.sleep(700)
      }.use { server ->
        val result =
          probeGatewayTlsFingerprint(
            host = LOOPBACK_HOST,
            port = server.port,
            connectTimeoutMs = 250,
            handshakeTimeoutMs = 250,
          )

        assertEquals(GatewayTlsProbeFailure.TLS_HANDSHAKE_TIMEOUT, result.failure)
      }
    }

  @Test
  fun probeGatewayTlsFingerprint_reportsTlsUnavailableForPlainHttpEndpoint() =
    runBlocking {
      TcpTestServer { socket ->
        socket.soTimeout = 1_000
        runCatching { socket.getInputStream().read(ByteArray(512)) }
        socket.getOutputStream().write("HTTP/1.1 400 Bad Request\r\nContent-Length: 0\r\n\r\n".toByteArray())
        socket.getOutputStream().flush()
      }.use { server ->
        val result =
          probeGatewayTlsFingerprint(
            host = LOOPBACK_HOST,
            port = server.port,
            connectTimeoutMs = 250,
            handshakeTimeoutMs = 1_000,
          )

        assertEquals(GatewayTlsProbeFailure.TLS_UNAVAILABLE, result.failure)
      }
    }

  @Test
  fun probeGatewayTlsFingerprint_reportsTlsUnavailableForConnectedReset() =
    runBlocking {
      TcpTestServer { socket ->
        socket.close()
      }.use { server ->
        val result =
          probeGatewayTlsFingerprint(
            host = LOOPBACK_HOST,
            port = server.port,
            connectTimeoutMs = 250,
            handshakeTimeoutMs = 1_000,
          )

        assertEquals(GatewayTlsProbeFailure.TLS_UNAVAILABLE, result.failure)
      }
    }

  @Test
  fun probeGatewayTlsFingerprint_reportsUnreachableWhenTcpConnectFails() =
    runBlocking {
      val result =
        probeGatewayTlsFingerprint(
          host = LOOPBACK_HOST,
          port = unusedLoopbackPort(),
          connectTimeoutMs = 250,
          handshakeTimeoutMs = 250,
        )

      assertEquals(GatewayTlsProbeFailure.ENDPOINT_UNREACHABLE, result.failure)
    }

  private class TcpTestServer(
    private val handler: (Socket) -> Unit,
  ) : AutoCloseable {
    private val serverSocket = ServerSocket(0, 50, LOOPBACK_ADDRESS)
    private var acceptedSocket: Socket? = null
    private val worker =
      thread(start = true, isDaemon = true, name = "openclaw-tls-probe-test-server") {
        try {
          serverSocket.accept().use { socket ->
            acceptedSocket = socket
            handler(socket)
          }
        } catch (_: SocketException) {
          // Closing the server during test cleanup interrupts accept/read.
        }
      }

    val port: Int = serverSocket.localPort

    override fun close() {
      runCatching { acceptedSocket?.close() }
      runCatching { serverSocket.close() }
      worker.join(1_000)
    }
  }

  private class RecordingExtendedTrustManager : X509ExtendedTrustManager() {
    var serverTwoArgumentCalls = 0
    var serverSocketCalls = 0
    var serverEngineCalls = 0

    override fun checkClientTrusted(
      chain: Array<X509Certificate>,
      authType: String,
    ) = Unit

    override fun checkClientTrusted(
      chain: Array<X509Certificate>,
      authType: String,
      socket: Socket,
    ) = Unit

    override fun checkClientTrusted(
      chain: Array<X509Certificate>,
      authType: String,
      engine: SSLEngine,
    ) = Unit

    override fun checkServerTrusted(
      chain: Array<X509Certificate>,
      authType: String,
    ) {
      serverTwoArgumentCalls += 1
    }

    override fun checkServerTrusted(
      chain: Array<X509Certificate>,
      authType: String,
      socket: Socket,
    ) {
      serverSocketCalls += 1
    }

    override fun checkServerTrusted(
      chain: Array<X509Certificate>,
      authType: String,
      engine: SSLEngine,
    ) {
      serverEngineCalls += 1
    }

    override fun getAcceptedIssuers(): Array<X509Certificate> = emptyArray()
  }

  private companion object {
    const val LOOPBACK_HOST = "127.0.0.1"
    val LOOPBACK_ADDRESS: InetAddress = InetAddress.getByName(LOOPBACK_HOST)

    fun unusedLoopbackPort(): Int =
      ServerSocket(0, 50, LOOPBACK_ADDRESS).use { server ->
        server.localPort
      }
  }
}

package ai.openclaw.app.gateway

import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test

class InvokeErrorParserTest {
  @Test
  fun parseInvokeErrorMessage_parsesUppercaseCodePrefix() {
    val parsed = parseInvokeErrorMessage("CAMERA_PERMISSION_REQUIRED: grant Camera permission")
    assertEquals("CAMERA_PERMISSION_REQUIRED", parsed.code)
    assertEquals("grant Camera permission", parsed.message)
    assertTrue(parsed.hadExplicitCode)
    assertEquals("CAMERA_PERMISSION_REQUIRED: grant Camera permission", parsed.prefixedMessage)
  }

  @Test
  fun parseInvokeErrorMessage_parsesNumericCodePrefix() {
    val parsed = parseInvokeErrorMessage("API2_UNAVAILABLE: service not reachable")
    assertEquals("API2_UNAVAILABLE", parsed.code)
    assertEquals("service not reachable", parsed.message)
    assertTrue(parsed.hadExplicitCode)
  }

  @Test
  fun parseInvokeErrorMessage_rejectsNonCanonicalCodePrefix() {
    listOf(
      "IllegalStateException: boom",
      "2FAST: boom",
      "_PRIVATE: boom",
      "CAMERA-PERMISSION: boom",
    ).forEach { raw ->
      val parsed = parseInvokeErrorMessage(raw)
      assertEquals("UNAVAILABLE", parsed.code)
      assertEquals(raw, parsed.message)
      assertFalse(parsed.hadExplicitCode)
    }
  }

  @Test
  fun parseInvokeErrorFromThrowable_usesFallbackWhenMessageMissing() {
    val parsed = parseInvokeErrorFromThrowable(IllegalStateException(), fallbackMessage = "fallback")
    assertEquals("UNAVAILABLE", parsed.code)
    assertEquals("fallback", parsed.message)
    assertFalse(parsed.hadExplicitCode)
  }
}

