      GatewayCronRunSummary(
        ts = 0,
        runId = "run-1",
        status = "ok",
        summary = "Complete",
        error = null,
        durationMs = 125,
        deliveryStatus = "not-delivered",
        sessionKey = null,
        model = "openai/gpt-5.6",
      )

    assertEquals(
