        onboardingMascotMood(
          step = OnboardingStep.SetupCode,
          setupScanErrorCode = OnboardingErrorCode.InvalidSetupQr,
        ),
    )
  }

  @Test
  fun onboardingBackDestinationsMatchTheVisibleFlow() {
