  @Test
  fun providerRowsIncludeConfiguredModelProvidersWithoutAuthRows() {
    val rows =
      providerRows(
        providers =
          listOf(
            GatewayModelProviderSummary(
              id = "openai",
              displayName = "OpenAI",
              status = "ok",
              profileCount = 1,
