/** Reader-owner animation proof; the app's separate code-reading test owns real nested dragging. */
@RunWith(RobolectricTestRunner::class)
@Config(sdk = [36], qualifiers = "w360dp-h800dp-420dpi", application = Application::class)
class ChatReaderScrollOwnershipLayoutTest {
  private val animationScale =
    object : MotionDurationScale {
      override val scaleFactor = 1f
    }

  @get:Rule
  val composeRule = createComposeRule(effectContext = animationScale)

  private lateinit var reader: ChatReaderScrollController
  private var observedScale: Float? = null

  @Test
  fun manualNavigationStopsAnAlreadyMovingAutomaticScroll() {
    verifyManualTakeover(replaceRunningTransition = false)
  }

  @Test
  fun manualNavigationStopsReplacementAfterTheOlderTransitionIsCancelled() {
    verifyManualTakeover(replaceRunningTransition = true)
  }

  private fun verifyManualTakeover(replaceRunningTransition: Boolean) {
    showReader()
    composeRule.waitForIdle()
    assertEquals("The actual effect context must allow timed animations", 1f, checkNotNull(observedScale), 0f)
    val initial = viewport()
    assertTrue("History must begin away from the latest row", initial.index > 0)
    assertFalse(initial.scrolling)

    val originalAutoAdvance = composeRule.mainClock.autoAdvance
    composeRule.mainClock.autoAdvance = false
    try {
      click("Jump to latest")
      val first = advanceUntilMoving(initial, "first automatic transition")

      if (replaceRunningTransition) {
        click("Append user turn")
        // Deliver the real timeline effect, then drain the older animation's cancellation.
        composeRule.mainClock.advanceTimeByFrame()
        drainCurrentWork()
        composeRule.onNodeWithText("User turns: 2").assertIsDisplayed()
        val replacementStart = viewport()
        assertTrue("The replacement must still be moving before manual takeover", replacementStart.scrolling)
        advanceUntilMoving(replacementStart, "replacement automatic transition")
      } else {
        assertTrue(first.scrolling)
      }

      // This visible fixture control uses the same provided navigation callback as
      // View all and Start/End of code; it does not reach into reader implementation state.
      click("Read here")
      drainCurrentWork()
      val stopped = viewport()
      composeRule.mainClock.advanceTimeBy(200)
      composeRule.waitForIdle()
      val afterFrames = viewport()

      // Cancellation must not poison the reader scope or prevent a later explicit jump.
      composeRule.mainClock.autoAdvance = true
      click("Jump to latest")
      composeRule.waitForIdle()
      assertEquals(ViewportPosition(0, 0), viewport().position)
      composeRule.onNodeWithText(if (replaceRunningTransition) "new user" else "assistant 59").assertIsDisplayed()
      assertEquals("Manual navigation must stop the automatic viewport movement", stopped.position, afterFrames.position)
      assertFalse("No automatic mutation may remain after manual takeover", afterFrames.scrolling)
    } finally {
      composeRule.mainClock.autoAdvance = originalAutoAdvance
      composeRule.waitForIdle()
    }
  }

  private fun advanceUntilMoving(
    before: Viewport,
    label: String,
  ): Viewport {
    composeRule.mainClock.advanceTimeUntil(timeoutMillis = 1_000) {
      reader.listState.isScrollInProgress &&
        ViewportPosition(reader.listState.firstVisibleItemIndex, reader.listState.firstVisibleItemScrollOffset) != before.position
    }
    composeRule.waitForIdle()
    val moving = viewport()
    assertTrue("$label must have observable animation frames, not an instant jump", moving.scrolling && moving.index > 0)
    assertTrue("$label must actually move", before.position != moving.position)
    println("READER_SCROLL phase=$label clock=${composeRule.mainClock.currentTime} before=${before.position} after=${moving.position} scale=$observedScale")
    return moving
  }

  private fun drainCurrentWork() {
    composeRule.mainClock.advanceTimeBy(0, ignoreFrameDuration = true)
    composeRule.waitForIdle()
  }

  private fun viewport(): Viewport =
    composeRule.runOnUiThread {
      Viewport(
        position = ViewportPosition(reader.listState.firstVisibleItemIndex, reader.listState.firstVisibleItemScrollOffset),
        scrolling = reader.listState.isScrollInProgress,
      )
    }

  private fun click(label: String) {
    composeRule
      .onNodeWithText(label)
      .assertIsDisplayed()
      .assertIsEnabled()
      .performClick()
  }

  private fun showReader() {
    val initialMessages = listOf(message("old user", "user", 1)) + (0 until 60).map { message("assistant $it", "assistant", it + 2) }
    composeRule.setContent {
      ClawDesignTheme {
        var messages by remember { mutableStateOf(initialMessages) }
        val timeline = remember(messages) { buildChatTimeline(messages, 0, emptyList(), null) }
        val current = rememberChatReaderScrollController("animation-owner", timeline, historyLoading = false)
        SideEffect { reader = current }
        LaunchedEffect(Unit) { observedScale = currentCoroutineContext()[MotionDurationScale]?.scaleFactor }
        CompositionLocalProvider(LocalChatReaderNavigation provides current.onManualNavigation) {
          val manualNavigation = LocalChatReaderNavigation.current
          Column(Modifier.size(360.dp, 700.dp).clipToBounds()) {
            Row(horizontalArrangement = Arrangement.SpaceBetween) {
              TextButton(onClick = current.jumpToLatest) { Text("Jump to latest") }
              TextButton(onClick = manualNavigation) { Text("Read here") }
            }
            TextButton(onClick = { messages = initialMessages + message("new user", "user", 1000) }) { Text("Append user turn") }
            Text("User turns: ${messages.count { it.role == "user" }}")
            LazyColumn(
              state = current.listState,
              reverseLayout = true,
              modifier = Modifier.fillMaxWidth().height(480.dp).nestedScroll(current.nestedScrollConnection),
            ) {
              items(timeline.items, key = ::chatTimelineItemKey) { item ->
                val message = (item as ChatTimelineItem.Message).message
                Box(Modifier.fillMaxWidth().height(64.dp)) {
                  Text(
                    message.content
                      .single()
                      .text
                      .orEmpty(),
                  )
                }
              }
            }
          }
        }
      }
    }
  }

  private fun message(
    text: String,
    role: String,
    timestamp: Int,
  ) = ChatMessage(
    id = text,
    role = role,
    content = listOf(ChatMessageContent(type = "text", text = text)),
    timestampMs = timestamp.toLong(),
  )

  private data class ViewportPosition(
    val index: Int,
    val offset: Int,
  )

  private data class Viewport(
    val position: ViewportPosition,
    val scrolling: Boolean,
  ) {
    val index: Int get() = position.index
  }
}

package ai.openclaw.app.ui.chat

import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotEquals
import org.junit.Assert.assertNull
import org.junit.Test

class ChatRichBlockCoordinatorTest {
  @Test
  fun queuePreservesOrderAndDeduplicatesMatchingJobs() {
    val harness = RenderHarness()
    val results = mutableListOf<String>()
    val first = request("first")
    val second = request("second")

    harness.coordinator.render(first) { result -> results.add("a:${result.value()}") }
    harness.coordinator.render(first) { result -> results.add("b:${result.value()}") }
    harness.coordinator.render(second) { result -> results.add("c:${result.value()}") }

    assertEquals(listOf(first), harness.backend.requests)
    harness.backend.complete(ChatRichBlockResult.Success("one"))
    assertEquals(listOf(first, second), harness.backend.requests)
    assertEquals(listOf("a:one", "b:one"), results)
    harness.backend.complete(ChatRichBlockResult.Success("two"))
    assertEquals(listOf("a:one", "b:one", "c:two"), results)
  }

  @Test
  fun cacheKeyBucketsWidthAndIncludesDarkMode() {
    val lightA = request("x", widthPx = 321, darkMode = false)
    val lightB = request("x", widthPx = 350, darkMode = false)
    val dark = request("x", widthPx = 321, darkMode = true)

    assertEquals(lightA.key, lightB.key)
    assertNotEquals(lightA.key, dark.key)
  }

  @Test
  fun presentationChangeWithSameKeyRendersAgain() {
    val harness = RenderHarness()
    val first = request("x")
    val recolored = first.copy(textColor = 0xffffffff.toInt())

    harness.coordinator.render(first) {}
    harness.backend.complete(ChatRichBlockResult.Success("first"))
    harness.coordinator.render(recolored) {}

    assertEquals(first.key, recolored.key)
    assertEquals(listOf(first, recolored), harness.backend.requests)
  }

  @Test
  fun negativeResultsAreCachedWithoutAnotherBackendJob() {
    val harness = RenderHarness()
    val request = request("bad")
    val results = mutableListOf<ChatRichBlockResult<String>>()

    harness.coordinator.render(request, results::add)
    harness.backend.complete(ChatRichBlockResult.Failure)
    harness.coordinator.render(request, results::add)

    assertEquals(1, harness.backend.requests.size)
    assertEquals(listOf(ChatRichBlockResult.Failure, ChatRichBlockResult.Failure), results)
  }

  @Test
  fun transientFailuresCanRetryTheSameKey() {
    val harness = RenderHarness()
    val request = request("retry")

    harness.coordinator.render(request) {}
    harness.backend.complete(ChatRichBlockResult.TransientFailure)
    harness.coordinator.render(request) {}

    assertEquals(listOf(request, request), harness.backend.requests)
  }

  @Test
  fun cancelDropsQueuedJobWithoutInterruptingActiveCacheWarmup() {
    val harness = RenderHarness()
    val first = request("first")
    val canceled = request("canceled")
    val last = request("last")

    harness.coordinator.render(first) {}
    harness.coordinator.render(canceled) {}.cancel()
    harness.coordinator.render(last) {}
    harness.backend.complete(ChatRichBlockResult.Success("one"))

    assertEquals(listOf(first, last), harness.backend.requests)
  }

  @Test
  fun timeoutFailsCurrentJobAndAdvancesQueue() {
    val harness = RenderHarness()
    val results = mutableListOf<ChatRichBlockResult<String>>()
    val first = request("first")
    val second = request("second")

    harness.coordinator.render(first, results::add)
    harness.coordinator.render(second, results::add)
    harness.scheduler.fire()

    assertEquals(listOf(ChatRichBlockResult.TransientFailure), results)
    assertEquals(listOf(first, second), harness.backend.requests)
    assertEquals(listOf("render:first", "reset", "render:second"), harness.backend.events)
  }

  @Test
  fun staleCompletionAfterTimeoutCannotCompleteRetry() {
    val harness = RenderHarness()
    val firstResults = mutableListOf<ChatRichBlockResult<String>>()
    val retryResults = mutableListOf<ChatRichBlockResult<String>>()
    val request = request("retry")

    harness.coordinator.render(request, firstResults::add)
    val staleCompletion = harness.backend.completions.removeAt(0)
    harness.scheduler.fire()
    harness.coordinator.render(request, retryResults::add)
    staleCompletion(ChatRichBlockResult.Success("stale"))

    assertEquals(listOf(ChatRichBlockResult.TransientFailure), firstResults)
    assertEquals(emptyList<ChatRichBlockResult<String>>(), retryResults)
    harness.backend.complete(ChatRichBlockResult.Success("fresh"))
    assertEquals(listOf(ChatRichBlockResult.Success("fresh")), retryResults)
  }

  @Test
  fun parsesStructuredRenderCompletionMessages() {
    assertEquals(
      ChatRichBlockRenderMessage(
        id = "7",
        widthCssPx = 12.5,
        heightCssPx = 8.0,
        success = true,
        svg = null,
      ),
      parseChatRichBlockRenderMessage(
        """{"id":"7","widthCssPx":12.5,"heightCssPx":8,"success":true}""",
        ChatRichBlockKind.Math,
      ),
    )
    assertNull(parseChatRichBlockRenderMessage("""{"id":"7"}""", ChatRichBlockKind.Math))
  }

  @Test
  fun diagramCompletionRequiresBoundedSvgButErrorsDoNotRequireDimensions() {
    val valid = """{"id":"8","success":true,"widthCssPx":240,"heightCssPx":100,"svg":"<svg/>"}"""
    assertEquals("<svg/>", parseChatRichBlockRenderMessage(valid, ChatRichBlockKind.Mermaid)?.svg)
    val withoutSvg = """{"id":"8","success":true,"widthCssPx":240,"heightCssPx":100}"""
    assertNull(parseChatRichBlockRenderMessage(withoutSvg, ChatRichBlockKind.Mermaid))
    assertNull(parseChatRichBlockRenderMessage(valid.replace("<svg/>", "x".repeat(1_000_001)), ChatRichBlockKind.Mermaid))
    assertEquals(
      false,
      parseChatRichBlockRenderMessage("""{"id":"8","success":false,"error":"Invalid diagram"}""", ChatRichBlockKind.Mermaid)?.success,
    )
    assertEquals(
      true,
      parseChatRichBlockRenderMessage("""{"id":"8","success":false,"error":"Renderer unavailable","retryable":true}""", ChatRichBlockKind.Mermaid)?.retryable,
    )
    assertEquals(
      false,
      parseChatRichBlockRenderMessage("""{"id":"8","success":false,"error":"Invalid diagram","retryable":false}""", ChatRichBlockKind.Mermaid)?.retryable,
    )
    assertEquals(
      false,
      parseChatRichBlockRenderMessage("""{"id":"8","success":false}""", ChatRichBlockKind.Math)?.retryable,
    )
  }

  @Test
  fun visibleMathRequestsDrainWithoutUserRetry() {
    val harness = RenderHarness()
    val requests = (0 until 40).map { request("x_{$it}^2") }
    val outcomes = mutableListOf<ChatRichBlockResult<String>>()
    requests.forEach { harness.coordinator.render(it, outcomes::add) }

    assertEquals(emptyList<ChatRichBlockResult<String>>(), outcomes)
    requests.forEach { harness.backend.complete(ChatRichBlockResult.Success(it.source)) }

    assertEquals(requests, harness.backend.requests)
    assertEquals(requests.map { ChatRichBlockResult.Success(it.source) }, outcomes)
  }

  @Test
  fun mathRequestsDrainAfterSynchronousRendererLoss() {
    val harness = RenderHarness()
    val requests = (0 until 5_000).map { request("x_{$it}") }
    val outcomes = mutableListOf<ChatRichBlockResult<String>>()
    requests.forEach { harness.coordinator.render(it, outcomes::add) }

    harness.backend.synchronousResult = ChatRichBlockResult.TransientFailure
    harness.backend.complete(ChatRichBlockResult.TransientFailure)

    assertEquals(requests, harness.backend.requests)
    assertEquals(requests.map { ChatRichBlockResult.TransientFailure }, outcomes)
  }

  @Test
  fun cancelingQueuedWorkFreesCapacityWithoutDroppingAdmittedJobs() {
    val harness = RenderHarness()
    val outcomes = mutableListOf<ChatRichBlockResult<String>>()
    harness.coordinator.render(diagramRequest("active"), outcomes::add)
    val subscriptions = (0 until 100).map { harness.coordinator.render(diagramRequest("queued-$it"), outcomes::add) }
    val rejected = outcomes.size
    org.junit.Assert.assertTrue(rejected > 0)
    org.junit.Assert.assertTrue(outcomes.all { it == ChatRichBlockResult.TransientFailure })
    subscriptions.first().cancel()
    harness.coordinator.render(diagramRequest("replacement"), outcomes::add)
    assertEquals(rejected, outcomes.size)
    harness.backend.complete(ChatRichBlockResult.Success("active"))
    assertEquals(
      "queued-1",
      harness.backend.requests
        .last()
        .source,
    )
  }

  @Test
  fun bitmapDimensionsRejectNonFiniteNonPositiveAndOversizedValues() {
    assertEquals(25, bitmapDimension(cssPixels = 12.5, density = 2f))
    assertNull(bitmapDimension(cssPixels = Double.NaN, density = 1f))
    assertNull(bitmapDimension(cssPixels = Double.POSITIVE_INFINITY, density = 1f))
    assertNull(bitmapDimension(cssPixels = 0.0, density = 1f))
    assertNull(bitmapDimension(cssPixels = 1.0, density = Float.NaN))
    assertNull(bitmapDimension(cssPixels = 8193.0, density = 1f))
    assertNull(bitmapDimension(cssPixels = 4097.0, density = 2f))
  }

  private class RenderHarness {
    val backend = FakeBackend()
    val cache = FakeCache()
    val scheduler = FakeScheduler()
    val coordinator = ChatRichBlockCoordinator(backend, cache, scheduler)
  }

  private class FakeBackend : ChatRichBlockBackend<String> {
    val requests = mutableListOf<ChatRichBlockRequest>()
    val completions = mutableListOf<(ChatRichBlockResult<String>) -> Unit>()
    val events = mutableListOf<String>()
    var synchronousResult: ChatRichBlockResult<String>? = null

    override fun reset() {
      events += "reset"
    }

    override fun render(
      request: ChatRichBlockRequest,
      completion: (ChatRichBlockResult<String>) -> Unit,
    ) {
      requests.add(request)
      events += "render:${request.source}"
      val immediate = synchronousResult
      if (immediate == null) completions.add(completion) else completion(immediate)
    }

    fun complete(result: ChatRichBlockResult<String>) {
      completions.removeAt(0).invoke(result)
    }
  }

  private class FakeCache : ChatRichBlockCache<String> {
    private val entries = mutableMapOf<ChatRichBlockRequest, ChatRichBlockResult<String>>()

    override fun get(request: ChatRichBlockRequest): ChatRichBlockResult<String>? = entries[request]

    override fun put(
      request: ChatRichBlockRequest,
      result: ChatRichBlockResult<String>,
    ) {
      if (result != ChatRichBlockResult.TransientFailure) entries[request] = result
    }
  }

  private class FakeScheduler : ChatRenderTimeoutScheduler {
    private var action: (() -> Unit)? = null

    override fun schedule(
      delayMs: Long,
      action: () -> Unit,
    ): ChatRenderCancellation {
      this.action = action
      return ChatRenderCancellation { if (this.action === action) this.action = null }
    }

    fun fire() {
      val pending = action
      action = null
      checkNotNull(pending).invoke()
    }
  }

  private fun ChatRichBlockResult<String>.value(): String =
    when (this) {
      is ChatRichBlockResult.Success -> value
      ChatRichBlockResult.Failure -> "failure"
      ChatRichBlockResult.TransientFailure -> "transient failure"
    }

  private fun request(
    latex: String,
    widthPx: Int = 321,
    darkMode: Boolean = false,
  ): ChatMathRenderRequest =
    ChatMathRenderRequest.create(
      latex = latex,
      widthPx = widthPx,
      darkMode = darkMode,
      textColor = 0xff000000.toInt(),
      fontSizePx = 16f,
      density = 1f,
    )

  private fun diagramRequest(source: String): ChatMermaidRequest =
    ChatMermaidRequest(
      source = source,
      widthPx = 320,
      density = 1f,
      theme = ChatMermaidTheme("#fff", "#000", "#666", "#ccc", "#f00", false),
    )
}

package ai.openclaw.app.ui.chat

import android.view.ViewGroup
import android.webkit.WebView
import androidx.activity.ComponentActivity
import androidx.webkit.WebViewCompat
import androidx.webkit.WebViewFeature
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotSame
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test
import org.junit.runner.RunWith
import org.robolectric.Robolectric
import org.robolectric.RobolectricTestRunner
import org.robolectric.Shadows.shadowOf
import org.robolectric.annotation.Config
import org.robolectric.annotation.Implementation
import org.robolectric.annotation.Implements

@RunWith(RobolectricTestRunner::class)
@Config(
  sdk = [36],
  instrumentedPackages = ["androidx.webkit"],
  shadows = [RichBlockWebViewFeatureShadow::class, RichBlockWebViewCompatShadow::class],
)
class ChatRichBlockRendererLifecycleTest {
  @Test
  fun destroyingMathHostRetiresDocumentBeforeReentrantRender() {
    assertHostDestruction(ChatRichBlockKind.Math)
  }

  @Test
  fun destroyingMermaidHostRetiresDocumentBeforeReentrantRender() {
    assertHostDestruction(ChatRichBlockKind.Mermaid)
  }

  private fun assertHostDestruction(kind: ChatRichBlockKind) {
    val oldActivity = Robolectric.buildActivity(ComponentActivity::class.java).setup()
    val replacementActivity = Robolectric.buildActivity(ComponentActivity::class.java).setup()
    lateinit var retired: WebView
    var destroyedBeforeCompletion = false
    var outcome: ChatRichBlockResult<ChatRichBlockImage>? = null
    var replacementSubscription: ChatRenderCancellation? = null
    ChatRichBlockRenderer.render(oldActivity.get(), request(kind, "old")) { result ->
      outcome = result
      destroyedBeforeCompletion = shadowOf(retired).wasDestroyCalled()
      replacementSubscription = ChatRichBlockRenderer.render(replacementActivity.get(), request(kind, "fresh")) {}
    }
    retired = findRenderer(oldActivity.get().window.decorView as ViewGroup)
    val retiredClient = retired.webViewClient
    val shellUrl = "$CHAT_RENDER_ORIGIN/assets/${kind.assetDirectory}/index.html"
    retiredClient.onPageFinished(retired, shellUrl)
    assertTrue(shadowOf(retired).lastEvaluatedJavascript.contains("old"))

    oldActivity.pause().stop().destroy()
    try {
      assertEquals(ChatRichBlockResult.TransientFailure, outcome)
      assertTrue("The retired document must lose authority before a completion can reenter render", destroyedBeforeCompletion)
      assertNull(retired.parent)
      val replacement = findRenderer(replacementActivity.get().window.decorView as ViewGroup)
      assertNotSame(retired, replacement)
      assertNull(shadowOf(replacement).lastEvaluatedJavascript)

      retiredClient.onPageFinished(retired, shellUrl)
      assertNull("A late load from the destroyed document cannot ready its replacement", shadowOf(replacement).lastEvaluatedJavascript)
      replacement.webViewClient.onPageFinished(replacement, shellUrl)
      assertTrue(shadowOf(replacement).lastEvaluatedJavascript.contains("fresh"))
    } finally {
      replacementSubscription?.cancel()
      replacementActivity.pause().stop().destroy()
    }
  }

  private fun findRenderer(host: ViewGroup): WebView = (0 until host.childCount).map(host::getChildAt).filterIsInstance<WebView>().single()

  private fun request(
    kind: ChatRichBlockKind,
    source: String,
  ): ChatRichBlockRequest =
    when (kind) {
      ChatRichBlockKind.Math ->
        ChatMathRenderRequest.create(source, widthPx = 320, darkMode = false, textColor = 0xff000000.toInt(), fontSizePx = 16f, density = 1f)
      ChatRichBlockKind.Mermaid ->
        ChatMermaidRequest(
          "flowchart LR\nA[$source] --> B[End]",
          widthPx = 320,
          density = 1f,
          theme = ChatMermaidTheme("#ffffff", "#000000", "#666666", "#cccccc", "#ff0000", darkMode = false),
        )
    }
}

// Robolectric has no AndroidX renderer bridge; only this platform capability is
// substituted. Activity callbacks, WebView ownership, and queue completion are real.
@Implements(value = WebViewFeature::class, isInAndroidSdk = false)
class RichBlockWebViewFeatureShadow {
  companion object {
    @JvmStatic
    @Implementation
    fun isFeatureSupported(feature: String): Boolean = feature == WebViewFeature.WEB_MESSAGE_LISTENER
  }
}

@Implements(value = WebViewCompat::class, isInAndroidSdk = false)
class RichBlockWebViewCompatShadow {
  companion object {
    @JvmStatic
    @Implementation
    fun addWebMessageListener(
      view: WebView,
      name: String,
      origins: Set<String>,
      listener: WebViewCompat.WebMessageListener,
    ) = Unit

    @JvmStatic
    @Implementation
    fun removeWebMessageListener(
      view: WebView,
      name: String,
    ) = Unit
  }
}

