package ai.openclaw.app.ui.chat

import ai.openclaw.app.chat.ChatSessionEntry
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertNull
import org.junit.Test
import java.util.Locale

class ChatTurnRecapResolverTest {
  private val session = "agent:main:main"
  private val previousEndedAt = 900_000L
  private val runEndedAt = 1_000_000L

  private fun row(
    status: String,
    endedAt: Long? = null,
    runtimeMs: Long? = null,
    outputTokens: Long? = null,
  ): ChatSessionEntry =
    ChatSessionEntry(
      key = session,
      updatedAtMs = endedAt,
      status = status,
      endedAt = endedAt,
      runtimeMs = runtimeMs,
      outputTokens = outputTokens,
      hasRunMetadata = true,
    )

  private fun done(
    endedAt: Long,
    runtimeMs: Long? = 51_000L,
    outputTokens: Long? = null,
  ): ChatSessionEntry = row("done", endedAt, runtimeMs, outputTokens)

  @Test
  fun resolvesOnceAFreshTerminalStampLandsThenSticks() {
    val resolver = TurnRecapResolver()
    assertNull(resolver.resolve(session, true, done(previousEndedAt)))
    assertNull(resolver.resolve(session, false, done(previousEndedAt)))

    val terminal = done(runEndedAt, runtimeMs = 51_000L, outputTokens = 485L)
    val expected = TurnRecap(runtimeMs = 51_000L, outputTokens = 485L)
    assertEquals(expected, resolver.resolve(session, false, terminal))
    assertEquals(expected, resolver.resolve(session, false, terminal))
  }

  @Test
  fun rejectsPreviousTurnAndRegressedStamps() {
    val resolver = TurnRecapResolver()
    resolver.resolve(session, true, done(previousEndedAt))

    assertNull(resolver.resolve(session, false, done(previousEndedAt)))
    assertNull(resolver.resolve(session, false, done(previousEndedAt - 5_000L)))
  }

  @Test
  fun expiresAnUnresolvedWatchInsteadOfMatchingALaterRun() {
    var nowMs = 1_000_000L
    val resolver = TurnRecapResolver { nowMs }
    resolver.resolve(session, true, done(previousEndedAt))
    assertNull(resolver.resolve(session, false, done(previousEndedAt)))

    nowMs += 31_000L
    assertNull(resolver.resolve(session, false, done(previousEndedAt)))
    assertNull(resolver.resolve(session, false, done(runEndedAt)))
  }

  @Test
  fun freshDoneWithoutRuntimeConsumesTheWatch() {
    val resolver = TurnRecapResolver()
    resolver.resolve(session, true, done(previousEndedAt))

    assertNull(resolver.resolve(session, false, done(runEndedAt, runtimeMs = null)))
    assertNull(resolver.resolve(session, false, done(runEndedAt + 1_000L)))
  }

  @Test
  fun clearedRunStartBaselineIsStaleFree() {
    val resolver = TurnRecapResolver()
    assertNull(resolver.resolve(session, true, row(status = "running")))
    assertEquals(
      TurnRecap(runtimeMs = 2_000L, outputTokens = null),
      resolver.resolve(session, false, done(runEndedAt, runtimeMs = 2_000L)),
    )
  }

  @Test
  fun neverResolvesWithoutWatchingAnIndicator() {
    assertNull(TurnRecapResolver().resolve(session, false, done(runEndedAt)))
  }

  @Test
  fun consumesAWatchWhoseBaselineRowWasNeverObserved() {
    val resolver = TurnRecapResolver()
    assertNull(resolver.resolve(session, true, null))
    assertNull(resolver.resolve(session, false, done(previousEndedAt)))
    assertNull(resolver.resolve(session, false, done(runEndedAt)))
  }

  @Test
  fun adoptsTheFirstRowObservedMidWatchAsBaseline() {
    val resolver = TurnRecapResolver()
    assertNull(resolver.resolve(session, true, null))
    assertNull(resolver.resolve(session, true, done(previousEndedAt)))
    assertNull(resolver.resolve(session, false, done(previousEndedAt)))
    assertEquals(
      TurnRecap(runtimeMs = 6_000L, outputTokens = null),
      resolver.resolve(session, false, done(runEndedAt, runtimeMs = 6_000L)),
    )
  }

  @Test
  fun forfeitsWhenATerminalStampChangesMidWatch() {
    val resolver = TurnRecapResolver()
    assertNull(resolver.resolve(session, true, row(status = "running")))
    assertNull(resolver.resolve(session, true, done(previousEndedAt)))
    assertNull(resolver.resolve(session, false, done(previousEndedAt)))
    assertNull(resolver.resolve(session, false, done(runEndedAt, runtimeMs = 4_000L)))
  }

  @Test
  fun forfeitsAFailedTurnWhoseTerminalRacedTheIndicator() {
    val resolver = TurnRecapResolver()
    resolver.resolve(session, true, row(status = "running"))
    resolver.resolve(session, true, row(status = "failed", endedAt = runEndedAt))

    assertNull(resolver.resolve(session, false, row(status = "failed", endedAt = runEndedAt)))
    assertNull(resolver.resolve(session, false, done(runEndedAt + 60_000L)))
  }

  @Test
  fun freezesTheFirstRecapAgainstLaterUnwatchedTerminals() {
    val resolver = TurnRecapResolver()
    resolver.resolve(session, true, done(previousEndedAt))
    val settled = resolver.resolve(session, false, done(runEndedAt, runtimeMs = 51_000L, outputTokens = 485L))

    assertNotNull(settled)
    assertEquals(settled, resolver.resolve(session, false, done(runEndedAt + 90_000L, runtimeMs = 7_000L, outputTokens = 42L)))
  }

  @Test
  fun settledRecapSticksOnlyWhileItsTranscriptAnchorIsNewest() {
    val resolver = TurnRecapResolver()
    resolver.resolve(session, true, done(previousEndedAt), transcript("user-1"))
    val terminal = done(runEndedAt, runtimeMs = 51_000L, outputTokens = 485L)
    val expected = TurnRecap(runtimeMs = 51_000L, outputTokens = 485L)

    assertNull(
      resolver.resolve(session, false, terminal, transcript("assistant-tool")),
    )
    assertEquals(
      expected,
      resolver.resolve(session, false, terminal, transcript("assistant-1", completedEndedAt = runEndedAt)),
    )
    assertEquals(
      expected,
      resolver.resolve(session, false, terminal, transcript("assistant-1", completedEndedAt = runEndedAt)),
    )
    assertNull(
      resolver.resolve(
        session,
        false,
        terminal,
        transcript("assistant-2", completedEndedAt = runEndedAt + 1_000L),
      ),
    )
  }

  @Test
  fun emptyTranscriptWaitsForTheCompletedItemBeforeSettling() {
    val resolver = TurnRecapResolver()
    resolver.resolve(session, true, done(previousEndedAt), transcript(null))
    val terminal = done(runEndedAt, runtimeMs = 2_000L)

    assertNull(resolver.resolve(session, false, terminal, transcript(null)))
    assertEquals(
      TurnRecap(runtimeMs = 2_000L, outputTokens = null),
      resolver.resolve(session, false, terminal, transcript("assistant-1", completedEndedAt = runEndedAt)),
    )
  }

  @Test
  fun newerContentAlreadyPresentWhenHistoryCompletesDropsTheRecap() {
    val resolver = TurnRecapResolver()
    resolver.resolve(session, true, done(previousEndedAt), transcript("user-1"))
    val terminal = done(runEndedAt, runtimeMs = 2_000L)

    assertNull(
      resolver.resolve(
        session,
        false,
        terminal,
        transcript(
          newestItemId = "user-2",
          completedEndedAt = runEndedAt,
          completedNewestItemId = "assistant-1",
        ),
      ),
    )
  }

  @Test
  fun changedTerminalWhileWaitingForHistoryDestroysAttribution() {
    val resolver = TurnRecapResolver()
    resolver.resolve(session, true, done(previousEndedAt), transcript("user-1"))
    assertNull(
      resolver.resolve(session, false, done(runEndedAt), transcript("user-1")),
    )

    assertNull(
      resolver.resolve(
        session,
        false,
        done(runEndedAt + 1_000L, runtimeMs = 9_000L),
        transcript("assistant-2", completedEndedAt = runEndedAt + 1_000L),
      ),
    )
  }

  @Test
  fun terminalWaitingForHistoryStillExpires() {
    var nowMs = 1_000_000L
    val resolver = TurnRecapResolver { nowMs }
    resolver.resolve(session, true, done(previousEndedAt), transcript("user-1"))
    assertNull(
      resolver.resolve(session, false, done(runEndedAt), transcript("user-1")),
    )

    nowMs += TURN_RECAP_SETTLE_WINDOW_MS + 1L
    assertNull(
      resolver.resolve(session, false, done(runEndedAt), transcript("assistant-1", completedEndedAt = runEndedAt)),
    )
  }

  @Test
  fun hidesTheRecapAsSoonAsTheNextIndicatorAppears() {
    val resolver = TurnRecapResolver()
    resolver.resolve(session, true, done(previousEndedAt))
    assertNotNull(resolver.resolve(session, false, done(runEndedAt)))

    assertNull(resolver.resolve(session, true, done(runEndedAt)))
    assertNull(resolver.resolve(session, false, done(runEndedAt)))
  }

  @Test
  fun ignoresAStaleFailedRowThenResolvesAFreshDone() {
    val resolver = TurnRecapResolver()
    resolver.resolve(session, true, row(status = "failed", endedAt = previousEndedAt))

    assertNull(resolver.resolve(session, false, row(status = "failed", endedAt = previousEndedAt)))
    assertEquals(
      TurnRecap(runtimeMs = 3_000L, outputTokens = null),
      resolver.resolve(session, false, done(runEndedAt, runtimeMs = 3_000L)),
    )
  }

  @Test
  fun freshFailedRowConsumesTheWatch() {
    val resolver = TurnRecapResolver()
    resolver.resolve(session, true, done(previousEndedAt))

    assertNull(resolver.resolve(session, false, row(status = "failed", endedAt = runEndedAt)))
    assertNull(resolver.resolve(session, false, done(runEndedAt + 1_000L)))
  }

  @Test
  fun leavingTheSessionAbandonsUnsettledButKeepsSettled() {
    val resolver = TurnRecapResolver()
    resolver.resolve(session, true, done(previousEndedAt))
    assertNull(resolver.resolve(session, false, done(previousEndedAt)))
    resolver.abandonActiveWatch(session)
    assertNull(resolver.resolve(session, false, done(runEndedAt)))

    resolver.resolve(session, true, done(previousEndedAt))
    val settled = resolver.resolve(session, false, done(runEndedAt))
    resolver.abandonActiveWatch(session)
    assertEquals(settled, resolver.resolve(session, false, done(runEndedAt + 1_000L)))
  }

  @Test
  fun everyNonDoneTerminalConsumesQuietly() {
    listOf("failed", "killed", "timeout").forEach { status ->
      val resolver = TurnRecapResolver()
      resolver.resolve(session, true, done(previousEndedAt))
      assertNull(resolver.resolve(session, false, row(status = status, endedAt = runEndedAt)))
      assertNull(resolver.resolve(session, false, done(runEndedAt + 1_000L)))
    }
  }

  @Test
  fun formatsZeroOneAndCompactTokenCounts() {
    assertEquals(TurnRecapTokenFormat(singular = false, count = "0"), turnRecapTokenFormat(0L))
    assertEquals(TurnRecapTokenFormat(singular = true, count = "1"), turnRecapTokenFormat(1L))
    assertEquals("1.2k", formatCompactTokenCount(1_234L, Locale.US))
    assertEquals("1.3k", formatCompactTokenCount(1_250L, Locale.US))
    assertEquals("1,2k", formatCompactTokenCount(1_234L, Locale.GERMANY))
    assertEquals("١M", formatCompactTokenCount(999_999L, Locale.forLanguageTag("ar")))
  }

  private fun transcript(
    newestItemId: String?,
    completedEndedAt: Long? = null,
    transcriptSessionKey: String? = session,
    completedNewestItemId: String? = newestItemId.takeIf { completedEndedAt != null },
  ): TurnRecapTranscriptState =
    TurnRecapTranscriptState(
      sessionKey = transcriptSessionKey,
      newestItemId = newestItemId,
      completedEndedAt = completedEndedAt,
      completedNewestItemId = completedNewestItemId,
    )
}

package ai.openclaw.app.ui.chat

import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test

class ChatWidgetExportTest {
  @Test
  fun sanitizesWidgetTitleForPngFileName() {
    assertEquals("Quarterly report 2026.png", widgetExportFileName("  Quarterly/report:*2026?  "))
    assertEquals("Résumé 📈.png", widgetExportFileName("Résumé 📈"))
  }

  @Test
  fun fallsBackWhenWidgetTitleHasNoSafeCharacters() {
    assertEquals("widget.png", widgetExportFileName(null))
    assertEquals("widget.png", widgetExportFileName(" .. /:*? "))
  }

  @Test
  fun boundsWidgetTitleToCodePointAndUtf8ByteLimits() {
    val fileName = widgetExportFileName("📈".repeat(100))
    val stem = fileName.removeSuffix(".png")

    assertEquals(30, stem.codePointCount(0, stem.length))
    assertTrue(fileName.toByteArray(Charsets.UTF_8).size <= 255)
    assertTrue(!Character.isHighSurrogate(stem.last()))
    assertTrue(fileName.endsWith(".png"))
  }

  @Test
  fun keepsAsciiFileNameBehaviorWithinTheUtf8Budget() {
    assertEquals("a".repeat(80) + ".png", widgetExportFileName("a".repeat(100)))
  }

  @Test
  fun requiresACompleteGlobalVisibleRectForPixelCopy() {
    assertTrue(
      canCaptureWithPixelCopy(
        hasGlobalVisibleRect = true,
        visibleWidth = 320,
        visibleHeight = 180,
        viewWidth = 320,
        viewHeight = 180,
      ),
    )
    assertTrue(
      !canCaptureWithPixelCopy(
        hasGlobalVisibleRect = true,
        visibleWidth = 319,
        visibleHeight = 180,
        viewWidth = 320,
        viewHeight = 180,
      ),
    )
    assertTrue(
      !canCaptureWithPixelCopy(
        hasGlobalVisibleRect = true,
        visibleWidth = 320,
        visibleHeight = 179,
        viewWidth = 320,
        viewHeight = 180,
      ),
    )
    assertTrue(
      !canCaptureWithPixelCopy(
        hasGlobalVisibleRect = false,
        visibleWidth = 320,
        visibleHeight = 180,
        viewWidth = 320,
        viewHeight = 180,
      ),
    )
  }

  @Test
  fun prunesOnlyExpiredExportsOlderThanTheNewestExport() {
    val nowMillis = 2 * 24 * 60 * 60 * 1000L
    val expiredMillis = nowMillis - 24 * 60 * 60 * 1000L - 1
    val newestMillis = nowMillis - 60 * 60 * 1000L

    assertTrue(shouldPruneWidgetExportDirectory(expiredMillis, newestMillis, nowMillis))
    assertTrue(!shouldPruneWidgetExportDirectory(newestMillis, newestMillis, nowMillis))
    assertTrue(!shouldPruneWidgetExportDirectory(expiredMillis, expiredMillis, nowMillis))
    assertTrue(!shouldPruneWidgetExportDirectory(nowMillis - 24 * 60 * 60 * 1000L, nowMillis, nowMillis))
  }
}

package ai.openclaw.app.ui.design

import ai.openclaw.app.GatewayAgentSummary
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Test

class AgentAvatarTest {
  @Test
  fun prefersResolvedAvatarUrl() {
    val agent = agent(avatar = dataUrl("image/png", "raw"), avatarUrl = dataUrl("image/jpeg", "resolved"))

    assertEquals(
      AgentAvatarSource.Data(mimeType = "image/jpeg", base64 = "resolved"),
      agentAvatarSource(agent),
    )
  }

  @Test
  fun fallsBackToRawAvatarOnlyWhenResolvedAvatarIsMissing() {
    val raw = AgentAvatarSource.Data(mimeType = "image/png", base64 = "raw")

    assertEquals(raw, agentAvatarSource(agent(avatar = dataUrl("image/png", "raw"))))
    assertEquals(raw, agentAvatarSource(agent(avatar = dataUrl("image/png", "raw"), avatarUrl = "  ")))
    assertNull(agentAvatarSource(agent(avatar = dataUrl("image/png", "raw"), avatarUrl = "not an image")))
  }

  @Test
  fun preservesRasterAndSvgMimeTypes() {
    assertEquals(
      AgentAvatarSource.Data(mimeType = "image/png", base64 = "body"),
      agentAvatarSource(agent(avatarUrl = "DATA:IMAGE/PNG;BASE64, body ")),
    )
    assertEquals(
      AgentAvatarSource.Data(mimeType = "image/svg+xml", base64 = "PHN2Zy8+"),
      agentAvatarSource(agent(avatarUrl = dataUrl("image/svg+xml", "PHN2Zy8+"))),
    )
  }

  @Test
  fun recognizesRemoteHttpSources() {
    assertEquals(
      AgentAvatarSource.Remote("https://example.com/avatar.png"),
      agentAvatarSource(agent(avatarUrl = "https://example.com/avatar.png")),
    )
    assertEquals(
      AgentAvatarSource.Remote("HTTP://example.com/avatar.svg"),
      agentAvatarSource(agent(avatarUrl = "HTTP://example.com/avatar.svg")),
    )
  }

  @Test
  fun rejectsMalformedOrUnsupportedAvatarValues() {
    assertNull(agentAvatarSource(agent(avatarUrl = "data:image/png,raw")))
    assertNull(agentAvatarSource(agent(avatarUrl = "data:text/plain;base64,dGV4dA==")))
    assertNull(agentAvatarSource(agent(avatarUrl = "data:image/png;base64,")))
    assertNull(agentAvatarSource(agent(avatar = "avatars/openclaw.png")))
    assertNull(agentAvatarSource(agent(avatar = "🦞")))
  }

  @Test
  fun rejectsMissingAvatarValues() {
    assertNull(agentAvatarSource(agent()))
    assertNull(agentAvatarSource(agent(avatar = " ", avatarUrl = "\n")))
  }

  private fun agent(
    avatar: String? = null,
    avatarUrl: String? = null,
  ) = GatewayAgentSummary(
    id = "main",
    name = "Main",
    emoji = null,
    avatar = avatar,
    avatarUrl = avatarUrl,
  )

  private fun dataUrl(
    mimeType: String,
    body: String,
  ): String = "data:$mimeType;base64,$body"
}

package ai.openclaw.app.ui.design

import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.compositeOver
import androidx.compose.ui.graphics.lerp
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotEquals
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertNull
import org.junit.Assert.assertSame
import org.junit.Test

class ClawColorsTest {
  @Test
  fun sessionColorsAdaptToThemeAndUnsetNamesHaveNoIndicator() {
    val light = clawColorsForTheme(dark = false, accentArgb = null)
    val dark = clawColorsForTheme(dark = true, accentArgb = null)
    for (name in listOf("red", "blue", "green", "yellow", "purple", "orange", "pink", "cyan")) {
      assertNotNull(light.sessionColor(name))
      assertNotNull(dark.sessionColor(name))
      assertNotEquals(light.sessionColor(name), dark.sessionColor(name))
    }
    for (name in listOf(null, "", "gray", "grey", "default", "reset", "none", "unknown")) {
      assertNull(light.sessionColor(name))
      assertNull(dark.sessionColor(name))
    }
  }

  @Test
  fun nullAccentPreservesHardcodedDarkAndLightPalettes() {
    val expectedAccents =
      mapOf(
        true to Triple(Color(0xFF6EA8FF), Color(0xFF1A2A44), Color(0xFF5B93E8)),
        false to Triple(Color(0xFF1B5ACB), Color(0xFFEAF2FF), Color(0xFF174CA9)),
      )

    for ((dark, expected) in expectedAccents) {
      val colors = clawColorsForTheme(dark = dark, accentArgb = null)

      assertEquals(expected.first, colors.accent)
      assertEquals(expected.second, colors.accentSoft)
      assertEquals(expected.third, colors.accentBorder)
      assertSame(colors, clawColorsForTheme(dark = dark, accentArgb = null))
    }
  }

  @Test
  fun gatewayAccentOverridesOnlyAccentTokensForBothPalettes() {
    val accent = Color(0xFFE84B35)

    for (dark in listOf(true, false)) {
      val base = clawColorsForTheme(dark = dark, accentArgb = null)
      val colors = clawColorsForTheme(dark = dark, accentArgb = 0xFFE84B35L)

      assertEquals(accent, colors.accent)
      assertEquals(accent.copy(alpha = if (dark) 0.25f else 0.08f).compositeOver(base.canvas), colors.accentSoft)
      assertEquals(lerp(accent, Color.Black, 0.12f), colors.accentBorder)
      assertNotEquals(accent, colors.accentSoft)
      assertNotEquals(accent, colors.accentBorder)
      assertNotEquals(base.accentSoft, colors.accentSoft)
      assertNotEquals(base.accentBorder, colors.accentBorder)
      assertEquals(
        base.copy(accent = colors.accent, accentSoft = colors.accentSoft, accentBorder = colors.accentBorder),
        colors,
      )
    }
  }
}

package ai.openclaw.app.ui.design

import org.junit.Assert.assertEquals
import org.junit.Test

class ClawComponentsTest {
  @Test
  fun emptySegmentedOptionsProduceNoRows() {
    assertEquals(emptyList<List<String>>(), segmentedControlRows(emptyList()))
  }

  @Test
  fun segmentedOptionsStayOnOneRowByDefault() {
    val options = listOf("One", "Two", "Three", "Four", "Five")

    assertEquals(listOf(options), segmentedControlRows(options))
  }

  @Test
  fun optedInSmallSegmentedOptionSetsStayOnOneRow() {
    val options = listOf("One", "Two", "Three", "Four")

    assertEquals(listOf(options), segmentedControlRows(options, maxOptionsPerRow = 4))
  }

  @Test
  fun fiveSegmentedOptionsSplitIntoBalancedRows() {
    val options = listOf("Pending", "Held", "Applied", "Rejected", "All")

    assertEquals(
      listOf(
        listOf("Pending", "Held", "Applied"),
        listOf("Rejected", "All"),
      ),
      segmentedControlRows(options, maxOptionsPerRow = 4),
    )
  }

  @Test
  fun largerSegmentedOptionSetsKeepRowsBalancedAndBounded() {
    val rows = segmentedControlRows((1..10).map(Int::toString), maxOptionsPerRow = 4)

    assertEquals(listOf(4, 3, 3), rows.map { it.size })
    assertEquals((1..10).map(Int::toString), rows.flatten())
  }
}

package ai.openclaw.app.ui.design

import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import kotlin.math.PI

/** Guards the exact constants ported from TalkWaveformView.swift. */
class TalkWaveformMathTest {
  @Test
  fun idlePowerIsStaticRegardlessOfTime() {
    assertEquals(0.05, TalkWaveformMath.power(TalkWaveformPhase.Idle, 0.0), 1e-9)
    assertEquals(0.05, TalkWaveformMath.power(TalkWaveformPhase.Idle, 42.5), 1e-9)
  }

  @Test
  fun thinkingBreathesInsideItsBand() {
    assertEquals(0.21, TalkWaveformMath.power(TalkWaveformPhase.Thinking, 0.0), 1e-9)
    var time = 0.0
    while (time < 10.0) {
      val power = TalkWaveformMath.power(TalkWaveformPhase.Thinking, time)
      assertTrue(power in 0.16..0.26)
      time += 0.1
    }
  }

  @Test
  fun listeningClampsLevelAndSpeechRaisesFloor() {
    assertEquals(0.30, TalkWaveformMath.power(TalkWaveformPhase.Listening(level = -0.5f, speechActive = false), 0.0), 1e-9)
    assertEquals(0.95, TalkWaveformMath.power(TalkWaveformPhase.Listening(level = 1.5f, speechActive = false), 0.0), 1e-9)
    assertEquals(0.56, TalkWaveformMath.power(TalkWaveformPhase.Listening(level = 0.4f, speechActive = false), 0.0), 1e-6)
    assertEquals(0.73, TalkWaveformMath.power(TalkWaveformPhase.Listening(level = 0.4f, speechActive = true), 0.0), 1e-6)
    assertEquals(1.0, TalkWaveformMath.power(TalkWaveformPhase.Listening(level = 2f, speechActive = true), 0.0), 1e-9)
  }

  @Test
  fun speakingClampsMeteredLevel() {
    assertEquals(0.25, TalkWaveformMath.power(TalkWaveformPhase.Speaking(level = -1f), 0.0), 1e-9)
    assertEquals(1.0, TalkWaveformMath.power(TalkWaveformPhase.Speaking(level = 2f), 0.0), 1e-9)
    assertEquals(0.70, TalkWaveformMath.power(TalkWaveformPhase.Speaking(level = 0.6f), 0.0), 1e-6)
  }

  @Test
  fun speakingWithoutEnvelopePulsesSynthetically() {
    val trough = TalkWaveformMath.power(TalkWaveformPhase.Speaking(level = null), 0.0)
    val peak = TalkWaveformMath.power(TalkWaveformPhase.Speaking(level = null), PI / 10.0)
    assertEquals(0.70 * 0.55, trough, 1e-9)
    assertEquals(0.70, peak, 1e-9)
    var time = 0.0
    while (time < 5.0) {
      val power = TalkWaveformMath.power(TalkWaveformPhase.Speaking(level = null), time)
      assertTrue(power in trough..peak)
      time += 0.05
    }
  }

  @Test
  fun lobesAreDeterministicWithFixedShapeConstants() {
    val lobes = TalkWaveformMath.lobes(time = 1.25, seed = 7.31)
    assertEquals(lobes, TalkWaveformMath.lobes(time = 1.25, seed = 7.31))
    assertEquals(3, lobes.size)
    assertEquals(0.62, lobes[0].k, 1e-9)
    assertEquals(0.73, lobes[1].k, 1e-9)
    assertEquals(0.84, lobes[2].k, 1e-9)
    for (lobe in lobes) {
      assertTrue(lobe.amplitude in 0.30..1.0)
      assertTrue(lobe.t in -2.8..2.8)
    }
  }

  @Test
  fun attenuatedSinePeaksAtFullAmplitudeAndStaysNonNegative() {
    // At kx − t = −π/2 the bell envelope is exactly 1 and |sin| is 1.
    assertEquals(3.0, TalkWaveformMath.attenuatedSine(x = -PI / 2, amplitude = 3.0, k = 1.0, t = 0.0), 1e-9)
    var x = -9.0
    while (x <= 9.0) {
      assertTrue(TalkWaveformMath.attenuatedSine(x = x, amplitude = 1.0, k = 0.73, t = 1.4) >= 0.0)
      x += 0.25
    }
  }
}

package ai.openclaw.app.voice

import org.junit.Assert.assertEquals
import org.junit.Test

class AudioLevelsTest {
  @Test
  fun silenceMetersToZero() {
    val silence = ByteArray(640)
    assertEquals(0.0, TalkAudioLevel.pcm16Rms(silence, silence.size), 0.0)
    assertEquals(0f, TalkAudioLevel.pcm16Level(silence, silence.size), 0f)
  }

  @Test
  fun fullScaleMetersToOne() {
    val frame = pcm16Frame(samples = 160, sample = Short.MAX_VALUE)
    assertEquals(1.0, TalkAudioLevel.pcm16Rms(frame, frame.size), 1e-6)
    assertEquals(1f, TalkAudioLevel.pcm16Level(frame, frame.size), 1e-6f)
  }

  @Test
  fun negativeFullScaleClampsToOne() {
    // abs(-32768) exceeds Short.MAX_VALUE by one; the level must stay in 0..1.
    val frame = pcm16Frame(samples = 160, sample = Short.MIN_VALUE)
    assertEquals(1f, TalkAudioLevel.pcm16Level(frame, frame.size), 0f)
  }

  @Test
  fun midScaleFollowsTheSharedDecibelCurve() {
    // Same 50 dB window as OpenClawKit's TalkAudioLevel: half amplitude is
    // -6.02 dBFS, so the normalized level is (50 - 6.02) / 50 = 0.8796.
    val frame = pcm16Frame(samples = 160, sample = (Short.MAX_VALUE / 2).toShort())
    assertEquals(0.5, TalkAudioLevel.pcm16Rms(frame, frame.size), 1e-3)
    assertEquals(0.8796f, TalkAudioLevel.pcm16Level(frame, frame.size), 1e-3f)
  }

  @Test
  fun quietSignalsStayVisibleOnTheDecibelCurve() {
    // -40 dBFS (1% amplitude) still reads at 0.2 instead of vanishing, which is
    // what makes the wave feel alive at conversational distance on iOS/macOS.
    assertEquals(0.2f, TalkAudioLevel.normalized(rms = 0.01), 1e-3f)
    assertEquals(0f, TalkAudioLevel.normalized(rms = 0.0), 0f)
    assertEquals(1f, TalkAudioLevel.normalized(rms = 1.0), 0f)
  }

  @Test
  fun trailingOddByteAndEmptyLengthAreIgnored() {
    val frame = pcm16Frame(samples = 2, sample = Short.MAX_VALUE) + byteArrayOf(0x7F)
    assertEquals(1f, TalkAudioLevel.pcm16Level(frame, frame.size), 1e-6f)
    assertEquals(0f, TalkAudioLevel.pcm16Level(frame, 0), 0f)
    assertEquals(0f, TalkAudioLevel.pcm16Level(frame, 1), 0f)
  }

  @Test
  fun smoothingMatchesIosWeighting() {
    assertEquals(0.2f, TalkAudioLevel.smoothed(previous = 0f, raw = 1f), 1e-6f)
    assertEquals(0.36f, TalkAudioLevel.smoothed(previous = 0.2f, raw = 1f), 1e-6f)
    assertEquals(0.8f, TalkAudioLevel.smoothed(previous = 1f, raw = 0f), 1e-6f)
  }

  private fun pcm16Frame(
    samples: Int,
    sample: Short,
  ): ByteArray {
    val frame = ByteArray(samples * 2)
    for (index in 0 until samples) {
      frame[index * 2] = (sample.toInt() and 0xff).toByte()
      frame[index * 2 + 1] = ((sample.toInt() shr 8) and 0xff).toByte()
    }
    return frame
  }
}

package ai.openclaw.app.voice

import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonObject
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Test

class ChatEventTextTest {
  private val json = Json { ignoreUnknownKeys = true }

  @Test
  fun extractsAssistantTextParts() {
    val payload =
      payload(
        """
        {
          "message": {
            "role": "assistant",
            "content": [
              { "type": "text", "text": "hello" },
              { "type": "text", "text": "world" }
            ]
          }
        }
        """,
      )

    assertEquals("hello\nworld", ChatEventText.assistantTextFromPayload(payload))
  }

  @Test
  fun preservesResponsesTextAndIgnoresTypedNonTextBlocks() {
    val payload =
      payload(
        """
        {
          "message": {
            "role": "assistant",
            "content": [
              { "type": "thinking", "text": "private reasoning" },
              { "type": "output_text", "text": "visible output" },
              { "type": "input_text", "text": "visible input" },
              { "type": "tool_result", "text": "tool payload" },
              { "text": "legacy visible" }
            ]
          }
        }
        """,
      )

    assertEquals(
      "visible output\nvisible input\nlegacy visible",
      ChatEventText.assistantTextFromPayload(payload),
    )
  }

  @Test
  fun extractsPlainStringContent() {
    val payload =
      payload(
        """
        {
          "message": {
            "role": "assistant",
            "content": "plain reply"
          }
        }
        """,
      )

    assertEquals("plain reply", ChatEventText.assistantTextFromPayload(payload))
  }

  @Test
  fun ignoresUserMessages() {
    val payload =
      payload(
        """
        {
          "message": {
            "role": "user",
            "content": [
              { "type": "text", "text": "do not speak" }
            ]
          }
        }
        """,
      )

    assertNull(ChatEventText.assistantTextFromPayload(payload))
  }

  @Test
  fun ignoresMessagesWithMissingRole() {
    val payload =
      payload(
        """
        {
          "message": {
            "content": [
              { "type": "text", "text": "do not speak" }
            ]
          }
        }
        """,
      )

    assertNull(ChatEventText.assistantTextFromPayload(payload))
  }

  @Test
  fun ignoresNonCanonicalAssistantRoles() {
    for (role in listOf("ASSISTANT", " assistant ")) {
      val payload =
        payload(
          """
          {
            "message": {
              "role": "$role",
              "content": "do not speak"
            }
          }
          """,
        )

      assertNull(ChatEventText.assistantTextFromPayload(payload))
    }
  }

  private fun payload(source: String): JsonObject = json.parseToJsonElement(source.trimIndent()) as JsonObject
}

package ai.openclaw.app.voice

import org.junit.Assert.assertEquals
import org.junit.Test

class PushToTalkRecognitionLadderTest {
  @Test
  fun api33StartsWithRawAudioThenFallsThroughInOrder() {
    assertEquals(
      listOf(
        PushToTalkRecognitionCandidate.RawAudioSegmented,
        PushToTalkRecognitionCandidate.SilenceSegmented,
        PushToTalkRecognitionCandidate.RestartingSingleSession,
      ),
      pushToTalkRecognitionCandidates(supportsSegmentedRecognition = true, first = null),
    )
  }

  @Test
  fun olderApisUseRestartingSingleSessionOnly() {
    assertEquals(
      listOf(PushToTalkRecognitionCandidate.RestartingSingleSession),
      pushToTalkRecognitionCandidates(supportsSegmentedRecognition = false, first = null),
    )
  }

  @Test
  fun degradedHoldNeverClimbsBackUpTheLadder() {
    assertEquals(
      listOf(
        PushToTalkRecognitionCandidate.SilenceSegmented,
        PushToTalkRecognitionCandidate.RestartingSingleSession,
      ),
      pushToTalkRecognitionCandidates(
        supportsSegmentedRecognition = true,
        first = PushToTalkRecognitionCandidate.SilenceSegmented,
      ),
    )
  }

  @Test
  fun rawSegmentedSessionEndAdvancesToSilenceButSilenceSessionEndRearms() {
    assertEquals(
      true,
      shouldAdvancePushToTalkRungAfterSegmentedSession(
        PushToTalkRecognitionCandidate.RawAudioSegmented,
      ),
    )
    assertEquals(
      false,
      shouldAdvancePushToTalkRungAfterSegmentedSession(
        PushToTalkRecognitionCandidate.SilenceSegmented,
      ),
    )
  }
}

package ai.openclaw.app.voice

import org.junit.Assert.assertEquals
