import java.util.concurrent.Executors
import java.util.concurrent.atomic.AtomicReference

@RunWith(RobolectricTestRunner::class)
@Config(sdk = [34])
@OptIn(ExperimentalCoroutinesApi::class)
class TalkAudioPlayerTest {
  private val context = RuntimeEnvironment.getApplication()

  @Before
  fun setUpPlayback() {
    Dispatchers.setMain(Dispatchers.Unconfined)
    ShadowMediaPlayer.setMediaInfoProvider { ShadowMediaPlayer.MediaInfo(60_000, 0) }
  }

  @After
  fun cleanUpPlayback() {
    speechFiles().forEach(File::delete)
    ShadowMediaPlayer.resetStaticState()
    Dispatchers.resetMain()
  }

  @Test
  fun resolvesPcmPlaybackFromOutputFormat() {
    val mode =
      TalkAudioPlayer.resolvePlaybackMode(
        outputFormat = "pcm_24000",
        mimeType = null,
        fileExtension = null,
      )

    assertEquals(TalkPlaybackMode.Pcm(sampleRate = 24_000), mode)
  }

  @Test
  fun resolvesCompressedPlaybackFromMimeType() {
    val mode =
      TalkAudioPlayer.resolvePlaybackMode(
        outputFormat = null,
        mimeType = "audio/mpeg",
        fileExtension = null,
      )

    assertEquals(TalkPlaybackMode.Compressed(fileExtension = ".mp3"), mode)
  }

  @Test
  fun preservesProvidedExtensionForCompressedPlayback() {
    val mode =
      TalkAudioPlayer.resolvePlaybackMode(
        outputFormat = null,
        mimeType = "audio/webm",
        fileExtension = "webm",
      )

    assertTrue(mode is TalkPlaybackMode.Compressed)
    assertEquals(".webm", (mode as TalkPlaybackMode.Compressed).fileExtension)
  }

  @Test
  fun cancelledCompressedPlaybackReleasesMediaPlayer() {
    val outcome = cancelCompressedPlayback()

    assertEquals(ShadowMediaPlayer.State.END, outcome.playerState)
  }

  @Test
  fun cancelledCompressedPlaybackDeletesPrivateSpeechFile() {
    val outcome = cancelCompressedPlayback()

    assertEquals(emptyList<String>(), outcome.remainingSpeechFiles)
  }

  @Test
  fun compressedPlaybackSetupFailureReleasesAllocatedMediaPlayer() =
    runBlocking {
      val createdPlayer = AtomicReference<MediaPlayer>()
      val createdShadow = AtomicReference<ShadowMediaPlayer>()
      ShadowMediaPlayer.setCreateListener { player, shadow ->
        createdPlayer.set(player)
        createdShadow.set(shadow)
      }
      ShadowMediaPlayer.setMediaInfoProvider { throw IllegalStateException("synthetic media initialization failed") }

      try {
        val failure = runCatching { TalkAudioPlayer(context).play(syntheticAudio()) }.exceptionOrNull()

        assertEquals("synthetic media initialization failed", failure?.message)
        assertEquals(ShadowMediaPlayer.State.END, checkNotNull(createdShadow.get()).state)
        assertEquals(emptyList<String>(), speechFiles().map(File::getName))
      } finally {
        runCatching { createdPlayer.get()?.release() }
        speechFiles().forEach(File::delete)
      }
    }

  @Test
  fun cancellationBeforeCreatedFileReturnsDeletesPrivateSpeechFile() =
    runBlocking {
      val dispatcher = Executors.newSingleThreadExecutor().asCoroutineDispatcher()
      val blockerScope = CoroutineScope(dispatcher)
      val callerBlocked = CountDownLatch(1)
      val releaseCaller = CountDownLatch(1)
      val player = TalkAudioPlayer(context)
      val playback =
        launch(dispatcher) {
          blockerScope.launch {
            callerBlocked.countDown()
            releaseCaller.await()
          }
          player.play(syntheticAudio())
        }

      try {
        withTimeout(5_000) {
          while (callerBlocked.count > 0 || speechFiles().isEmpty()) {
            delay(10)
          }
        }
        assertEquals(1, speechFiles().size)

        playback.cancel()
        releaseCaller.countDown()
        playback.join()

        assertEquals(emptyList<String>(), speechFiles().map(File::getName))
      } finally {
        releaseCaller.countDown()
        playback.cancelAndJoin()
        blockerScope.cancel()
        dispatcher.close()
        speechFiles().forEach(File::delete)
      }
    }

  private fun cancelCompressedPlayback(): CancelledPlaybackOutcome =
    runBlocking {
      val createdPlayer = AtomicReference<MediaPlayer>()
      val createdShadow = AtomicReference<ShadowMediaPlayer>()
      ShadowMediaPlayer.setCreateListener { player, shadow ->
        createdPlayer.set(player)
        createdShadow.set(shadow)
      }
      val player = TalkAudioPlayer(context)
      val playback = launch(Dispatchers.Default) { player.play(syntheticAudio()) }

      try {
        withTimeout(5_000) {
          while (createdShadow.get()?.state != ShadowMediaPlayer.State.STARTED) {
            delay(10)
          }
        }
        val activeFiles = speechFiles()
        assertEquals(1, activeFiles.size)

        playback.cancelAndJoin()

        CancelledPlaybackOutcome(
          playerState = checkNotNull(createdShadow.get()).state,
          remainingSpeechFiles = speechFiles().map(File::getName),
        )
      } finally {
        playback.cancelAndJoin()
        runCatching { createdPlayer.get()?.release() }
        speechFiles().forEach(File::delete)
      }
    }

  private fun speechFiles(): List<File> {
    val files = context.cacheDir.listFiles().orEmpty()
    return files.filter { it.name.startsWith("talk-audio-") }
  }

  private fun syntheticAudio(): TalkSpeakAudio =
    TalkSpeakAudio(
      bytes = byteArrayOf(1, 2, 3),
      provider = "test",
      outputFormat = null,
      voiceCompatible = null,
      mimeType = "audio/mpeg",
      fileExtension = null,
    )

  private data class CancelledPlaybackOutcome(
    val playerState: ShadowMediaPlayer.State,
    val remainingSpeechFiles: List<String>,
  )
}

package ai.openclaw.app.voice

import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test

class TalkDirectiveParserTest {
  @Test
  fun parsesDirectiveAndStripsHeader() {
    val input =
      """
      {"voice":"voice-123","once":true}
      Hello from talk mode.
      """.trimIndent()
    val result = TalkDirectiveParser.parse(input)
    assertEquals("voice-123", result.directive?.voiceId)
    assertEquals(true, result.directive?.once)
    assertEquals("Hello from talk mode.", result.stripped.trim())
  }

  @Test
  fun ignoresUnknownKeysButReportsThem() {
    val input =
      """
      {"voice":"abc","foo":1,"bar":"baz"}
      Hi there.
      """.trimIndent()
    val result = TalkDirectiveParser.parse(input)
    assertEquals("abc", result.directive?.voiceId)
    assertTrue(result.unknownKeys.containsAll(listOf("bar", "foo")))
  }

  @Test
  fun parsesAlternateKeys() {
    val input =
      """
      {"model_id":"eleven_v3","similarity_boost":0.4,"no_speaker_boost":true,"rate":200}
      Speak.
      """.trimIndent()
    val result = TalkDirectiveParser.parse(input)
    assertEquals("eleven_v3", result.directive?.modelId)
    assertEquals(0.4, result.directive?.similarity)
    assertEquals(false, result.directive?.speakerBoost)
    assertEquals(200, result.directive?.rateWpm)
  }

  @Test
  fun parsesAliasKeysCaseInsensitively() {
    val input =
      """
      {"Voice":"voice-abc","NoSpeakerBoost":true,"Language_Code":"en"}
      Speak clearly.
      """.trimIndent()
    val result = TalkDirectiveParser.parse(input)
    assertEquals("voice-abc", result.directive?.voiceId)
    assertEquals(false, result.directive?.speakerBoost)
    assertEquals("en", result.directive?.language)
    assertEquals(emptyList<String>(), result.unknownKeys)
  }

  @Test
  fun preservesAliasPriorityNullMaskingAndPrimitiveCoercion() {
    val input =
      """
      {"VOICE":"masked","voice":null,"voice_id":"  selected  ","MODEL":7,"model_id":" model ","speed":"1.25","rate":0,"stability":0,"similarity":"0.4","style":"0.0","speaker_boost":false,"no_speaker_boost":false,"seed":"42","normalize":" ","apply_text_normalization":" auto ","LANG":"masked","lang":null,"language_code":" en ","output_format":" pcm ","latency":"0","once":"yes","z":1,"A":2}
      Speak.
      """.trimIndent()

    val result = TalkDirectiveParser.parse(input)

    assertEquals(
      TalkDirective(
        voiceId = "selected",
        modelId = "model",
        speed = 1.25,
        rateWpm = 0,
        stability = 0.0,
        similarity = 0.4,
        style = 0.0,
        speakerBoost = false,
        seed = 42,
        normalize = "auto",
        language = "en",
        outputFormat = "pcm",
        latencyTier = 0,
        once = true,
      ),
      result.directive,
    )
    assertEquals("Speak.", result.stripped)
    assertEquals(listOf("A", "z"), result.unknownKeys)
  }

  @Test
  fun preservesExactKeyAndCaseCollisionOrdering() {
    val cases =
      listOf(
        "{\"VOICE\":\"first\",\"Voice\":\"second\"}" to "first",
        "{\"VOICE\":\"case-insensitive\",\"voice\":\"exact\"}" to "exact",
        "{\"voice\":\"primary\",\"voice_id\":\"secondary\"}" to "primary",
      )

    for ((json, expected) in cases) {
      val result = TalkDirectiveParser.parse("$json\nSpeak.")
      assertEquals(json, expected, result.directive?.voiceId)
    }
  }

  @Test
  fun preservesRejectedTextAndAcceptedWhitespaceExactly() {
    val rejected = "{\"unknown\":1}\r\nText\r\n"
    assertEquals(
      TalkDirectiveParseResult(directive = null, stripped = rejected, unknownKeys = emptyList()),
      TalkDirectiveParser.parse(rejected),
    )

    val accepted = "\r\n\r\n{\"voice\":\"v\"}\r\n\r\nHello\r\n"
    assertEquals(
      TalkDirectiveParseResult(
        directive = TalkDirective(voiceId = "v"),
        stripped = "\n\nHello\n",
        unknownKeys = emptyList(),
      ),
      TalkDirectiveParser.parse(accepted),
    )
  }

  @Test
  fun returnsNullWhenNoDirectivePresent() {
    val input =
      """
      {}
      Hello.
      """.trimIndent()
    val result = TalkDirectiveParser.parse(input)
    assertNull(result.directive)
    assertEquals(input, result.stripped)
  }
}

