    tracker.adoptSnapshot(null, 4)

    assertEquals(listOf(5L, 6L), replay.map(WearInboundEvent::sequence))
    assertTrue(replay.all { tracker.accept(it.streamId, it.sequence) == WearSequenceDecision.Accepted })
